quests[9747] = { id = 9747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Umbrafennstamm", description = "Die Naga sind furchtbar, ja. Aber noch schlimmer sind die verräterischen Stämme der Zerschlagenen und der Verirrten, die ihnen geholfen haben!\n\nDie schlimmsten von allen sind die Verirrten des Umbrafennstamms. Sie benutzen dunkle Magie, um andere zu fangen und zu versklaven. Sie sind besonders grausam zu entflohenen Sklaven und würden mir die Kehle durchschneiden, wenn ich die Zuflucht auch nur für einen Tag verlassen würde.\n\nReist nach Umbrafenn im Süden und tötet sie und ihren Anführer, Kataru. Bis dahin werde ich jeden Tag um mein Leben bangen.", sourceObjective = "Ikeyen in der Zuflucht des Cenarius möchte, dass Ihr nach Umbrafenn reist und Kataru, 8 Seher von Umbrafenn, 6 Hexendoktoren von Umbrafenn und 6 Orakel von Umbrafenn tötet.", completion = "Danke, {name}. Endlich werde ich nachts ruhig schlafen können. Wäre ich nicht so alt und schwach, würde ich mich selbst mit meinen Feinden auseinandersetzen.\n\nNehmt dieses Gold. Es ist nicht viel, aber Eure Freundlichkeit darf nicht unbelohnt bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9748] = { id = 9748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkt nicht das Wasser", description = "Unser Schamane bekundet, dass die Wasserelemente durch die Verschmutzung der Wasserquelle sehr stark aus dem Gleichgewicht geraten sind. Wir wissen, dass der Kraftkern der Exodar im westlich gelegenen Berg liegt. Offenbar entweicht von dort eine flüchtige Substanz in die Wasserzufuhr! Ihr müsst für mich mehr Informationen sammeln.\n\n<Aesom deutet auf einen Behälter und nickt.>\n\nNehmt diesen Behälter und folgt dem Strand Richtung Norden bis Ihr auf den Punkt trefft, an dem die Flüsse der Blutmythosinsel in das Meer fließen. Entnehmt an dieser Stelle eine Probe und kehrt zu mir zurück.", sourceObjective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr den Wasserprobenbehälter verwendet, um eine Wasserprobe der Blutmythosinsel zu entnehmen.", progress = "Trinkt nicht das Wasser, {name}!", completion = "Wie ich vermutet habe, ist das Wasser von der Verseuchung durch die austretende Kernflüssigkeit rot geworden.\n\nIch hoffe, dass Ihr nicht in dem verseuchten Wasser geschwommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9749] = { id = 9749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie leben! Vielleicht...", description = "Es war ein blutiges Gemetzel, {name}. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!", sourceObjective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[9751] = { id = 9751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Blutfluchs", description = "Letzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich der Blutwacht liegt, suchen?", sourceObjective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9752] = { id = 9752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Umbrafenn", description = "Ihr müsst mir helfen hier rauszukommen!\n\nIch habe in der Nähe Kräuter gesammelt, als ein paar dieser Wilden mich entführten. Ich habe versucht mich loszureißen, aber es waren zu viele.\n\nHelft mir zurück zur Zuflucht des Cenarius und weg von diesen grausamen Schuften und ihrer bösen Magie zu gelangen!", sourceObjective = "Begleitet Kayra Langmähne zur Zuflucht des Cenarius in den Zangarmarschen. Gebt Ysiel Windsänger Bescheid, sobald Ihr diese Aufgabe erledigt habt.", completion = "Ihr habt einen meiner Druiden gerettet. Das könnten wir Euch niemals zurückzahlen, {name}.\n\nIhr habt meinen Dank sowie den Dank der Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[9753] = { id = 9753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir wissen...", description = "Wir haben in den vergangenen Tagen viel über unsere Feinde gelernt. Die Blutelfen werden von einer gewissen Sironas angeführt und haben vor, uns zu zerstören. Letztendlich wollen sie noch O'ros versklaven und wieder die Kontrolle über die Exodar gewinnen.\n\nDem Licht sei Dank, konnten wir ihre Versorgungszufuhr abschneiden, indem wir das Sonnentor zerstörten. Sie verwenden jedoch die Verunreinigung der Vektorspule, um das Land zu vergiften, und nutzen somit dessen mutagene Eigenschaften zu ihrem Vorteil.\n\nAdmetius hat auf Grund dieser Informationen einen Plan ausgeklügelt. Geht zu ihm.", sourceObjective = "Sprecht mit Exarch Admetius bei der Blutwacht.", completion = "Ich brauche Eure Hilfe, {name}. Es ist mein Plan, die gesamte Armee der Sonnenfalken zu stürzen. Zuvor gilt es jedoch ein paar grundlegende Informationen zu sammeln.\n\nWir müssen die Schwäche ihrer Verteidigung ausmachen. Unglücklicherweise ist es uns bis jetzt noch nicht gelungen, nahe genug an die Vektorspule heranzukommen und ihre Verteidigung auszukundschaften. Wenn wir den Gefangenen zum Sprechen bringen könnten, würden wir womöglich die Informationen bekommen, die wir brauchen, um durch ihre Verteidigung zu brechen und die Vektorspule zu zerstören.\n\nIhr habt richtig gehört, ich will das verdammte Ding in die Luft jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9756] = { id = 9756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir nicht wissen...", description = "Unsere Vernehmungsversuche sind kläglich gescheitert, {name}. Folter kommt - natürlich - nicht in Frage. Was wir brauchen, ist <ein/eine:r> {race}, <der/die:r> an ihn herankommen kann.\n\nIch kann einen Zauber auf Euch wirken, der Euch wie <einen Blutelfen/eine Blutelfe> aussehen lässt und Eure Sprache anpasst. Mit dieser List werden wir vielleicht die benötigten Informationen von dem gefangenen Agenten bekommen.\n\nIch möchte, dass Ihr Euch mithilfe dieser Verkleidung das Wissen des Gefangenen erschleicht.\n\nUnd {name}, verlasst die Blutwacht nicht, solange Ihr verkleidet seid, da sonst der Zauber aufgehoben wird.", sourceObjective = "Sprecht mit einem gefangenen Agenten der Sonnenfalken bei der Blutwacht und eignet Euch Informationen der Sonnenfalken an. Kehrt zu Exarch Admetius zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = "Kehrt erst wieder zurück, wenn Ihr erfolgreich gewesen seid!", completion = "A-ha! Gut gemacht, {name}. Wirklich sehr gut gemacht. Seid Ihr bereit der Blutelfenbedrohung unserer Insel nun endlich ein Ende zu bereiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9757] = { id = 9757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Jägerin Kella Nachtbogen auf", description = "Jägerin Kella Nachtbogen hat um eine Audienz mit allen qualifizierten Jägern gebeten. Sie lehrt das Zähmen von wilden Tieren, etwas, das Ihr vor allem anderen zum jetzigen Zeitpunkt Eurer Ausbildung lernen solltet.\n\nIhr findet Kella in der Nähe von Valaars Steg, den Docks westlich der Exodar.", sourceObjective = "Sprecht mit Jägerin Kella Nachtbogen nahe Valaars Steg.", completion = "Lasst uns sofort mit der Ausbildung beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9758] = { id = 9758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Arkanist Vandril", description = "Nun, <mein Freund/meine Freundin>, wenn Ihr so nett wärt, zu Arkanist Vandril zurückzukehren? Ich weiß, er ist begierig, Euch auf Eure erste Mission hier in den Geisterlanden zu senden.\n\nWir zählen auf Euch, {name}. Enttäuscht uns nicht.", sourceObjective = "Kehrt zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Ah, gut, da seid Ihr ja. Und gerade zur rechten Zeit, es gibt viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9759] = { id = 9759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Welt enden lassen", description = "Nehmt diesen Auftrag nicht an, wenn Euch etwas an Eurem Leben liegt. Seht Ihr den gigantischen Kraftkern, der aus der Seite des Bergs dort drüben hervorragt? Wer auch immer diese Last auf sich nehmen möchte, muss sich seinen Weg durch den Berg kämpfen und eine Armee der Sonnenfalken abwehren, um mich zu beschützen, während ich die Zerstörung des Kerns vorbereite. Sironas der Eredar ist auch irgendwo dort oben.\n\nIch werde Euch nicht weniger schätzen, wenn Ihr jetzt einfach geht, {name}.\n\nVielleicht seid Ihr aber genau die Person, die die Vektorspule zerstören und Sironas zu Fall bringen kann. Seid Ihr es?", sourceObjective = "Folgt und beschützt Demolierer Legoso, während er versucht, die Vektorspule zu zerstören und tötet Sironas. Kehrt zu Exarch Admetius bei der Blutwacht zurück, sobald Ihr Eure Aufgabe erfüllt habt.", completion = "Ihr habt die ganze Blutmythosinsel und Azurmythosinsel gerettet, das Leben der {race} in Azeroth gesichert, {name}! Dafür wird man Euch niemals genug danken können, keine Belohnung, nichts ist groß genug, um Euch unsere Anerkennung zu zeigen.\n\nLeider blieben noch so viele auf Draenor zurück, die dieses historische Ereignis nicht miterleben können. Ihr müsst Euren Weg zurückfinden. Findet Euren Weg zur Scherbenwelt, Held von Argus. Bringt Eure Leute nach Hause. Nach Hause in das Land, das Ihr gerettet habt. Nach Azeroth...", sourceObjectiveStatus = "unverified-source-field" }
quests[9760] = { id = 9760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigers Ruh'", description = "Ich würde Euch nicht bitten, die Vektorspule und Sironas im Alleingang zu vernichten, {name}, dennoch glaube ich, dass Ihr uns helfen könnt, den Weg für andere abzusichern, die solch einen gefährlichen Auftrag auf sich nehmen werden.\n\nNehmt die Straße, die nördlich aus der Blutwacht führt, und folgt dem Verlauf bis Ihr auf die Weggabelung stoßt. Biegt auf die linke Straße ab und geht solange weiter bis Ihr zu Verteidigers Ruh' kommt - es liegt leicht westlich von der Straße selbst. Corin wird dort auf Euch warten.", sourceObjective = "Sprecht mit Verteidigerin Corin bei Verteidigers Ruh' auf der Blutmythosinsel.", completion = "Vielleicht verhelft Ihr unserem Volk ja zu einem neuen Zeitalter des Wohlstands und des Friedens.", sourceObjectiveStatus = "unverified-source-field" }
quests[9761] = { id = 9761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Nur die wirklich Kampferprobten, Edelmütigen und Furchtlosen werden sich Legosos Auftrag stellen. Der Exarch wird keinen Agenten der Hand damit beauftragen, die Vektorspule zu zerstören und Sironas zu stürzen. Er lehnt es ab, Draenei in ihren Tod zu schicken - genau darum geht es bei diesem Auftrag: Selbstmord...\n\n<Corin seufzt.>\n\nIch bin dafür verantwortlich, die Verteidigung der Sonnenfalken zu schwächen. Eure Aufgabe besteht darin, Sonnenfalken nahe der Vektorspule zu töten und somit den Weg für unseren Helden frei zu machen - wer immer es auch sein mag.", sourceObjective = "Verteidigerin Corin bei Verteidigers Ruh' möchte, dass Ihr 8 Saboteure der Sonnenfalken und 8 Agenten der Sonnenfalken tötet.", completion = "Hoffentlich meldet sich bald ein Held, bevor sie Verstärkung anfordern können, um die gerade von Euch abgesicherte Gegend zu bewachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9762] = { id = 9762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungeschriebene Prophezeiung", sourceObjective = "Diese Inseln werden für Tausende ein Zuhause sein. Die meisten werden ihr gesamtes Leben hier verbringen. Ihr könntet das auch, aber es ist nicht, was Ihr wollt, oder {name}?\n\n\n\nIhr werdet in Eurem Leben noch viele großartige Taten vollbringen. Ihr müsst Euer Schicksal umarmen und es willkommen heißen!\n\nBevor Ihr geht, möchte ich Euch noch zwei Geschenke überreichen: Dieser Wappenrock wird nur von denen getragen, die den höchsten Respekt der Hand von Argus genießen; und nur die Weisesten besitzen diesen Siegelring. Tragt beides mit Stolz, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9763] = { id = 9763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteck des Kriegsherren", description = "Es hat Vorteile, sich heimlich am Eingang zum Versteck des Feindes zu verstecken.\n\nVor ein paar Stunden sah ich eine Gruppe von Naga durch den steinernen Torbogen am zweiten Tunnel von links gehen. Ich bin in ihrer Sprache nicht sehr bewandert, aber ein Wort habe ich sehr deutlich verstanden: Kalithresh.\n\nDas muss der Eingang zu den Dampfkammern sein, von denen aus Kriegsherr Kalithresh seine Truppen befehligt. Ihr müsst ihn finden und aufhalten! Ich bin leider zu schwach, um Euch dabei helfen zu können.", sourceObjective = "Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet.", completion = "Unser größter Feind in der Gegend ist endlich tot. Ihr habt der Expedition einen sehr großen Gefallen getan, {name}.\n\nWir stehen auf ewig in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[9764] = { id = 9764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Lady Vashj", description = "Dieser Brief enthält genaue Anweisungen für die Naga des Echsenkessels, die die Dampfpumpen bedienen. Er enthält eine Warnung vor der Ankunft von Druiden des Cenarius in dem Gebiet und die Anweisung, sie unverzüglich zu töten. Die Geschwindigkeit, mit der das Wasser aus den Seen in den Echsenkessel abgepumpt wird, soll verdoppelt werden. Die Befehle tragen das Siegel der berüchtigten Lady Vashj.\n\nDieser Brief dürfte die Druiden der Expedition des Cenarius sehr interessieren. Bringt ihn zur Leiterin der Expedition, Ysiel Windsänger.", sourceObjective = "Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Was habt Ihr da, {name}?", completion = "Vashj!\n\nDamit haben wir nicht gerechnet. Unsere kleinen Siege gegen die Naga hier und da sind also bedeutungslos.\n\nWenn Lady Vashj darin verwickelt ist, dann sind viel stärkere Mächte am Werk, als wir es sind.\n\nEs war eine gute Entscheidung, den Brief zu uns zu bringen, {name}. Nun müssen wir uns auf einen Krieg vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9765] = { id = 9765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitungen", description = "Die Expedition des Cenarius fing einst als friedliches Projekt an, doch nun stehen wir am Rande eines ausgewachsenen Kriegs gegen die Naga.\n\nUnter uns sind einige, die zwar gerne kämpfen würden, aber nur sehr schlecht ausgerüstet sind. Bringt mir die Waffen der Naga, damit wir sie zu Gleven und Pfeilspitzen umschmelzen können.\n\nNur Waffen aus hochwertigem Material können für uns nützlich sein, {name}. Ihr werdet die der Naga im Echsenkessel stehlen müssen.", sourceObjective = "Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", progress = "Habt Ihr die Waffen, die ich benötige, schon besorgt, {name}?", completion = "Sie eignen sich perfekt, {name}. Bringt mir alle Waffen, die Ihr nur finden könnt. Unser Bedarf ist groß und unsere Mittel sind wenige.", sourceObjectiveStatus = "unverified-source-field" }
quests[9766] = { id = 9766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Echsenkessels", progress = "Wir werden den eigenen Stahl der Naga in Waffen gegen sie umschmieden. Bringt mir alle Waffen, die Ihr aus dem Echsenkessel besorgen könnt.", completion = "Ausgezeichnete Arbeit, {name}. Die Naga werden schon lernen, dass sie uns nicht unterschätzen sollten!" }
quests[9767] = { id = 9767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind kennen", description = "Um einen Feind zu besiegen braucht man weit mehr als eine Überzahl an Männern oder Kraft. Oft hängt der Sieg davon ab, ob man die Schwächen des Feindes oder seine typischen Vorgehensweisen kennt.\n\nWir wissen zwar viel über die Naga, aber ihre Magie bleibt uns immer noch fremd.\n\nIch habe vor, mich mit der Hydromantie der Naga des Echsenkessels auseinanderzusetzen. Bringt mir eines ihrer Zauberbücher, damit ich mehr darüber erfahren kann.", sourceObjective = "Besorgt ein Zauberbuch des Echsenkessels von den Naga im Echsenkessel und bringt es zu Ashyen in der Zuflucht des Cenarius in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9769] = { id = 9769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mode kann man nicht erklären", description = "<Magasha kichert still in sich hinein.>\n\nIch wette, wenn sie wüssten, dass sie Insektenteile anhaben, wäre der Trend schnell vorbei.\n\nZuerst haben wir angefangen, die Insekten in der Umgebung zu töten, weil sie bei den Bauarbeiten im Weg waren. Eines Tages kam ein geschäftstüchtiger Händler hierher, blieb über Nacht und plötzlich fing er an alle Insektenflügel, die er bekommen konnte, aufzukaufen!\n\nSagte, er mache Kleidung daraus. Ich bleib lieber bei meiner Rüstung, danke. Aber wenn Ihr die Flügel der Glühwürmchenarten in der Umgebung sammelt, kaufe ich sie Euch gerne ab.", sourceObjective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Magasha im Sumpfrattenposten.", progress = "Was ist los? Hat Euch jemand die Flügel gestutzt?\n\n<Magasha kichert über ihren Witz.>", completion = "Die sind fein, {name}. Hier ist Eure Bezahlung.\n\n\n\nNe, nicht mein Fall, aber ich hab ja auch keine Ahnung von Mode.\n\n\n\nEs ist das Geld, was zählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9770] = { id = 9770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Marschenfänge", description = "Manchmal wünschte ich, Denjai hätte uns einen Schamanen mitgeschickt oder uns wenigstens ein Totem gegeben, um die Marschfangreißer fernzuhalten.\n\nEs wimmelt hier nur so von diesem Ungeziefer! Das ist doch nicht gerecht. Sollte nicht irgendwas diese widerlichen Käfer auffressen?\n\nWir haben alle schon abwechselnd Kammerjäger gespielt. Ihr seid genau zur richtigen Zeit gekommen, {name}. Glückwunsch! Und jetzt geht los und wischt ein paar Marschfänge auf!", sourceObjective = "Reavij im Sumpfrattenposten möchte, dass Ihr 10 Marschfangreißer tötet.", completion = "Schon satt?\n\n<Reavij lacht.>\n\nEs gibt einen Grund warum unsere Besucher nicht lange bleiben.\n\nWenn ich eine Wahl hätte, würde ich einen angenehmeren Ort für den Posten auswählen. Aber ich ziehe die Marschfänge immer noch Denjais Launen vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[9771] = { id = 9771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Späher Jyoba", description = "Jetzt, da Ihr mit dem Gelände vertraut seid, würde ich Euch gerne bei einer anderen Sache um Hilfe bitten. Das Todesmoor, so nennen wir das Gebiet im Nordwesten, ist ein schauriger Ort. Niemand hat dort je ein Lebewesen gesehen, aber es war auch nie jemand lange dort.\n\nSpäher Jyoba hat sich freiwillig gemeldet, um das Gebiet zu untersuchen und von seinen Beobachtungen zu berichten. Er hat den Posten vor drei Tagen verlassen und ist noch nicht zurückgekehrt. Er würde nie so lange wegbleiben ohne einen Bericht zu schicken. Könntet Ihr nach ihm suchen, {name}?", sourceObjective = "Sucht Späher Jyoba im Todesmoor in den Zangarmarschen.", completion = "Diese in Mitleidenschaft gezogene Leiche passt genau zu Zurais Beschreibung. Was auch immer den Späher getötet haben mag, muss ihn überrascht haben, da er seine Waffen nicht gezogen hatte und Tintenflecken auf dem Boden zu sehen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9772] = { id = 9772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jyobas Bericht", description = "Fetzen von welkem Pilz befinden sich überall auf dem Körper von Späher Jyoba. Was auch immer ihn getötet hat muss aus demselben siechenden Pilz bestehen wie die riesigen welkenden Pilze des Todesmoors. Vielleicht hat ihn einer der siechenden Riesen überrascht, als er gerade seinen Bericht schreiben wollte.\n\nOhne den Text des Berichts ist es fast unmöglich herauszufinden, was der Späher entdeckt hat. Wenn der Bericht gefunden werden könnte, sollte er unbedingt zu Zurai gebracht werden.", sourceObjective = "Besorgt Späher Jyobas Bericht von den siechenden Riesen und kehrt dann zu Zurai im Sumpfrattenposten zurück.", progress = "Ihr seid zurück, aber Jyoba ist nicht bei Euch. Was ist mit ihm passiert?", completion = "<Zurai nimmt den Bericht von Euch und schaut ihn sich an.>\n\nViele von diesen Informationen sind uns bereits bekannt. Alles in dieser Gegend scheint ausgetrocknet oder am verwelken zu sein, aber hier steht etwas neues.\n\nEr sagt, die Fungusgiganten sind von dem Wassermangel wahnsinnig geworden. Eurer Beschreibung nach muss es einer von ihnen gewesen sein, der ihn umgebracht hat.\n\nIch werde meinen Männer anweisen, die Gegend zu meiden. Wir können uns keine weiteren Verluste erlauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9773] = { id = 9773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Pilze mehr!", description = "Pilzsuppe, Pilzeintopf, Pilzsoße!\n\nPilze, Pilze, Pilze! Was anderes bekommt man hier nicht zu essen. Wenn man sagt, dass man Hunger hat, drückt der Koch einem eine Axt in die Hand und sagt: Schlag Dir Dein Abendessen selbst!\n\nNun, ich habe Pilze satt. Ich habe Fische in den Seen hier gesehen. Klar, sie sehen aus, als würden sie sich wehren, aber sie müssen einfach besser schmecken als Pilze!\n\nWie viel würde es mich kosten Euch zu beauftragen, mir mein erstes anständiges Abendessen seit Wochen zu bringen?", sourceObjective = "Bringt 8 Aalfilets von Umbrafennaalen zu Magasha im Sumpfrattenposten.", progress = "Bitte sagt mir nicht, dass Ihr mit leeren Händen zurückgekommen seid, {name}.", completion = "Endlich, eine Abwechslung zu den Pilzen! Wenn Ihr nicht nach Fisch riechen würdet, würde ich Euch umarmen.\n\nWollen wir mal schauen, wie neidisch die anderen werden, wenn sie meinen gebratenen Fisch riechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9774] = { id = 9774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Hydraschuppen", description = "Es war sehr klug von Reavij Lederrüstung mitzubringen. Der Sumpf wird meine Panzerrüstung innerhalb von kurzer Zeit wertlos machen.\n\nIch habe schon so weit ich konnte nach und nach alle Schuppen ausgetauscht. Die Hydras in dem Marschen haben dicke, schützende Schuppen, die der Feuchtigkeit ihrer Heimat optimal standhalten.\n\nGeeignete Schuppen zu finden ist allerdings ziemlich langwierig. Oftmals sind sie zu kaputt, zu abgenutzt oder zu dünn um sie als Rüstung zu verwenden. Bringt mir ein paar geeignete Schuppen von den Hydras in den größeren Seen.", sourceObjective = "Bringt 12 dicke Hydraschuppen zu Zurai im Sumpfrattenposten.", progress = "Ich sehe, dass Ihr grinst. Ja, meine Rüstung wird etwas merkwürdig aussehen, bis ich das ganze alte Metall ersetzt habe, aber besser so als ungeschützt.", completion = "Danke, {name}. Jedes noch so kleine bisschen hilft.\n\nEs ist immer noch viel zu tun, aber mal ehrlich, was soll ich sonst zwischen den Patrouillen machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9775] = { id = 9775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Schattenjäger Denjai", description = "Schattenjäger Denjai erwartet sicher einen Bericht über meine Fortschritte bei der Errichtung unseres Außenpostens. Ich habe eine Zusammenfassung unserer bisherigen Errungenschaften vorbereitet, aber seit wir Späher Jyoba verloren haben, kann ich keinen Boten entbehren, um den Bericht zu Denjais Posten Zabra'jin im Westen zu bringen.\n\nWenn Ihr in die Richtung geht, könntet Ihr ihm den Bericht vielleicht von mir geben? Schattenjäger Denjai kann auf den ersten Blick etwas einschüchternd wirken, aber wenn Ihr Euch an ihn gewöhnt habt, ist er kein übler Kerl.", sourceObjective = "Bringt Zurais Bericht zu Schattenjäger Denjai in Zabra'jin in den Zangarmarschen.", progress = "Ihr seht nicht aus wie einer meiner Männer. Was wollt Ihr, {race}?", completion = "Warum habt Ihr nicht gleich gesagt, dass Ihr einen Bericht von Zurai habt? Ich warte schon auf Nachricht von ihm.\n\nIch habe ihn nach Osten geschickt, damit er dort einen Posten baut, nicht um auf den Händen zu sitzen. Wollen wir mal sehen, was er zu sagen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9776] = { id = 9776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oreborzuflucht", description = "Wie Ihr sicher wisst, sind viele Einwohner von Telredor Flüchtlinge aus dem Krieg, der die Draenei dezimiert hat. Es ist mein Ziel, Telredor als sicheren Hafen für all unsere Verbündeten in diesem Kampf zu gewinnen. Es gibt einige, die sich uns gerne anschließen möchten, aber spüren, dass sie noch nicht bereit sind.\n\nWir schulden ihnen jede Hilfe, die wir ihnen bieten können, {name}. Eine Gruppe von Zerschlagenen unter der Führung von Ikuti hat in den Ruinen eines alten Tempels nordwestlich vom Schlangensee Zuflucht gefunden. Sucht sie und reicht ihnen Eure Hand in Freundschaft.", sourceObjective = "Sprecht mit Ikuti in der Oreborzuflucht in den Zangarmarschen.", completion = "Wenn Anachoret Ahuurn Euch als Freund betrachtet, kann ich Euch vielleicht vertrauen. Bitte vergebt mir meinen Argwohn, {race}, doch oft rettet nur dieser mein Volk vor dem Tod. Seid in unserer Zuflucht willkommen. Vielleicht wird so unser gegenseitiges Vertrauen wachsen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9777] = { id = 9777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fulgorsporen", description = "Es gibt nur wenig Brennbares in diesem Sumpf, {race}, daher müssen wir auf andere Mittel zugreifen, um Telredor zu erleuchten. Viele Tiere und Pflanzen in den Marschen strahlen ein schwaches Leuchten aus.\n\nEs ist schwierig und grausam die leuchtenden Tiere einzusperren, deshalb haben wir uns einen Pilz als Lichtquelle gesucht.\n\nWir bauen die Fulgorpilze hier an, aber ab und zu benötigen wir auch neue Pflanzen. Die kleinen grünen Pilze wachsen an den größeren in der Nähe von Telredor.", sourceObjective = "Bringt 6 Fulgorsporen zu Ruam in Telredor.", progress = "So wie es aussieht brauchen wir sehr bald neue Sporen.", completion = "Diese Sporen sind sehr gut und sollten uns für einen Weile reichen. Vielen Dank für Eure Hilfe bei der Aufstockung unserer Vorräte, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9778] = { id = 9778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Hamuht", description = "Sprecht auf jeden Fall noch mit Aufseher Hamuht, bevor Ihr die Zuflucht des Cenarius verlasst. Er ist für die Sicherheit der Expedition verantwortlich.\n\nEr würde mir nie verzeihen, wenn ich einen erfahrenen Abenteurer wie Euch nicht zu ihm schicken würde.", sourceObjective = "Meldet Euch bei Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Ysiel hat Euch geschickt? Natürlich habe ich für jemanden wie Euch Verwendung! Wir können immer ein paar Muskeln brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9779] = { id = 9779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfangen der Nachricht", description = "Schön, Euch wiederzusehen, {name}. Ich hätte da eine heikle Aufgabe, die es zu lösen gilt.\n\nUnsere Agenten, die die Sonnenfalken ausspionieren, haben berichtet, dass Soldaten der Sonnenfalken ein ungewöhnliches Dokument untersucht haben.\n\nUnglücklicherweise konnten wir keine Kopie dieses Schreibens für uns selbst beschaffen. Ihr müsst für mich vor Ort gehen und das Dokument an Euch bringen. Ich bin mir sicher, dass Euch ein Sonnenfalke die von uns gesuchten Informationen geben wird, wenn Ihr genug Druck anwendet. Ich überlasse den Einsatz von Gewalt voll und ganz Eurem Ermessen.", sourceObjective = "Tötet die Elfen der Sonnenfalken, bis Ihr das Schreiben der Sonnenfalken findet, und bringt es zu Verteidiger Boros bei der Blutwacht.", progress = "Schon zurück? Konntet Ihr das Schreiben finden?", completion = "<Verteidiger Boros betrachtet das Dokument.>\n\nDas ist Thalassisch. Glücklicherweise kenne ich eine Person, die es übersetzen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[9780] = { id = 9780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalfilets von Umbrafenn", description = "Schön, ein neues Gesicht hier zu sehen. Als Haalrun und ich nach Telredor kamen, waren wir die ersten von außerhalb, aber das scheint schon eine Ewigkeit her zu sein.\n\nTrotzdem heißen wir Neuankömmlinge immer willkommen und versuchen dafür zu sorgen, dass alle genug zu essen haben. Wir werden die Freundlichkeit der Anachoreten von Telredor niemals vergelten können, aber wir können ihrem Beispiel folgen und ebenso freundlich zu anderen sein.\n\nWenn Ihr helfen möchtet, dann fangt ein paar der Fische, die sich in den Seen in der Gegend tummeln. Sie heißen Umbrafennaale und sind Hauptbestandteil unserer Nahrung.", sourceObjective = "Bringt 8 Aalfilets zu Noraani in Telredor.", progress = "Habt Ihr schon Fische für unsere Vorräte besorgt?", completion = "Danke für Eure Hilfe, {name}. Euer Großmut wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9781] = { id = 9781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Mäuler zu stopfen", description = "Auf meiner letzten Jagd habe ich gesehen, dass eine Gruppe von Trollen im Begriff ist, einen neuen Außenposten zu bauen. Ohne Zweifel haben sie auch angefangen, hier zu jagen.\n\nWenn sie einen dauerhaften Standort hier errichten, wird es einen erbitterten Kampf um Nahrung geben. Wir können sie nicht direkt angreifen, ohne sie zu provozieren. Aber wir können unsere natürlichen Wettbewerber im Nahrungskampf reduzieren.\n\nJede Morasthydra, die Ihr erlegt, bedeutet drei Mäuler weniger, die gestopft werden müssen!", sourceObjective = "Tötet 10 Morasthydras und kehrt zu Haalrun in Telredor zurück.", completion = "Gut gemacht. Das sollte den Bedarf an Nahrung in der Gegend für die nahe Zukunft etwas mindern, auch wenn wir immer noch nach neuen Nahrungsquellen suchen sollten.. Fisch und Pilze reichen aus, aber etwas Abwechslung sollte nicht unterschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9782] = { id = 9782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Todesmoor", description = "Ich lebe nun seit einiger Zeit bei den Anachoreten von Telredor, {name}, und inzwischen kenne ich die Marschen ganz gut. In letzter Zeit habe ich eine erschreckende Veränderung des Landes im Nordosten bemerkt.\n\nFast alles Leben dort hat begonnen zu welken und zu sterben, und das scheinbar ohne Grund. Ich habe ein paar Vermutungen, was dort vorgehen könnte, aber sie sind nur sehr vage. Wenn Ihr mir eine Bodenprobe dieser Gegend bringen könntet, dann könnte ich diesem Rätsel vielleicht auf den Grund kommen.", sourceObjective = "Bringt eine Erdprobe vom Todesmoor zu Verteidiger Idaar in Telredor.", progress = "Konntet Ihr eine Probe der Erde des Todesmoors bekommen?", completion = "Hmm... der Boden ist nicht ausgelaugt, das kann also nicht der Grund für das Problem sein, wie ich zuerst vermutet habe. Wo liegt die Verbindung? Warum stirbt alles so plötzlich?", sourceObjectiveStatus = "unverified-source-field" }
quests[9783] = { id = 9783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unnatürliche Dürre", description = "Die Erdprobe, die Ihr mir gebracht habt, ist fast ausgetrocknet, {name}. Wenn schon der Boden seine Feuchtigkeit verliert, müssen die Lebewesen im Todesmoor furchtbar leiden.\n\nIch habe gesehen, was passiert, wenn die Fungusgiganten der Gegend anfangen zu welken und zu sterben. Der Schmerz macht sie wahnsinnig und bringt sie dazu, alles in ihrer Nähe anzugreifen.\n\nDiese Lebewesen haben nicht die leiseste Ahnung, was mit ihnen geschieht. Sie zu retten liegt außerhalb unserer Macht. Das Einzige, was wir tun können, ist ihr Leiden zu beenden.", sourceObjective = "Verteidiger Idaar in Telredor möchte, dass Ihr 12 siechende Riesen tötet.", completion = "Danke für Eure Hilfe bei dieser schweren Aufgabe, {name}. Unsere Arbeit im Todesmoor ist noch nicht beendet, aber nun können wir uns darauf konzentrieren, das Gleichgewicht in der Gegend wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9784] = { id = 9784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzenteile identifizieren", progress = "Ich könnte noch mehr Pflanzenteile brauchen. Jetzt, da die Seen ihr Wasser verlieren, befürchte ich, dass die fremden Arten zunehmen werden. Ich brauche aber mehr Beweise, um meine Theorie zu untermauern.", completion = "Ausgezeichnet. Wenn Ihr noch mehr Pflanzenteile findet, bringt sie zu mir.\n\n<Diese Quest kann wiederholt werden, bis Ihr den Ruf Wohlwollend' erlangt habt.>" }
quests[9785] = { id = 9785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Uralten", description = "Ihr habt Euch das Vertrauen der Expedition des Cenarius verdient, {name}. Es ist an der Zeit, dass Ihr Euch mit den Urtumen unterhaltet, die sich unserer Sache angeschlossen haben, Ashyen und Keleth, und um ihren Segen bittet.\n\nDas Zeichen eines Urtums zu tragen bedeutet große Macht. Je höher Euer Ansehen bei uns steigt, umso wertvoller wird dieser Gefallen werden.\n\nGeht, {name}, und bittet die Urtume um ihren Segen.", sourceObjective = "Windruferin Schwarzhuf möchte, dass Ihr mit den Urtumen Ashyen und Keleth in der Zuflucht des Cenarius sprecht und um ihren Segen bittet.", completion = "Ihr seid zurück. Habt Ihr den Segen der Uralten erhalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9786] = { id = 9786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Boha'mu", description = "Bevor mein Volk von den Orcs dezimiert wurde, diente Telredor als Zuflucht für die Anachoreten und Spiritualisten der Draenei. Ein kleiner Orden von Anachoreten und Verteidigern pflegte ein paar Schreine in dieser Region.\n\nWährend des Krieges verloren wir den Kontakt zu den Anachoreten, die für diese Schreine zuständig waren, besonders zu denen im Tempel von Boha'mu im Südwesten. Ich habe gehört, dass ein Stamm von Verirrten sich in dieser Gegend niedergelassen hat und vielleicht sogar in den Ruinen lebt. Geht zu den Ruinen von Boha'mu und berichtet mir, was Ihr dort findet.", sourceObjective = "Anachoret Ahuurn in Telredor möchte, dass Ihr die Ruinen von Boha'mu erforscht.", completion = "Die Verirrten des Wildfennstamms haben sich also in den Ruinen eingenistet? Das ist verblüffend. Sie müssen sich an Ihr Erbe erinnern und die Wichtigkeit dieses Ortes erkennen können. Wir müssen mehr darüber erfahren, {name}. Vielleicht ist in diesem Tempel der Schlüssel zur Erlösung der Verirrten und zur Wiedervereinigung der verschiedenen Arten der Draenei versteckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9787] = { id = 9787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen des Wildfennstamms", description = "Aus Eurem Bericht über die Ruinen von Boha'mu hörte ich heraus, dass dieser Stamm der Verirrten zur Verehrung von Tiergeistern zurückgekehrt ist. Bevor wir auf sie zugehen können, müssen wir mehr über ihren Glauben in Erfahrung bringen.\n\nKehrt zurück nach Wildfenn und sammelt heimlich ein paar ihrer Götzen, damit ich sie untersuchen kann. Versucht jedoch, sie nicht wütend zu machen, sonst haben wir vielleicht keine Chance mehr, Kontakt mit ihnen aufzunehmen.", sourceObjective = "Sammelt 6 Wildfenngötzen und kehrt dann zu Anachoret Ahuurn in Telredor zurück.", progress = "Habt Ihr die Götzen?", completion = "Diese sollten mehr als ausreichen, {name}. Sie scheinen auf Vögel fixiert zu sein, was merkwürdig ist, da es in den Zangarmarschen keine einheimischen Vogelarten gibt. Was könnte das wohl bedeuten?\n\nSind sie vielleicht auf die Arakkoa getroffen? Für ein schamanistisches Volk mögen sie vielleicht wie der Inbegriff eines mächtigen Vogelgeists wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[9788] = { id = 9788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuchter, düsterer Ort", description = "Bald nachdem ich dem Umbrafennstamm entkommen war, habe ich mich in einer Höhle südlich des Dorfs verkrochen. Ich hatte ja keine Ahnung, dass die Tiere der Marschen und die Sporenmänner sich um die Höhle stritten!\n\nIch musste sehr plötzlich von dort fliehen und eine Kiste mit meinem weltlichen Besitz zurücklassen.\n\nEs grenzte schon an Ironie, dass ich mit meinem ganzen Hab und Gut aus Umbrafenn entkommen konnte, nur um es so bald darauf wieder zu verlieren. Wenn Ihr mir meine Sachen wiederbringen könntet, würde ich Euch etwas aus meinem persönlichen Besitz schenken. Seid Ihr einverstanden, {name}?", sourceObjective = "Sucht nach Ikeyens Habseligkeiten in einer Höhle südlich von Umbrafenn. Bringt sie zurück zu Ikeyen in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr meine Habseligkeiten gefunden, {name}? Die Höhle ist nicht weit von Umbrafenn entfernt, nahe an der Grenze zu Nagrand.", completion = "Meine Sachen! Sie sind alle da!\n\nIch danke Euch, {name}. Wie versprochen dürft Ihr Euch etwas von den Dingen aussuchen. Ich habe nicht viel anzubieten, aber mein Volk hat schon immer das Wenige, was wir hatten, geteilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9789] = { id = 9789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Ihr möchtet Euch einen Platz in der Safari verdienen? Dann beweist Euch erst einmal.\n\nMir ist es völlig schnuppe, was Ihr schon alles für Kreaturen erlegt habt, bevor Ihr nicht jagt, was wir jagen, seid Ihr in meinen Augen <kein Jäger/keine Jägerin>. Die Grollhufe wären ein guter Anfang, sofern Ihr <Manns genug/mutig genug> seid.\n\nIch bin mir sicher, dass ich sie in der direkten Umgebung der Safari und in der Nähe im Süden gesehen habe.", sourceObjective = "Erlegt 12 Grollhufe und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück, um Euch zu beweisen.", completion = "Ein akzeptabler Start. Doch das war erst der Anfang.\n\nDie harmloseren Grollhufe beweisen noch gar nichts. Versuchen wir es doch mal mit einer größeren Herausforderung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9790] = { id = 9790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtdurchlässige Flügel", description = "An so einem abgeschiedenen Ort zu leben hat uns gelehrt, einen Nutzen aus allen verfügbaren Dingen zu ziehen. Dabei muss man natürlich lernen zu vergessen, woher einige der Materialien stammen.\n\nIch habe herausgefunden, dass die Flügel der Umbraglimmstecher, die hier in der Gegend leben, sehr gut als Regenschutz dienen. Sie sind stabil, dünn und biegsam.\n\n<Haalrun kichert.>\n\nIch sehe Euren Gesichtsausruck. Wie ich sagte, man muss sich erst an die Idee gewöhnen. Wenn Ihr in der Gegend herumstreicht, könnt Ihr mir dann vielleicht ein paar solcher Flügel mitbringen?", sourceObjective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Haalrun in Telredor.", progress = "Habt Ihr schon ein paar lichtdurchlässige Flügel sammeln können?", completion = "Habt Dank, {name}.\n\n\n\nZumindest müsst Ihr sie nicht säubern. Das ist der schlimmste Teil der Arbeit, aber wenn ich damit fertig bin, werdet Ihr niemals erkennen, dass sie mal zu einem riesigen Insekt gehört haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9791] = { id = 9791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Marschenfänge", description = "Während der Kriege der Orcs gegen mein Volk haben die Nahrungssammler Telredor aus Angst, angegriffen oder gefangen zu werden, kaum verlassen. Nun gehen sie häufiger hinaus, aber die Marschen sind nicht weniger gefährlich.\n\nEs scheint, als wären die Marschenfänge in letzter Zeit aggressiver geworden. Ich weiß nicht, ob das an der erhöhten Konkurrenz für ihre gewöhnliche Nahrung liegt, aber sie greifen regelmäßig unsere Nahrungssucher an. Vielleicht würden sie uns in Ruhe lassen, wenn wir ihren Bestand um Telredor herum etwas dezimieren könnten.", sourceObjective = "Tötet 10 Marschenfangreißer und kehrt dann zu Noraani in Telredor zurück.", completion = "Danke für Eure Hilfe bei der Auslöschung einiger Marschenfangreißer, {name}. Wenn sie über Intelligenz verfügen würden, würden sie vielleicht erkennen, dass es am Besten ist, zu leben und leben zu lassen.\n\n\n\nGroße, überwucherte Käfer mit Intelligenz. Ich frage mich, wie das wohl wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[9792] = { id = 9792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft für Telaar", description = "Ihr habt Euch in unseren Geschäften als vertrauenswürdig erwiesen, {name}, und das in Zeiten, in denen das Vertrauen meines Volkes nur schwer zu gewinnen ist.\n\nEine große Gruppe meiner Brüder und Schwestern hat sich in der alten Draeneistadt Telaar in Nagrand im Süden niedergelassen. Um nach Telaar zu gelangen, müsst Ihr der Straße Richtung Süden nach Nagrand folgen und dann nach Südosten gehen, bis Ihr an die Klippen östlich des Oshu'guns gelangt.\n\nJeder, der uns so sehr geholfen hat wie Ihr, ist dort willkommen.\n\nSucht Aufseher Moi'bff Jill und sagt ihm, dass Ihr mein Vertrauen erlangt habt.", sourceObjective = "Sprecht mit Aufseher Moi'bff in Telaar in Nagrand.", completion = "Ikuti ist wie ein Bruder für mich. Seine Freunde sind auch meine Freunde. Ihr seid hier willkommen, {name}, und Ihr habt unseren Dank für die Hilfe, die Ihr meinem Volk geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9793] = { id = 9793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Tuurem", description = "Prophet Velens Suche nach Verbündeten hat die Draenei in der Scherbenwelt ermutigt, selbst eine Suche zu beginnen. Der Krieg meines Volks mit der Legion hat uns vielleicht aus unseren Städten und Tempeln vertrieben, aber er konnte nicht alle Spuren unserer Zivilisation verwischen.\n\nTuurem, mein früheres Zuhause in den Wäldern von Terokkar, war eine der Städte, die von den Orcs überrannt wurden. Ich habe schon viel zu lange nichts mehr von dort gehört. Bringt diesen Brief zu Andarl in Allerias Feste in Terokkar und schaut, was Ihr herausfinden könnt.", sourceObjective = "Bringt Verteidiger Idaars Brief zu Andarl in Allerias Feste in den Wäldern von Terokkar.", progress = "Wie kann ich Euch helfen?", completion = "Hmm... Ich kann mich erinnern, dass unsere Späher von den Ruinen einer Draeneisiedlung in den nördlichen Ausläufern des Waldes berichtet haben. Ich weiß jedoch selbst nicht viel über die Ruinen, aber Ihr könnt gerne mit unseren Spähern sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9794] = { id = 9794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Neugier", description = "{name}, ich muss Euch um einen Gefallen bitten. Normalerweise würde ich das ja nicht tun, aber ich habe beide Hände bereits mehr als voll.\n\nIch habe einen Verbündeten namens Kialon in Sylvanaar im Schergrat im Norden. Er erwartet, dass ich mich in naher Zukunft bei ihm melde, obwohl ich fürchte, dass ihm nicht gefallen wird, was ich zu sagen habe.\n\nWenn Ihr ihm meine Antwort bringen könntet, wäre ich Euch sehr dankbar. Ich muss jedoch darauf bestehen, und das ist sehr wichtig, dass Ihr den Brief nicht lest. Er ist nur für Kialons Augen bestimmt.", sourceObjective = "Bringt Timothys Brief zu Kialon in Sylvanaar im Schergrat.", progress = "<Kialon schaut Euch misstrauisch an.>\n\nIch kenne Euch nicht, {race}. Was wollt Ihr von mir?", completion = "Ihr bringt mir also Timothys Antwort?\n\n<Kialon hält einen Moment inne, um den Brief zu lesen, und fängt an zu lachen.>\n\nEr hat alles unter Kontrolle, sagt er, braucht keine Hilfe. Ich hätte es wissen müssen!\n\nManche Leute ändern sich nie. Schaut, er hat sich sogar die Zeit genommen, meine Rechtschreibfehler zu korrigieren.\n\n<Kialon seufzt halbherzig.>\n\nIch hätte ihm den Brief nicht schicken sollen. Ich habe es vergessen. Der Spezialist hat die Situation immer unter Kontrolle. Immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9795] = { id = 9795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ogerbedrohung", description = "Als ob die Naga und ihre Verbündeten nicht schon genug wären, scheinen nun auch die Oger sich weiter in den Marschen auszubreiten. Sie haben schon weite Teile des Nordwestens erobert, und der Puffer zwischen uns und ihnen wird immer kleiner.\n\nFür jeden, den wir umbringen, sind gleich mehrere neue zur Stelle. Ich weiß nicht, wie lange wir Zabra'jin halten können, wenn sie sich entschließen uns anzugreifen. Geht nach Norden in die Berge zum orcischen Stützpunkt in der Donnerfeste und berichtet Nekthar von unserer Bedrängnis. Jede Hilfe, die er uns zur Verfügung stellen kann, ist äußerst willkommen.", sourceObjective = "Reist zur Donnerfeste im Schergrat und sprecht mit Nekthar.", completion = "Denjai braucht Hilfe? Ich würde ihm gerne ein paar Leute schicken, aber wir sind hier selbst nur sehr dünn besiedelt. Wir haben hier oben unsere eigenen Probleme mit den Ogern.\n\nSobald ich kann werde ich ihm alle Informationen, die wir über diesen Ogerstamm und ihre Taktiken haben, zukommen lassen. Wenn er lang genug durchhält können wir die Grobiane vielleicht von zwei Seiten aus angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9796] = { id = 9796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus den Zangarmarschen", description = "Schattenjäger Denjai ist nicht der einzige, der auf einen Bericht von mir wartet. Mokasa in der Steinbrecherfeste in Terokkar brennt darauf, von unseren Fortschritten zu hören, besonders seit die meisten ihrer Boten hier auf ihren Reisen vorbeikommen.\n\nSie hat mich gebeten, ihr Bescheid zu geben, sobald der Sumpfrattenposten fertig ist. Wenn Ihr nichts dagegen habt, wäre ich Euch sehr dankbar, wenn Ihr ihr die Nachricht überbringen könntet. Wir haben zwar soweit schon alles aufgebaut, aber es gibt noch viel zu tun.\n\nUm zur Steinbrecherfeste zu gelangen, müsst Ihr der Straße nach Süden in Richtung Zangarmarschen folgen und Euch durch die Wälder von Terokkar an Tuurem vorbei begeben.", sourceObjective = "Sprecht mit Mokasa in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Es wurde auch langsam Zeit, dass der Außenposten fertig wird. Wir haben schon viel zu viele Boten an die Vorhut der Allianz verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9797] = { id = 9797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Garadar", description = "<Immer noch nach Atem ringend bedeutet der Bote Euch, Euch hinzusetzen.>\n\nSie werden vielleicht nicht überleben, {race}! Geht so schnell Euch Eure Beine tragen können nach Garadar.\n\n<Als Reaktion auf Euren fragenden Gesichtsausdruck führt der Bote näher aus.>\n\nDas Zuhause der Mag'har liegt im Süden, in Nagrand. Wir haben ein paar Leute dort, aber es sind nur wenige, und unsere Verbündeten der Mag'har werden von allen Seiten von Feinden angegriffen. Sucht dort unseren Kommandanten, Hauptmann Kroghan, und helft ihm, wo Ihr nur könnt! Garadar darf nicht fallen!", sourceObjective = "Sprecht mit Hauptmann Kroghan in Garadar in Nagrand.", completion = "<Auch wenn er sich Mühe gibt, es zu verheimlichen, macht sich Erleichterung auf Kroghans Gesicht breit.>\n\nEs wurde auch langsam Zeit, dass Ihr kommt! Sicher, Ihr seid keine Armee, {race}, aber hier ist ein jeder willkommen, der Kraft genug besitzt, eine Waffe zu führen oder einen Zauber zu wirken. Die Bevölkerung Garadars ist ein Teil der Horde und stolz, sein Blut für ihre Verteidigung vergießen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9798] = { id = 9798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelfenpläne", description = "Diese Pläne sehen wichtig aus. Ihr solltet sie Verteidiger Aldar bei der Absturzstelle zeigen.", sourceObjective = "Bringt die Blutelfenpläne zu Verteidiger Aldar bei der Absturzstelle im Am'mental.", progress = "Was habt Ihr denn da?", completion = "Hier, lasst mich einen Blick auf diese Pläne werfen.\n\nDie Blutelfen sind uns hierher gefolgt? Sie sind durch und durch bösartig und sollten ganz und gar ausgelöscht werden!\n\n<Der Verteidiger braucht einen Moment, um sich wieder zu fassen.>\n\nEntschuldigung, ich hätte mich beherrschen sollen. Wir stehen für die Entdeckung dieser Informationen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9799] = { id = 9799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanische Hilfsarbeit", description = "Die Am'menfelder im Westen sind das wichtigste Vermehrungsgebiet der einheimischen Peitscherpopulation. Botanikerin Taerix befürchtet, dass sich die Peitscher auf Grund des verseuchten Grundwasserspiegels nicht mehr fortpflanzen können, nachdem wir den See gereinigt haben.\n\nGeht zu den Am'menfeldern und pflückt dort ein paar der verderbten Blumen für mich, damit ich sie untersuchen und sehen kann, was es zu tun gilt. Ihr solltet sie an ihren ungewöhnlichen roten Blüten erkennen.", sourceObjective = "Sammelt 3 verderbte Blumen und kehrt zu Lehrling Vishael bei der Absturzstelle im Am'mental zurück.", progress = "Hallo, {class}. Habt Ihr die Blumen?", completion = "Das sieht mir nach ein paar guten Exemplaren aus. Danke für Eure kleine Hilfsarbeit. Sobald ich Zeit zum Untersuchen der Blumen habe, sollte ich bestimmen können, was es zur Wiederherstellung der Felder bedarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9800] = { id = 9800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltene Bohne", description = "Ihr seid zu schlecht ausgerüstet um den rastlosen Elementaren Nagrands gegenüber zu treten. Bevor Ihr dem Irdenen Ring helfen könnt, müsst Ihr erst Euch selbst helfen.\n\nIm Westen findet Ihr Kothaufen von den Wildtieren Nagrands. Ihr müsst den Dung nach den verdauten Überresten der Caracolibohne durchsuchen. Aus dieser Bohne kann ich eine Tablette herstellen, die Euch im Kampf gegen die ruhelosen Naturgewalten helfen wird.\n\nKehrt zu mir zurück, wenn Ihr mindestens zwei Fäuste voller Caracolibohnen gesammelt habt... Ogerfäuste!", sourceObjective = "Bringt 8 verdaute Caracolibohnen zu Elementarist Lo'ap am Thron der Elemente.", progress = "<Elementarist Lo'ap ballt seine Hände zu Fäusten und schüttelt den Kopf.>\n\nOgerfäuste...", completion = "Bitte wascht Euch nicht in den heiligen Wassern des Throns.\n\n<Elementarist Lo'ap reicht Euch eine fertige Caracolitablette.>\n\nLegt sie unter Eure Zunge und lasst sie sich auflösen. Einmal aufgelöst werdet Ihr Wasser wie Luft atmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9801] = { id = 9801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reagenzien sammeln", description = "Ich habe das Gefühl, dass diese Verirrten nicht so gut auf einen Draenei zu sprechen sein werden, aber vielleicht auf einen Arakkoa. Ich kann einen Zaubertrank herstellen, der Euch für kurze Zeit in einen Arakkoa verwandeln kann. Dazu benötige ich ein paar Reagenzien, die man nur sehr schlecht lagern kann, da man sie sofort nach dem Sammeln weiterverarbeiten muss.\n\nIhr werdet mir ein paar Sporensegleraugen und einige Fennschreitertentakel bringen müssen. Beide Arten leben in der Wildnis um Telredor herum.", sourceObjective = "Anachoret Ahuurn in Telredor möchte, dass Ihr ihm 4 Sporensegleraugen und 4 Fennschreitertentakel bringt.", progress = "Habt Ihr die Reagenzien schon?", completion = "Diese Reagenzien eignen sich sehr gut. Bitte gebt mir einen Moment Zeit, um den Trank zu mischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9802] = { id = 9802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzen der Zangarmarschen", description = "Die Seen der Zangarmarschen werden langsam entwässert. Wir wissen nicht warum, aber viele Pflanzenarten drohen auszusterben.\n\nAls Katalogisiererin der Expedition ist es meine Aufgabe, diese Pflanzen zu identifizieren und zu verstehen, was mit ihnen geschieht.\n\nWenn Ihr helfen wollt, bringt mir unbekannte Pflanzenteile. Wenn Ihr kräuterkundig seid, könnt Ihr sie direkt vom Boden pflücken, aber auch die einheimischen Wesen des Sumpfs tragen Pflanzenteile bei sich.", sourceObjective = "Bringt 10 unbekannte Pflanzenteile zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr ein paar Pflanzenteile gefunden, {name}?", completion = "Das Abnehmen der natürlichen Arten ist ein Grund zur Sorge. Die Zunahme der eingewanderten Arten könnte mit der neuerlichen Störung des Ökosystems zusammenhängen. Ich habe jedoch noch zu wenig Anhaltspunkte, um Genaueres zu sagen.\n\n<Lauranna macht ein paar Notizen in ein Buch, als sie die Pflanzenteile untersucht.>\n\nNehmt ein paar davon, {name}. Sie könnten vielleicht nützlich für Euch sein.\n\nBringt mir alle weiteren Pflanzenteile, die Ihr finden könnt. Ich werde sie in meiner Statistik auflisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9803] = { id = 9803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft für den Wildfennstamm", description = "Es ist an der Zeit, dem Wildfennstamm die Hand zu reichen und sie zu lehren, dass das Licht sie nicht aufgegeben hat. Nehmt den Trank, den ich vorbereitet habe, und tragt ihn zu den Ruinen von Boha'mu.\n\nSobald Ihr bei den Ruinen angekommen seid, trinkt den Trank um Euch in einen der Vogelgeister zu verwandeln. Sprecht mit dem Ältesten Kuruti und lasst ihn wissen, dass die Draenei bereit sind, sein Volk als verloren geglaubte Brüder und Schwestern zu empfangen.", sourceObjective = "Trinkt Ahuurns Elixier in den Ruinen von Boha'mu. Sprecht mit dem Ältesten Kuruti in der Form eines Arakkoas.", progress = "Habt Ihr schon mit dem Ältesten von Wildfenn gesprochen?", completion = "Sie haben abgelehnt? Natürlich steht es ihnen frei, selbst zu wählen, aber ihre Entscheidung überrascht mich. Ich habe gedacht, dass alle Draenei, also auch die Zerschlagenen und Verirrten, sich daran erinnern würden, dass wir alle ein Volk sind.\n\nIch schätze er hat recht damit, dass es töricht war zu versuchen, sie hereinzulegen, aber trotzdem, konnte er denn nicht sehen, dass wir in freundlicher Absicht gehandelt haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9804] = { id = 9804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgebrachte Geister des Himmelsweisensees", description = "Die Unruhen in den Gezeiten der Gewässer von Nagrand hat die Wassergeister des Himmelsweisensees sehr aufgebracht. Sie haben im Gegenzug damit begonnen, Verwüstungen entlang der Wasserwege anzurichten.\n\nWatoosun des Wassers ist uns in einer Vision erschienen und hat uns erlaubt, das Problem zu lösen, solange wir auch die Ursache dafür beheben...\n\nWir werden uns um die Ursache kümmern, doch zuerst müssen wir die direkten Bedrohungen für den Thron beseitigen. Zerstört die aufgebrachten Seegeister und kehrt dann zu mir zurück.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 8 Seegeister tötet.", completion = "<Elementarist Lo'ap kniet im Wasser und betet.>\n\nDer Irdene Ring ist nicht stolz auf das, was geschehen ist. Wir tun das, was wir müssen, um das Land zu heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9805] = { id = 9805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Incineratus", description = "Die erbärmlichen Verirrten, einst verbannt in die Sümpfe der Zangarmarschen, versuchen nun, ihren Dreck auch in andere Teile der Welt zu tragen.\n\nIch habe mich an die weisen Furien gewandt und ihren Segen erhalten. Um die Ursache zu beseitigen, müssen wir die Elemente auf sie hetzen!\n\nIch gebe Euch beseeltes Feuer, entzündet an der feurigen Essenz von Incineratus selbst. Reist nach Schilftanz, südöstlich von hier, und entzündet die Hütten mit dem Feuer! Lasst sie die Wut der Elemente spüren!", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr die große Hütte, die westliche Hütte, die südliche Hütte und die östliche Hütte in Schilftanz zerstört.\n\nBringt das beseelte Feuer zurück zu Elementarist Lo'ap, wenn Ihr fertig seid.", progress = "Es beschämt mich, dass mein eigenes Volk die Gewässer in Nagrand beeinflussen möchte, um ein Marschland zu erschaffen.", completion = "Eure Bemühungen haben die Ausbreitung der Verschmutzung eingedämmt, aber nun sind neue Probleme aufgetaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9806] = { id = 9806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruchtbare Sporen", description = "Wenn sie zwischen den Langstielpilzen hindurchwandern, sammeln sich allerlei fruchtbare Sporen an den Gliedmaßen der Sporensegler und Marschenläufer.\n\nWie Ihr sehen könnt, ist unser Volk sehr klein, also haben wir nur wenige Möglichkeiten, diese Sporen zu sammeln. Haltet nach Sporenseglern und Marschenläufern Ausschau und sammelt die fruchtbaren Sporen. Ganz Sporeggar stünde tief in Eurer Schuld.", sourceObjective = "Sammelt 6 fruchtbare Sporen von den Sporenseglern und den Marschenläufern der Zangarmarschen und kehrt danach zu Gshaff in Sporeggar zurück.", progress = "Ihr seid zurück, {name}. Habt Ihr die fruchtbaren Sporen bekommen?", completion = "Diese Sporen sind perfekt, {name}! Die Langstielpilze sind für den Wiederaufbau unseres Dorfs unerlässlich. Und seit den Angriffen der Sumpflords, die wir erdulden mussten, sind unsere Vorräte knapp!", sourceObjectiveStatus = "unverified-source-field" }
quests[9807] = { id = 9807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr fruchtbare Sporen", progress = "Wir können immer noch mehr fruchtbare Sporen gebrauchen, {race}. Langstielpilze sind unglaublich nützlich. Wir können sehr viel mit ihnen anstellen, wenn wir sie anbauen.", completion = "Eure Hilfe wird sehr geschätzt, {name}. Ihr werdet uns doch weiterhin helfen, oder?" }
quests[9808] = { id = 9808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühkappenpilze", description = "Ich habe gesehen, dass Ihr glänzende runde Metallstücke benutzt, um sie gegen Dinge einzutauschen, die Ihr haben möchtet. Wir benutzen glänzende runde Pilze als Zahlungsmittel.\n\nDie Glühkappenpilze wachsen überall in den Marschen, man muss nur wissen, wie man sie richtig sammelt ohne sie zu zerstören. Ich werde Euch beibringen, wie man das tut, wenn Ihr mir versprecht, ein paar für unsere Vorräte zu sammeln. Einverstanden, {name}?", sourceObjective = "Bringt 10 Glühkappen zu Msshi'fn in Sporeggar in den Zangarmarschen.", progress = "Habt Ihr ein paar Glühkappen gefunden, {name}? Sie wachsen fast überall in den Marschen.\n\nIhr könnt sie schon von weitem leuchten sehen, wenn Ihr genau hinschaut.", completion = "Die können wir prima bei den anderen Sporlingen gegen Essen und Vorräte eintauschen. Sporeggar dankt Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9809] = { id = 9809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Glühkappen", progress = "Wenn Ihr noch mehr Glühkappen habt, nehme ich sie Euch gerne ab. Unser Dorf kann sie immer gut gebrauchen.", completion = "Habt Dank, {name}. Als Ältester von Sporeggar ist es meine Aufgabe dafür zu sorgen, dass mein Volk genügend Vorräte hat. Ihr erleichtert mir diese Aufgabe ungemein." }
quests[9810] = { id = 9810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschmutzte Geist", description = "Watoosun konnte zwar den Seuchengestank loswerden, aber gleichzeitig erschuf er eine irrsinnige Geisteressenz. Eine Geisteressenz, die aus der übelsten Verderbnis entstanden ist, die es je unter Elementaren gegeben hat!\n\nIhr könnt diesen verschmutzten Sumpfgeist südwestlich von hier, tief im Sonnenwindsee, finden.\n\nSucht und vernichtet Watoosuns verschmutzte Essenz sowie jeglichen verseuchten Nachfahren, den sie erschaffen haben möge.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr Watoosuns verschmutzte Essenz und 8 Seewoger tötet.", completion = "Die Elemente haben Euren Sieg besungen, als Ihr die verschmutzte Essens getötet habt. Der Irdene Ring dankt Euch und möchte, dass Ihr Euch eine Belohnung aussucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9811] = { id = 9811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund der Sin'dorei", description = "Dies ist der Beginn eines neuen Zeitalters in der Geschichte der Blutelfen {name}. Ihr habt geholfen, den Bund zwischen unserem und Eurem Volk zu festigen, {race}.\n\nBringt den Kopf des Verräters nach Silbermond zum Lordregenten Lor'themar Theron. Er wird begierig sein, die Neuigkeit zu erfahren.", sourceObjective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", progress = "Ihr wünscht eine Audienz bei mir, {class}? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Ihr habt Dar'Khan also getötet, {race}? Beeindruckend. Ich habe das Gefühl, dass unsere und Eure Leute bald gute Freunde sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9812] = { id = 9812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter zur Horde", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, {name}. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", sourceObjective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", progress = "Mir wurde gesagt, dass ich einen Besucher aus Quel'Thalas erwarten soll. Ehrlich gesagt hatte ich einen Blutelfen erwartet.\n\nWelche Neuigkeiten bringt Ihr?", completion = "Dann ist es also geschehen. Der gemeine Verräter hat bekommen, was er verdient hat.\n\nIhr habt den Blutelfen und der Horde einen großen Dienst erwiesen. Dar'Khan war Thralls Entschuldigung, um den Blutelfen den Eintritt in unser Bündnis zu verweigern. Jetzt habt Ihr den Weg für eine neue Horde bereitet, {name}.\n\nWie ich sehe hat Lor'themar weitere Nachrichten, die seine Beziehungen zu Thrall deutlich verbessern werden. Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[9813] = { id = 9813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Kriegshäuptling", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zum Kriegshäuptling in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte der Sin'dorei.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", sourceObjective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zum Kriegshäuptling nach Orgrimmar, Hauptstadt von Durotar, bringt.", progress = "Ja, {class}?", completion = "<Thrall beginnt, den Brief zu lesen.>\n\nDie Blutelfen haben sich also endlich ihres kleinen Problems entledigt. Dass Eure Hilfe und ein gesamtes Regiment der Verlassenen dafür nötig war, spielt ja keine Rolle.\n\n<Thrall bricht in Gelächter aus.>\n\nIch nehme an, dass wir das hier nicht aufhalten können. Schließlich brauchen wir sie genauso sehr, wie sie uns brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9814] = { id = 9814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berstkappenpilze, Mann!", description = "Mögt Ihr Pilze, Mann? Es gibt einen ganz mächtigen hier in den Zangarmarschen, wächst gleich in der Nähe von Zabra'jin.\n\nIhr müsst aber vorsichtig sein, Mann. Man nennt sie aus gutem Grund Berstkappenpilze. Wenn man ohne entsprechende Vorsichtsmaßnahmen zu nahe an sie herangeht, geht ihnen der Hut hoch! Puff! Und dann steht man in einer Wolke von giftigen Sporen.\n\nIch habe sie benutzt, um die Zukunft vorauszusagen, aber jetzt sind sie fast alle.", sourceObjective = "Bringt Hexendoktor Tor'gash 6 Berstkappen.", progress = "Habt Ihr die Pilze, Mann?", completion = "Die sind klasse, Mann!\n\nIch sag' Euch was. Weil Ihr so nett wart und mir mit den Pilzen geholfen habt, dürft Ihr beim Spaß dabeisein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9815] = { id = 9815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammtauchen", description = "Die am schwersten betroffenen Wasserelementare befinden sich im Halaanibecken, südwestlich von hier unterhalb der verlassenen Stadt Halaa. Während einige der verzweifelten Elementare ohne Folgen für die Umwelt zerstört werden können, müssen die Überreste der Schlammkreaturen nach ihrer Zerstörung entfernt werden.\n\nDie Schlammkreaturen hinterlassen nämlich verseuchte Leichenteile, die der Umwelt schaden können, wenn man sie liegen lässt.\n\nVernichtet diese Schlammkreaturen und bringt mir ihre schlammbesudelten Kerne.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 5 schlammbesudelte Kerne besorgt.", progress = "Lasst keinen verseuchten Schlamm zurück!", completion = "Der Irdene Ring dankt Euch, {name}. Auch die Elemente sind Euch dankbar. Eure wiederholten Bemühungen, unsere Welt zu reinigen, werden sehr geschätzt und sicher nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9816] = { id = 9816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr so was schon mal gesehen?", description = "In diesen Marschen fehlt was, Mann! Keine Murlocs hier.\n\nKeine Sorge, Mann, ich habe eine Lösung für dieses Problem. Seht Ihr Gargel und Gurgel da drüben? Ich habe vor, den Verirrten ein paar Murlocs zu schenken!\n\nBringt diesen Käfig nach Dolchfenn und lasst sie bei der Ansammlung von Hütten im Nordosten frei. Nun gut, ich möchte Euch nicht Gargel und Gurgel auf den Hals jagen, aber ich gebe Euch einen Käfig mit jungen bunten Murlocs. Setzt den Käfig einfach auf den flachen Stein, den Ihr dort finden werdet, und öffnet die Tür!", sourceObjective = "Bringt den Murlockäfig nach Dolchfenn und stellt ihn auf den flachen Stein in der Nähe des Dorfs.", completion = "Ausgezeichnete Arbeit, Mann! Ich hoffe, sie hatten Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9817] = { id = 9817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführerin der Blutschuppen", description = "Hiermit setzt die Expedition des Cenarius ein Kopfgeld auf Rajis Fyashe, Anführerin der Blutschuppennagas, aus. Die Nagazauberin wurde zuletzt am Schlangensee gesehen, im Nordwesten der Zangarmarschen.\n\nDie Blutschuppen sind als extrem gefährlich einzustufen, und ihre Anführerin sollte mit äußerster Vorsicht behandelt werden.\n\nDas Kopfgeld kann bei Aufseher Hamuht in der Zuflucht des Cenarius eingefordert werden.", sourceObjective = "Tötet Rajis Fyashe am Schlangensee und kehrt dann zu Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.", completion = "Ich wette, die Blutschuppen überlegen es sich nun zweimal, bevor sie unsere Späher nochmals angreifen. Nehmt dies als Belohnung, {name}. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9818] = { id = 9818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Untergrund", description = "Etwas schändet den Untergrund. Es schlägt den Boden, als wollte es ihn bestrafen.\n\n*Rums*\n\n<Untrag schlägt sich mit der Faust auf die Brust.>\n\nSo klingt das hunderttausendmal. Endlos. Die Erde taumelt. Sie ruft nach uns.\n\nGordawg spricht mit mir. Gordawg weiß, dass etwas die Elementare hervortreibt. Etwas unter der Erde.\n\nGeht jetzt und sprecht mit Gordawg. Nein, hört ihm zu, sprecht nicht. Hört Gordawg an...", sourceObjective = "Kommuniziert mit Gordawg.", completion = "<Gordawg scheint Euch zuzunicken.>\n\nSetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9819] = { id = 9819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gequälte Erde", description = "Bestraft den Thronräuber. Ihr werdet ihn finden. Folgt Pfad aus Erde. Zuerst bringt gequälte Erdgeister zur Ruhe. Müssen wieder schlafen.\n\n<Gordawg schlägt mit seiner Faust auf den Boden und schleudert faulig riechende Erde nach oben.>\n\nMüssen schlafen!\n\n<Gordawg zeigt nach Südosten.>\n\nSucht Geister in Nähe von Bergen. Nähe von Hügeln. Nähe von Erde.\n\nBringt zur Ruhe.\n\nTelaaribecken... Südosten.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 10 gequälte Erdgeister tötet.", progress = "Schlafen sie?", completion = "<Gordawg nickt zufrieden.>\n\nGut. Geister schlafen jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9820] = { id = 9820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Boss Grog'ak", description = "Gesucht - Tot oder lebendig: Boss Grog'ak, Vorarbeiter der Ango'rosh Pilzsammeloperation.\n\nDiese grobschlächtigen, axtschwingenden Dummköpfe sind für das Fällen von Pilzen nördlich des Dorfs verantwortlich. Wenn er nicht aufgehalten wird, werden er und seine Leute einen Pfad bis zu den Mauern von Zabra'jin schlagen!\n\nWer Boss Grog'aks Kopf zu Schattenjäger Denjai bringt, soll reich belohnt werden.", sourceObjective = "Bringt Boss Grog'aks Kopf zu Schattenjäger Denjai in Zabra'jin.", progress = "Was habt Ihr da, {name}?", completion = "Gut gemacht, {name}. Die Anwesenheit dieser Oger so nah an unserem Außenposten hat mich ein wenig beunruhigt. Es scheint, als kämen sie seit einiger Zeit die Berge im Norden herunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9821] = { id = 9821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnis schmecken", description = "<Gordawg nimmt einen Stein und fängt an darauf herumzukauen.>\n\nGordawg schmeckt. Gordawg weiß wo diese Erde war.\n\n<Gordawg hebt eines seiner massiven Beine und stampft auf den Boden.>\n\nSchaut. Schaut Nagrand an.\n\n<Gordawg zeigt auf seinen Fußabdruck. Im Abdruck seht Ihr eine perfekte geologische Karte von Nagrand, auf der alle Stellen markiert sind, an denen die Elementare, die Ihr für Gordawg zerstören sollt, sich aufhalten.>\n\nZERSTÖRT SIE! Bringt Gordawg die Stücke zum Essen.\n\nNehmt die Karte.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr ihm 10 Kerne eines wütenden Zermalmers bringt.", progress = "Gordawg isst den Stein. Gordawg findet den Thronräuber. Bringt Stein!", completion = "<Gordawg spuckt den gekauten Stein aus, woraufhin ein Steinschauer auf Euch herabrieselt.>\n\nGift. Diese Felsen sind nicht Nagrand. Diese Felsen sind vergiftet. Ihr zerstört Giftfels. Ihr findet Thronräuber.", sourceObjectiveStatus = "unverified-source-field" }
quests[9822] = { id = 9822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohender Angriff", description = "Die Position der Pilzsammeloperation der Oger kann kein Zufall sein. Ich werde den Verdacht einfach nicht los, dass sie einen Angriff auf Zabra'jin planen.\n\nIch muss das genau wissen, {name}. Die Oger haben einen weiteren Außenposten im Nordwesten beim Grund der Ango'rosh. Wenn sie tatsächlich vorhaben uns anzugreifen, dann werden wir dort sicher Beweise für ihre Pläne finden. Geht dorthin, {name}, und durchsucht das Lager. Bringt mir alles, was auch nur im Geringsten verdächtig sein könnte!", sourceObjective = "Bringt die Angriffspläne der Ango'rosh zu Schattenjäger Denjai in Zabra'jin.", progress = "Habt Ihr einen Beweis für die Pläne der Oger gefunden?", completion = "<Schattenjäger Denjai untersucht die Pläne.>\n\nIch wusste es! Der Gestank eines Ogers hat immer etwas Bedrohliches an sich. Jetzt, da wir einen Beweis für ihren Plan haben, müssen wir ihnen zuvorkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9823] = { id = 9823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie oder wir", description = "Um die Bedrohung, die von den Ango'rosh ausgeht, zu beenden, müssen wir ihren Oberanführer Schmetterfaust töten. Aber wir werden sogar noch viel mehr tun. Wir werden mit dem Oberanführer und seinem Gefolge ein Zeichen setzen.\n\nGeht zur Festung der Ango'rosh und kümmert Euch um unsere Feinde. Die Feste befindet sich in einer Höhle auf einer kleinen Insel nordwestlich von Zabra'jin. Dort werdet Ihr eine Brücke, die aus einem umgefallenen Pilz besteht, finden.\n\nZeigt kein Erbarmen, {name}. Sie würden sicher keinen von uns verschonen.", sourceObjective = "Tötet Oberanführer Schmetterfaust, 10 Raufer der Ango'rosh, 10 Seelenfresser der Ango'rosh und meldet Euch dann bei Schattenjäger Denjai in Zabra'jin zurück.", completion = "Unser Sieg über die Ango'rosh muss gefeiert werden, {name}. Ich frage mich, wie lange es wohl dauert, bis diese Grobiane einen neuen, blutrünstigen Anführer gefunden haben.\n\nGanz gleich, wir werden auf sie vorbereitet sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9824] = { id = 9824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Störungen", description = "Ich versuche, eine Aufzeichnung von Karazhans Energie zu erstellen... für ein privates Projekt natürlich. Unglücklicherweise empfange ich hier oben einfach nichts. Wenn ich in die Nähe einer unterirdischen Wasserquelle gelangen könnte, könnten meine Kristalle die Signale viel leichter empfangen.\n\nIch habe sowohl von einem unterirdischen Teich als auch von einem Brunnen in einem Keller unter uns gehört. Dieser ganze Ort ist jedoch voll von Geistern, und sich dort hinzuwagen wäre für jemanden in meinem Alter viel zu gefährlich. Was sagt Ihr? Werdet Ihr einem alten Mann helfen und das Aufzeichnen für mich übernehmen?", sourceObjective = "Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück.", progress = "Die Aufzeichnungen, {name}. Habt Ihr sie beendet?", completion = "Diese Aufzeichnungen verheißen nichts Gutes, {name}. Karazhan sollte alle möglichen arkane Ströme ausstrahlen... stattdessen herrscht dort nun ein riesiges Energievakuum. Keine Signale. Nichts. Außer einem sehr schwachen dämonischen Echo.\n\nDas sind schlechte Nachrichten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9825] = { id = 9825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastlose Aktivität", description = "Wie Ihr sicher bemerkt habt, wimmelt es außerhalb von Karazhan nur so von Geistwesen. Der Grund ihrer Existenz ist unbekannt, und Unbekanntes mag ich gar nicht leiden!\n\nBringt mir ihre geisterhafte Essenz, damit ich ihre Beschaffenheit untersuchen kann. Karazhan hat viele Geheimnisse, {name}. Und ich werde sie alle lüften.", sourceObjective = "Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan.", progress = "Habt Ihr die Essenzen, die ich benötige, besorgt, {class}?", completion = "Faszinierend. Ich werde die Essenzen untersuchen, {name}. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9826] = { id = 9826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalarankontaktpersonen", description = "Diese Zeichen bedeuten nichts Gutes für uns, {name}. Ich hatte es noch nie so mit Geheimhaltung, deshalb erzähle ich Euch ein wenig über meine Organisation, das Violette Auge.\n\nWir sind Agenten der Kirin Tor, dem Magierrat von Dalaran. Wir wurden beauftragt, Karazhan und Medivh im Auge zu behalten, für den Fall, dass die Dinge aus dem Ruder laufen.\n\nWas sie auch taten... sehr bald nachdem Medivh verschwunden war.\n\nIn diesem Bericht stehen meine genauen Ergebnisse. Bringt ihn zu Erzmagier Cedric, er ist auch vom Violetten Auge. Ihr findet ihn am Rande des Dalarankraters.", sourceObjective = "Bringt Alturus' Bericht zu Erzmagier Cedric am Rande des Dalarankraters.", progress = "Ihr wisst vom Violetten Auge? Ihr kommt mir nicht bekannt vor.", completion = "Alturus hat Euch diese Information anvertraut? Der alte Narr.\n\nIch schätze, der Schaden ist schon angerichtet, dann können wir Euch genauso gut für uns nutzen. Ich nehme an, Ihr werdet kooperieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[9827] = { id = 9827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siechendes Basidium", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt, etwas mehr darüber erzählen.", sourceObjective = "Bringt das siechende Basidium zu Ruam in Telredor in den Zangarmarschen.", progress = "Was habt Ihr da, {name}?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie die anderen in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9828] = { id = 9828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siechendes Basidium", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt etwas mehr darüber erzählen.", sourceObjective = "Bringt das siechende Basidium zu Reavij im Sumpfrattenposten in den Zangarmarschen.", progress = "Was habt Ihr da, {name}?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie kein anderer in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9829] = { id = 9829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar", description = "Alturus' Bericht ist beunruhigend. Wir dachten, es sei ein schlechtes Zeichen, als Karazhan sich von der Umwelt abgeschottet hat. Wir hatten dort Agenten, von denen wir nie wieder gehört haben. Und nun diese... dämonische Strömung. Wir müssen das untersuchen.\n\nDie Einzigen, die Karazhan wieder öffnen könnten, hielt man für tot: Khadgar und Medivh.\n\nWährend wir hoffen, das Letzterer tatsächlich tot ist, haben wir kürzlich in Erfahrung gebracht, dass sein Lehrling, Khadgar, gesund und munter an einem Ort namens Shattrath lebt. Findet ihn und gebt ihm Alturus' Bericht.", sourceObjective = "Bringt Alturus' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar.", completion = "Das Violette Auge? Was Ihr nicht sagt.\n\nZeigt mir den Bericht, von dem Ihr sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9830] = { id = 9830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutergift", description = "Wenn ich mich mit den Draenei unterhalte, habe ich immer den Eindruck, dass sie das Gefühl haben, aus ihrer natürlichen Umgebung herausgerissen zu sein. Viele scheinen meine Brüder und Schwestern, die Zerschlagenen, zu bedauern, weil sie glauben, dass wir etwas verloren haben.\n\nWir Zerschlagenen haben vielleicht unsere Verbindung zum Licht verloren, aber unsere Erfahrung hat uns enger an das Land gebunden.\n\nMein Volk erkennt Möglichkeiten, die den Draenei verschlossen bleiben. Nehmt zum Beispiel das Gift der Sumpflichtbluter, die im Süden und Westen leben. Es ist vielseitig einsetzbar, ob für die Jagd oder zur Heilung.", sourceObjective = "Bringt 6 Einheiten Sumpflichtblutergift zu Puluu in der Oreborzuflucht.", progress = "Ich hoffe, ich kann die Vorzüge des Fennblutergifts Anachoret Ahuurn und den anderen in Telredor zeigen. Aber dafür werde ich meine Vorräte verdoppeln müssen.", completion = "Vielen Dank für das Gift, {name}. Jetzt kann ich es den anderen vorführen ohne meine eigenen Vorräte anfassen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9831] = { id = 9831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Karazhan", description = "Die Neuigkeiten in diesem Bericht beunruhigen mich sehr, {name}. Es wird jedoch schwierig, sich Zugang zu Karazhan zu beschaffen.\n\nAls klar wurde, dass ich hier gestrandet bin, habe ich den Schlüssel in drei Teile zerbrochen.\n\nIch habe die Schlüsselfragmente in verzauberte Behälter gelegt, und diese dann an damals sicheren Plätzen versteckt.\n\nWegen der dunklen Veränderungen, die die Scherbenwelt durchmachen musste, sind sie heute allerdings alles andere als sicher. Das erste Fragment ist in einem Teil von Auchindoun versteckt, der nun vom Schattenrat beherrscht wird. Bringt mir dieses Fragment zurück.", sourceObjective = "Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt.", progress = "Habt Ihr das Fragment besorgt, {class}? Ihr solltet dabei besser keine Zeit verschwenden.", completion = "Das habt Ihr gut gemacht, {name}. Ich war mir nicht sicher, ob Ihr Erfolg haben würdet.\n\nDie Behälter sind mit einem mächtigen Zauber belegt, der sie vor unwürdigen Augen beschützt. Ich bin froh, dass sie Euch nicht täuschen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9832] = { id = 9832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zweite und das dritte Fragment", description = "Ich habe das zweite Fragment am Boden des Schlangensees versteckt, noch lange bevor er so hieß. Der gigantische Ablauf, der dort installiert wurde, nachdem die Naga den Ort in Beschlag genommen hatten, hat den Behälter wahrscheinlich in die Tiefen des Echsenkessels gesogen.\n\nDas dritte Fragment wird eine besonders große Herausforderung werden, da ich es in der Festung der Stürme gelassen habe, als die Naaru dort noch herrschten. Kael'thas regiert dort jetzt, und das Zimmer, in dem sich das Fragment befindet, ist jetzt ein Gefängnis.\n\nBringt mir diese beiden Fragmente, {name}. Von Eurem Erfolg hängt viel ab.", sourceObjective = "Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück.", progress = "Wie kommt Ihr mit der Suche nach den Schlüsselfragmenten voran, {name}?", completion = "Ihr habt die Fragmente. Ich bin sehr beeindruckt, {name}. Ihr habt bewiesen, dass Ihr es wert seid, den Schlüssel zu Karazhan zu besitzen.\n\nBleibt nur noch ein kleines Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[9833] = { id = 9833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichtenwege", description = "Einer der Gründe, warum uns Ikuti in die Zangarmarschen geführt hat, ist der Versuch, die Kommunikation zwischen den Draenei und Telaar, der Heimatstadt der Kurenai in Nagrand, zu verbessern. Damit die Boten schnell zwischen Telaar und Telredor hin- und herreisen können, müssen die Straßen sicher gemacht werden.\n\nAuf unserem Weg hierher wurden wir oft von Marschenfangschlitzern angegriffen. Wir konnten sie zwar abwehren, aber für einen einzelnen Boten wären sie eine besondere Bedrohung. Ihre Reihen etwas zu lichten würde viel zur Sicherheit unserer Boten beitragen.", sourceObjective = "Puluu in der Oreborzuflucht möchte, dass Ihr 12 Marschenfangschlitzer tötet.", completion = "Das sind wundervolle Nachrichten. Der Weg ist zwar immer noch nicht sicher, aber unsere Boten sind schlau und erfinderisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9834] = { id = 9834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Rüstung", description = "Maktu kann einen Draenei über Meilen hinweg an seiner schimmernden Rüstung erkennen, sogar in diesem düsteren Sumpf!\n\nMaktu will sie auslachen, aber dann erinnert er sich, dass sie nett zu den Kurenai waren, und will ihnen beibringen, wie Kurenai Rüstung herstellen.\n\nDie dunklen, schuppigen Bälge der Fennklauen ergeben die beste Rüstung, die Maktu je getragen hat. Wenn {name} Maktu ein paar dieser Bälge von den Fennklauenhauern tief im Schlangensee bringen kann, teilt er gerne seine Rüstung mit {name}.", sourceObjective = "Bringt 8 Fennklauenbälge zu Maktu in der Oreborzuflucht.", progress = "Hat {name} die Bälge für Maktu?", completion = "Das sind gute Bälge, findet Maktu. Sie werden sehr gute Rüstung geben.\n\nWer weiß? Vielleicht sind es genug, damit Maktu ein paar Rüstungen für die Draenei machen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9835] = { id = 9835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen der Ango'rosh", description = "Die kleine Gruppe von Zerschlagenen, die Ihr dort seht, sind Gesandte einer Siedlung in Nagrand. Die Kurenai, wie wir uns selbst nennen, sind Zerschlagene, die sich gerne mit den Draenei wiedervereinen möchten.\n\nMeine Gruppe ist hierhergekommen, um die Bande zwischen den Kurenai und den Draenei in Telredor zu stärken.\n\nWenn es nach den Ogern der Ango'rosh geht, wird dieser Tempel nicht mehr lange stehen. Sie haben die hohen Pilze des Prügelsumpfs vollständig gerodet und kommen immer näher an unsere Zuflucht heran. Wenn Ihr <ein Freund/eineFreundin> unseres Volkes sein möchtet, dann helft uns, diesen Feind zu besiegen.", sourceObjective = "Tötet 10 Oger der Ango'rosh und 5 Schamanen der Ango'rosh und kehrt dann zu Ikuti in der Oreborzuflucht zurück.", completion = "Für den Moment ist die Bedrohung durch die Ango'rosh gebannt, aber ich bin mir sicher, dass sie nicht so leicht aufgeben werden. Ich habe vieles von meinem früheren Leben als Draenei vergessen, aber die Hartnäckigkeit der Oger hat sich in mein Gedächtnis eingebrannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9836] = { id = 9836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung des Meisters", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", sourceObjective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", progress = "Wer seid Ihr und was wollt Ihr?", completion = "Ich erkenne diesen Schlüssel. Das ist Khadgars Schlüssel... ich habe ihn ihm natürlich noch nicht gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9837] = { id = 9837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Khadgar", description = "Ich scheine mich an zukünftige Ereignisse, die mit Euch und diesem Schlüssel zu tun haben, zu erinnern.\n\n<Medivh schaut Euch an, als hätte er einen Geist gesehen.>\n\nEuch stehen harte Zeiten bevor, {name}. Wollen wir hoffen, dass Euch Eure Stärke nicht im Stich lassen wird.\n\nDen Schlüssel werde ich Khadgar geben, wenn er zu mir geschickt wird. Ich könnte mir keinen besseren Lehrling vorstellen.\n\nMeiner Meinung nach solltet Ihr einen eigenen Schlüssel bekommen.\n\n<Medivh fasst in seine Robe und reicht Euch seinen eigenen Schlüssel.>\n\nNun zieht weiter. Und viel Glück, {class}.", sourceObjective = "Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters.", completion = "Sein eigener Schlüssel? Das ist unglaublich!\n\nIch spüre keine Störungen in unserer Zeitlinie, also nehme ich an, dass dies von vorneherein so bestimmt war. Jetzt gibt es kein Zurück mehr, {name}. Der Schlüssel gehört Euch und nur Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9838] = { id = 9838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Violette Auge", description = "Ihr wurdet mit einer großen Verantwortung betraut, {name}. Wenn man den Zeichen, die das Violette Auge beobachtet hat, trauen kann, müsst Ihr ihnen helfen.\n\nTrotz all meiner Unstimmigkeiten mit Cedric halte ich die Arbeit von Männern wie Alturus immer noch für sehr wichtig. Achtet jedoch darauf, dass sie Euch nicht ausnutzen. Denkt immer daran, dass der Schlüssel an Euch gebunden ist, nicht an sie. Aber wenn die Bedrohung in Karazhan wirklich echt ist, dann sind sie am besten dafür geeignet, Euch darauf vorzubereiten. Kehrt zurück zu Alturus und helft ihm, wo immer Ihr könnt.", sourceObjective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan.", completion = "Ich schicke Euch, um einen Bericht abzuliefern, und Ihr kommt mit einem Schlüssel zurück? Es muss mehr an Euch sein, als man mit dem bloßen Auge erkennen kann, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9839] = { id = 9839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Schmetterfaust", description = "Das Herzstück jedes Ogerstamms ist sein Anführer. Ohne Anführer werden die Ango'rosh sich zurückziehen und unter sich auskämpfen, wer der nächste Anführer wird.\n\nObwohl wir die Oger überall verstreut in dieser Gegend gesichtet haben, ist die Festung der Ango'rosh im Nordwesten ihre eigentliche Machtbasis. Sie liegt in einer Höhle auf einer kleinen Insel, die nur durch einen umgestürzten Pilz mit den Marschen verbunden ist.\n\nGeht dort hin und besiegt Oberanführer Schmetterfaust. Das sollte uns eine wohlverdiente Ruhepause geben.", sourceObjective = "Ikuti möchte, dass Ihr Oberanführer Schmetterfaust und 10 Raufer der Ango'rosh tötet. Kehrt zur Oreborzuflucht zurück, wenn Ihr die Aufgabe erfüllt habt.", progress = "Seid Ihr fertig? Habt Ihr Oberanführer Schmetterfaust besiegt?", completion = "Endlich! Vielen Dank für die Hilfe bei der Sicherung unserer Stellung hier in der Oreborzuflucht. Ich werde den Kurenai in Telaar in Nagrand von Euren Taten berichten. Es werden sich noch viele Gelegenheiten bieten, in denen unsere Völker zusammenarbeiten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9840] = { id = 9840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung der Situation", description = "Jetzt, da wir - oder besser Ihr - einen Weg zurück in Medivhs' Turm gefunden haben, müssen wir als Erstes herausfinden, wie die Situation im Inneren aussieht.\n\nEine unserer Agentinnen hat es geschafft, sich in Karazhan einzuschleusen und hielt ihre Beobachtungen in verschlüsselten Aufzeichnungen fest. Unglücklicherweise wurden wir über ihren Tod informiert, kurz bevor Karazhan geschlossen wurde. Koren, der Schmied von Karazhan, wird von uns bezahlt. Auch wenn er kein Mitglied des Violetten Auges ist, wird er uns sicher helfen können, Keannas Aufzeichnungen zu finden. Sucht ihn innerhalb von Karazhan.", sourceObjective = "Findet Koren in Karazhan.", completion = "<Koren sieht Euch unsicher an.>\n\nIch weiß nichts von diesem Violetten Auge, von dem Ihr da redet. Ich bin ein Schmied, sonst nichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[9841] = { id = 9841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tückische Mücken", description = "Ich kann mit diesem infernalen Gesumme nicht arbeiten! Könnt Ihr es hören?\n\nIch bekomme es nicht mehr aus meinem Kopf! Ich weiß genau, wer dieses Geräusch verursacht, Sumpflichtbluter! Das Geräusch kommt immer vom Süden und vom Westen des Dorfs her.\n\nSie sind zu groß, um sie mit einer Fliegenklappe zu erschlagen, sie unter dem Fuß zu zerquetschen oder fortzuwedeln. Der einzige Weg dieses fürchterliche Dröhnen zu beenden ist sie zu töten. Mir ist ganz egal, wie Ihr es tut, {name}, aber bringt sie zum Schweigen!", sourceObjective = "Tötet 8 Sumpflichtbluter und kehrt dann zu Gambarinka in Zabra'jin zurück.", completion = "Dachte ich es mir, Ich kann den Unterschied schon deutlich hören. Dank Euch werde ich endlich wieder arbeiten können. Falls Ihr jemals Handwerkswaren benötigen solltet, denkt an den alten Gambarinka!", sourceObjectiveStatus = "unverified-source-field" }
quests[9842] = { id = 9842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schärfsten Klingen", description = "Das feuchte Klima der Marschen hat meine metallenen Werkzeuge stark in Mitleidenschaft gezogen. Das macht die Holzarbeiten schwerer als sonst, weshalb ich nun ganz auf Metallklingen verzichte.\n\nEs hat sich herausgestellt, dass die Marschenfangschlitzer im Süden und im Westen über Klingen verfügen, die schärfer sind als jede Metallklinge, die ich je besessen habe. Sie rosten auch nicht und nutzen sich nicht ab. Es ist nur ein wenig schwer, sie an einem Griff zu befestigen, aber ich glaube, ich habe dieses Problem bereits gelöst. Ich wäre Euch für jede Klinge, die Ihr mitbringen könnt, sehr dankbar.", sourceObjective = "Bringt 10 Marschenfangschlitzerklingen zu Gambarinka in Zabra'jin.", progress = "Habt Ihr ein paar Marschenfangklingen auftreiben können?", completion = "Die sollten mir für eine Weile genügen! Ich glaube, ein paar andere sind schon darauf aufmerksam geworden. Ich hatte schon ein paar Angebote, mir die Klingen abzukaufen. Sie nebenbei zu verkaufen könnte vielleicht ein einträglicheres Geschäft als meine herkömmlichen Waren bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9843] = { id = 9843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Aufzeichnungen", description = "Wen sucht Ihr noch gleich? Keanna?\n\nIch habe einst jemanden mit diesem Namen getroffen. Sie wohnte oben in den Gästezimmern. Das hätte ich nicht verraten dürfen, oder?\n\nSagtet Ihr, Ihr gehört zum Violetten Auge? Nein, davon habe ich noch nie gehört.\n\nIch muss jetzt zurück an die Arbeit, wenn es Euch nichts ausmacht.\n\n<Koren scheint Euch schon vergessen zu haben.>", sourceObjective = "Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan.", progress = "Keannas Aufzeichnungen... habt Ihr sie gefunden?", completion = "Ihr habt die Aufzeichnungen gefunden. Ich hoffe, dass die Information, die wir brauchen, auch hier drin stehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9844] = { id = 9844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dämonische Präsenz", description = "Keannas letzte Einträge bestätigen unseren Verdacht, dass sich eine dämonische Präsenz in Karazhan befindet.\n\nSie hat die Ankunft eines Agenten der Brennenden Legion entdeckt, der sich in der Nähe der Turmspitze aufhalten soll.\n\nIhr Eintrag endet hier.\n\nKarazhan ist ein sehr wichtiger Ort, {class}. Es ist ein Portal in den Nether, ein Leuchtfeuer, das in andere Welten scheint. Wenn es in falsche Hände gerät, sind die Folgen unvorstellbar. Das Eindringen der Dämonen muss unbedingt aufgehalten werden. Und außer Euch, {name}, hat niemand einen Schlüssel.", sourceObjective = "Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört.", progress = "Ich scheue mich zu fragen, {name}, aber wie sieht es mit der Situation in Karazhan aus?", completion = "Ihr habt es geschafft! Ja, die Aufzeichnungen normalisieren sich wieder!\n\nDas müssen wir Cedric berichten. Er wird von unseren Errungenschaften sehr beeindruckt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9845] = { id = 9845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerunglück", description = "Welch Erleichterung, dass ich endlich an einem Ort mit Wasser angekommen bin! Ich hatte schon Angst, dass es keine anständigen Fischgründe hier in der Scherbenwelt gibt.\n\nJetzt bin ich doch froh, dass ich meine Angelausrüstung mitgenommen habe. Und das Fischen läuft soweit auch ganz gut, wenn da nicht diese nichtsnutzigen Fennklauenhauer im Schlangensee wären.\n\nSie verscheuchen mir nicht nur die Fische, sondern sind auch noch frech genug, mir die Köder direkt vom Haken zu stehlen! Ich verbringe mehr Zeit damit, neue Köder anzubringen, als tatsächlich etwas zu fangen!", sourceObjective = "Tötet 10 Fennklauenhauer und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Ich kann es gar nicht erwarten endlich wieder angeln zu gehen. Jetzt werde ich endlich mit echten Fischen in meinem Eimer ins Dorf zurückkehren können, und Gambarinka wird sich nicht mehr über mich lustig machen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[9846] = { id = 9846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Wildfenn", description = "Der mächtigste Stamm der Verirrten in den Marschen, der Wildfennstamm, soll eine mächtige Medizin besitzen. Vielleicht ist an solchen Gerüchten nichts Wahres dran, aber ich muss allem nachgehen, was mir dabei helfen kann, die Geister dieser Welt zu lenken.\n\nFindet die Mystiker, Jäger und Druiden von Wildfenn, {name}, und nehmt Euch ihre Totems. Alles, was ich wissen muss, werde ich aus den Schnitzereien erfahren können.", sourceObjective = "Bringt 10 Schutztotems von Wildfenn zu Seherin Janidi in Zabra'jin.", progress = "Habt Ihr die Totems schon gesammelt?", completion = "Hmm... Es scheint, als wäre die eine Hälfte mit Bildern von Schlangegeister, die andere mit Bildern von Vogelgeistern verziert. Kein Dunkelspeertroll mit Selbstachtung würde jemals Vögel verehren. Ihre Geister sind schwach, launisch und besser bei den Schamanen der Amani aufgehoben.\n\nAber die Schlange, {name}, die Schlange hat beträchtliche Kräfte und ist daher der Geist, dem ich meine Studien widmen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9847] = { id = 9847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbündeter Geist?", description = "Wir müssen herausfinden, welche Kräfte dieser Schlangengeist von Wildfenn besitzt und ob wir sie für unsere Zwecke einsetzen können. Stellt Euch nur vor, was ich alles tun könnte, wenn ich über einen Geist der Scherbenwelt befehligen könnte!\n\nNehmt dieses Totem und begebt Euch an den Fuß der Treppe zu den Ruinen von Boha'mu. Verankert das Totem dort in der Erde, den Rest wird es selbst erledigen. Der Geist dürfte nicht wissen, wer das Totem benutzt hat, bis er sich manifestiert hat.", sourceObjective = "Bringt das Wildfenntotem an den Fuß der Treppe in den Ruinen von Boha'mu und verankert es im Boden. Berichtet Seherin Janidi in Zabra'jin von Euren Beobachtungen.", progress = "Konntet Ihr den Geist von Wildfenn rufen?", completion = "<Ihr berichtet Seherin Janidi, was passiert ist, als Ihr das Totem benutzt habt.>\n\nDer Geist hat euch angegriffen? Er muss diesen Verirrten wohl mehr zugetan sein, als ich dachte. Es gibt keine Möglichkeit, ihn mir gefügig zu machen, ohne immensen Aufwand zu betreiben. Ich muss mich wohl nach einer anderen Quelle der Macht in dieser elenden Welt umsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9848] = { id = 9848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Dolchfennstamms", description = "Käfer, Käfer, Käfer! Die Marschen sind voll davon, und meine Gefährten hier scheinen ganz besessen von ihnen zu sein.\n\nNun, ich habe genug von Käfern! Etwas viel Aufregenderes hat mein Interesse geweckt. Im Westen gibt es ein Dorf der Verirrten, das Dolchfenn genannt wird.\n\nDer gesamte Stamm besteht aus hochbegabten Auftragsmördern. Ich habe gesehen, wie sie ein bestimmtes hochwirksames Gift mischen und verwenden. Ich würde liebend gerne mehr darüber erfahren, aber dazu bräuchte ich eine Abschrift des Rezepts und eine Phiole mit einer Probe des Gifts.", sourceObjective = "Bringt das Gifthandbuch von Dolchfenn und eine Giftphiole von Dolchfenn zu Timothy Daniels in der Oreborzuflucht.", progress = "War Eure Suche in Dolchfenn nach den Informationen, die ich zur Lösung des Gifträtsels benötige, erfolgreich?", completion = "<Timothy blättert das Handbuch durch.>\n\nSie benutzen Zottelkappe als Grundlage für das Gift? Nein, das kann nicht richtig sein. Zottelkappe ist nicht giftig.\n\nZottelkappe in ein Gift zu mischen ist so sinnvoll, wie einem Schurken zwei Streitkolben in die Hand zu drücken. Sicher, man kann das zwar tun, aber das entspricht nicht dem Wesen Eurer Berufung! Ich kann das einfach nicht verstehen...\n\n<Timothy räuspert sich.>\n\nNun ja, danke dass Ihr mir das hier besorgt habt. Ich werde das Gift ausprobieren, sobald die Zeit es mir erlaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9849] = { id = 9849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maskerade durchschauen", description = "<Gordawg bricht einen ebenholzfarbenen Fels von seinem Rücken ab.>\n\nIch gewähre Euch ein Stück Wut der Erde. Nehmt Gordawgs Fels und werft ihn auf den Giftfels. Zerschlagt ihre Hüllen um die Wahrheit zu erfahren. Vernichtet die Diener des Thronräubers und kehrt mit dem Namen zu Gordawg zurück.\n\nIhr findet die zerschlagenen Elemente am Ende der Welt. Südwesten.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 30 Diener von Gurok tötet.", progress = "Gordawg will den Stein zurück.", completion = "GUROK! Gurok hat die Elemente verraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[9850] = { id = 9850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Ihr habt mir gezeigt, dass Ihr in der Lage seid, die harmlosen Exemplare der Grollhufe zu erlegen. Doch viel gefährlicher sind die Bullen.\n\nErledigt zwölf von denen. Dann könnt Ihr Euch vor mir mit Eurem Jagdgeschick brüsten.\n\nIhr findet sie überall im Westen und Süden der mittleren Regionen Nagrands.", sourceObjective = "Tötet 12 Grollhufbullen und sprecht anschließend mit Hemet Nesingwary bei Nesingwarys Safari in Nagrand, um Euer Jagdgeschick zu beweisen.", completion = "Beeindruckend, sehr beeindruckend.\n\nIhr habt Potential, Jungspund. Ich werde Euch die Möglichkeit geben, richtig viel Spaß zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9851] = { id = 9851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Das Grollhufweibchen Banthar ist der meistgefürchtete und am schwersten zu fassende Grollhuf der gesamten Scherbenwelt. Sie ist außerdem das Exemplar mit dem längsten Fell ihrer Gattung.\n\nMan sagt, sie treibt sich auf den Geisterfeldern in der Nähe des Oshu'gun herum.\n\nBringt mir ihr Horn, um mir endgültig Euer Können in den Jagdkünsten zu beweisen.", sourceObjective = "Erlangt das Horn von Banthar und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück.", progress = "Ein warmes Feuer und eine Frau an Eurer Seite könnt Ihr daheim finden. Hier jagen wir ernsthaft oder sterben bei dem Versuch.", completion = "Ihr habt es tatsächlich geschafft! Ihr habt Banthar erlegt! Ich habe niemals an Euch gezweifelt, {name}.\n\nHier, ich denke, das habt Ihr Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9852] = { id = 9852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ultimative Beute", description = "Die Königin aller Tiere in Nagrand ist Zahna. Sie ist ein riesiger Elekk von der Sorte, wie Ihr sie woanders nie zu sehen bekommen werdet!\n\nIhr tut gut daran, Euch bei dem Namen zu erschrecken. Bach'lor, Aaskralle und Banthar sind nichts im Vergleich zu ihr. Man sagt, dass sie sich auf einer riesigen Klippe weit im Südwesten in der Nähe des Oshu'gun aufhält. Bringt mir ihr Herz, wenn Ihr Euch traut.\n\nWollt Ihr mir einen Brief für Eure Familie dalassen, falls Ihr, was sehr wahrscheinlich ist, nicht zurückkommt?", sourceObjective = "Bringt das Herz von Zahna zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand.", progress = "Es ist keine Schande zuzugeben, dass Ihr nicht den Mumm habt, eines der mächtigsten Tiere die dieses Land zu bieten hat, zu erlegen, {name}.", completion = "{name}! Ihr bringt das Herz dieses alten Zwergs zum Springen.\n\nIhr habt Euch nun bewiesen und seid in die Eliteränge aufgestiegen! Andere sind voller Angst geflüchtet, sind gestorben oder wurden unter den Füßen des Tieres zerquetscht. Ihr habt Euren Verstand, Eure List und Eure Entschlossenheit genutzt, um zu beweisen, dass Ihr die Jagd beherrscht.\n\nNehmt dies und seid gewiss, dass Ihr jederzeit zur Jagd an meiner Seite willkommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9853] = { id = 9853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurok der Thronräuber", description = "Gurok muss gerufen werden. Ihr ruft Gurok und Ihr vernichtet.\n\nIhr müsst zum Totschlägerhügel im Nordwesten gehen und suchen, wo Oger Gurok verehren. Ihr setzt Ogerschädel von Totschläger auf Guroks irdenes Brandmal. Nur dann kommt Gurok. Sieben Schädel.\n\nWenn Ihr lebt, dann bringt Guroks irdenen Kopf zu Gordawg. Gordawg zerschmettert Kopf.\n\n<Gordawg beißt die Zähne so fest zusammen, dass der Boden unter Euren Füßen bebt.>", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr Gurok den Thronräuber zerstört und Guroks irdenen Kopf besorgt.", progress = "Gordawg isst Gurokpulver.", completion = "<Gordawg beißt fest in Guroks irdenen Kopf und bringt die Steinformation fast zum Bröckeln.>\n\nGuroks Herrschaft ist zu Ende. Die Erdelementare sind frei. Schlafen alle. Gewinner bekommt Preis!", sourceObjectiveStatus = "unverified-source-field" }
quests[9854] = { id = 9854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Lebt Ihr genauso für die Jagd wie ich, {class}? Sucht Ihr die Ruhe, die Euch überkommt, wenn Ihr Euch an Eure Beute heranpirscht? Wisst Ihr, was es bedeutet, die letzten Herzschläge der erlegten Beute zu ehren? Ich werde Euch helfen, dies zu erreichen.\n\nNagrand ist ein blühendes Land, voller Leben inmitten dieser zerschlagenen Welt. Erlegt ein paar Windrocs und dann unterhalten wir uns weiter.\n\nIhr könnt sie an vielen Orten um unser Lager herum finden.", sourceObjective = "Tötet 12 Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", completion = "Jeder Tag ist ein Geschenk. Macht das Beste daraus. Denn schon morgen werden wir uns schneller fortbewegen als heute. Wir werden unsere Arme weiter ausbreiten und uns anstrengen, um das zu erzielen, von dem wir heute Nacht noch träumen, auch wenn wir es vielleicht nie erreichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9855] = { id = 9855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Ihr müsst immer im Training bleiben, wenn Ihr eines Tages die mächtigste Beute überhaupt erlegen möchtet! Jetzt seid Ihr noch nicht dafür bereit, aber ich werde Euch auf den richtigen Weg bringen.\n\nEs gibt noch eine tödlichere Art von Windrocs. Messt Euch an den gefräßigen Windrocs! Ihr findet sie im Herzen von Nagrand, im Süden und im Südwesten.", sourceObjective = "Tötet 12 gefräßige Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", completion = "Ihr habt Eure Fähigkeiten erneut unter Beweis gestellt, {class}. Jetzt müsst Ihr Euch mit der wildesten Sorte von Windrocs messen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9856] = { id = 9856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Ihr seid bereit, {class}. Bereit Euch der Mutter aller Windrocs zu stellen, Aaskralle! Nachdem Ihr so viele ihrer Kinder getötet habt, gebietet die Ehre, dass ihr eine Chance auf Rache gewährt wird. Ihr findet sie bei den großen Windrocs weit im Westen.\n\nWenn Ihr überleben solltet, bringt mir ihr Auge.", sourceObjective = "Bringt das Auge von Aaskralle zu Fitz bei Nesingwarys Safari in Nagrand.", progress = "Habt Ihr Euch Aaskralle schon gestellt?", completion = "Ihr Auge sieht aus, als wäre es noch am Leben. Denkt Ihr, sie kann immer noch in Eure Seele schauen?\n\n{name}, Ihr könnt Euch zu den Elitesafarijägern zählen. Und Ihr seid auf dem besten Weg, die entscheidende Beute dieses Landes zu jagen, Zahna!\n\nIhr habt Euch das hier verdient. Möge es Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9857] = { id = 9857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "Ich habe heute keine Lust zu jagen. Könnt Ihr das für mich übernehmen?\n\nIch habe Hemet gesagt, dass ich mich um ein paar von den Talbuks kümmern würde, die hier überall herumlaufen. Die Böcke sind besonders gut zu jagen. Ihr könnt sie in kleinen Gruppen unter den Bäumen in der Nähe finden.\n\nDenkt Ihr, Ihr könntet das für mich tun?", sourceObjective = "Tötet 12 Talbukhirsche und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", completion = "Das ist schon eine tolle Geschichte...<hust>...wie Ihr all die Hirsche erlegt habt, {class}. Aber das könnt Ihr sicher noch besser. Ich habe da etwas anderes für Euch im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9858] = { id = 9858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "Diese verdammte Schramme macht mir echt zu schaffen. Also, habt Ihr Lust, nochmals...<hust>...für mich einzuspringen?\n\nDieses Mal werdet Ihr ein paar Dornzehrer erlegen. Sie sind härter und gerissener als die Hirsche, also seid auf der Hut. Sucht sie...<hust>..unter den Bäumen in den mittleren Gebieten Nagrands im Süden und Westen.\n\nAuf, geht los und...<hust>.. zeigt Hemet aus welchem Holz Ihr geschnitzt seid. Mir wird es schon gut gehen.", sourceObjective = "Erlegt 12 Talbukdornzehrer und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", completion = "<hust>, <hust>... {name}! Ihr habt es geschafft. Jetzt gibt es... ...nur noch eine Sache......zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9859] = { id = 9859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "<Schlimmer Husten.>\n\nMacht Euch keine Sorgen um...<hust>... mich. Mir geht es gut. Es ist nur ein...<hust>... Kratzer.\n\nDennoch müsst Ihr...<hust>... nochmal für mich...<hust>... einspringen.\n\nIhr müsst den großen Bach'lor, König der Hirsche...<hust>... finden.\n\nBringt mir einen seiner Hufe...<hust>, <hust>... als Beweis.\n\nEr führt seine Herde...<hust>... weit im Westen von Nagrand.", sourceObjective = "Besorgt den Huf von Bach'lor und bringt ihn zu Harold Fährten bei Nesingwarys Safari in Nagrand.", progress = "<Harold schaut geschwächt zu Euch hoch und ringt sich ein Lächeln ab.>\n\nHabt Ihr...<hust>... den Huf?", completion = "Wow! Ihr habt es geschafft! Das ist tatsächlich Bach'lors Huf!\n\nÄhm, wie es aussieht fühle ich mich schon viel besser. Hier, lasst mich Euch etwas zur Feier Eures Jägerkönnens schenken!", sourceObjectiveStatus = "unverified-source-field" }
quests[9860] = { id = 9860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Anweisungen", description = "Kehrt sofort zu Cedric zurück, {name}. Die Unterstützung, die Ihr dem Violetten Auge geleistet habt, wird nicht unbelohnt bleiben.\n\nHaltet von uns und unserer Organisation was Ihr wollt, {class}, aber in der Gunst der Erzmagier von Dalaran zu stehen ist nichts, was Ihr je bereuen werdet.", sourceObjective = "Sprecht mit Erzmagier Cedric am Rande des Dalarankraters.", completion = "Alturus hat mir erzählt, was passiert ist, {name}. Wir sind jedoch noch nicht am Ende angelangt. Solange Karazhan für die Außenwelt verschlossen ist, ist es nur eine Frage der Zeit, bis die Legion ihre Angriffe erneuert, während wir nur tatenlos zusehen können.\n\nEs sei denn natürlich, Ihr nehmt die Verantwortung, die Euch das Schicksal auferlegt hat, an.\n\n\n\nWas sagt Ihr, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9861] = { id = 9861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heulende Wind", description = "Die formlose Elementarluftgestalt spricht in einer Sprache zu Euch, die Ihr nicht versteht. Ihr glaubt, dass es die Sprache der Elemente ist, Kalimag. Vielleicht kann Euch jemand beim Thron der Elemente mit dieser ungewöhnlichen Entdeckung weiterhelfen.", sourceObjective = "Sucht beim Thron der Elemente nach jemandem, der Kalimag sprechen kann und zeigt der Person den heulenden Wind.", progress = "Gebt es her, schnell!", completion = "Es ist ein Notruf, {race}. Eine Macht versucht die Elemente zu untergraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9862] = { id = 9862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte der Finsterblut", description = "Der Finsterblutstamm fängt die Luftgeister ein und quält sie! Die Finsterblut gehören zu meinem Volk. Sie sind ein Stamm von Zerschlagenen, der dem bösen Musel'ek, dem Sumpflord des Echsenkessels, dient.\n\nDer Luftgeist sagt, dass die Verderber der Finsterblut andere Luftgeister fangen und sie benutzen, um Chaos in den Reihen der Elemente zu säen. Wie es aussieht haben die Finsterblut vor Kurzem ein Orcdorf im Südwesten namens Sonnenwind geplündert und benutzen nun mächtige Elementarmagie, um den See aufzuwühlen. Sucht die Verderber und vernichtet sie!", sourceObjective = "Elementarist Morgh beim Thron der Elemente in Nagrand möchte, dass Ihr 5 Verderber der Finsterblut tötet.", completion = "Ihr habt gesehen, wie sie die Elemente kontrollieren? Der Wind beugt sich ihrem Willen?\n\n<Morgh versinkt für einen Moment in Gedanken.>\n\nDas ist sehr beunruhigend, {name}. Ich muss mich mit den anderen beraten.\n\nVielen Dank für Eure Mühen, {name}. Vielleicht solltet Ihr in Euer Dorf zurückkehren und Euch umhören, ob es weitere Informationen über die Finsterblut und ihre schändlichen Ziele gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9863] = { id = 9863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheulicher Götzendienst", description = "Ohne Führung sind wir von allen Seiten angreifbar! Die niederträchtigen Finsterblut hätten keinen besseren Zeitpunkt auswählen können, um uns anzugreifen.\n\nIn den letzten Tagen mussten wir nicht weniger als fünf Angriffe von den Zerschlagenen ertragen! Sie haben sich sogar unserer Siedlung in dieser Gegend, des Sonnenwindpostens, bemächtigt.\n\nWir müssen zurückschlagen und ihnen zeigen, das wir ganz und gar nicht machtlos sind. Erschlagt die widerlichen Götzendiener und bringt mir ihre abscheulichen Götzen! Möge der Blitz sie treffen!", sourceObjective = "Scharfseher Kurkush in Garadar in Nagrand möchte, dass Ihr ihm 10 Finsterblutgötzen bringt.", progress = "Tut es für uns, weil wir es nicht für uns selbst tun können.", completion = "Ihr habt den Söhnen des Blitzschlags neue Hoffnung gegeben, {name}. Wenn unser Anführer uns schon nicht beschützt, vielleicht können es andere tun - so wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[9864] = { id = 9864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschollene Kampftrupp", description = "Nach dem letzten Angriff der Finsterblut hat eine Gruppe von Jünglingen sich aufgemacht, um uns zu rächen. Wir haben versucht sie aufzuhalten, aber ihre Wut hat sie blind werden lassen. Es ist nun eine Woche vergangen seit wir sie das letzte Mal gesehen haben.\n\nBitte, {race}, Ihr müsst sie finden! Sie sind doch gerade erst erwachsen geworden. Wie können sie erwarten, diese Wilden besiegen zu können?\n\nSie haben die Straße nach Westen aus der Stadt genommen. Folgt dieser Straße und haltet nach Lebenszeichen unserer Jünglinge Ausschau.\n\nUnd {name}, haltet Euch von Halaa fern, wenn Euch Euer Leben lieb ist. Dort ist Kriegsgebiet.", sourceObjective = "Sucht den verschollenen Kriegstrupp von Garadar.", completion = "Ich habe Geschichten über unser Volk gehört. Sie sagen, dass wir einst Krieger waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[9865] = { id = 9865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chroniken eines Kriegers", description = "Ich kenne Euch nicht, Fremder, aber ich muss Euch um Hilfe bitten. Ich schäme mich dafür, aber ich bin nur ein einziger Orc.\n\nIn mir kochen Emotionen hoch, die ich vorher nie gekannt habe. Ich.. Ich will Rache. Blut für Blut. Kennt Euer Volk dieses Gefühl? Ich möchte meine Axt nehmen und meine Feinde in Stücke schlagen. Meine Waffe schwingen, bis meine Arme nicht mehr können und erschlaffen.\n\nDer Sonnenwindposten ist gleich südlich von dieser Prozession hier. Dort werdet Ihr unsere Feinde finden. Tötet sie... Tötet sie alle...", sourceObjective = "Tötet 20 Strauchdiebe der Finsterblut und 10 Räuber der Finsterblut.", completion = "<Saurfang dreht sich zu Euch um.>\n\nRieche ich da etwa Blut? Ich bedauere es sehr, dass ich Euch nicht helfen konnte. Wie stolz Ihr auf Euch sein müsst. Meine Brust hebt sich allein von dem Wissen, was Ihr getan habt.\n\nGibt es noch mehr wie euch? Gibt es noch mehr Helden dort, wo Ihr herkommt?", sourceObjectiveStatus = "unverified-source-field" }
quests[9866] = { id = 9866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter...", description = "Würdet Ihr mir eine letzte Ehre erweisen, {name}? Ich möchte nicht nach Garadar zurück. Ich glaube, dass mein Schicksal woanders liegt, dass ich einst höheren Zielen folgen werde.\n\nBitte geht zu Scharfseher Corhuk und sagt ihm, dass ich nicht zurückkehren werde. Dass ich nicht zurückkehren kann. Ich muss weiterziehen... Er wird es verstehen.", sourceObjective = "Bringt die Nachricht zu Scharfseher Corhuk in Garadar.", completion = "<Weissager Corhuk starrt gedankenverloren auf den Boden. Er nickt zustimmend.>\n\n<Weissager Corhuk wischt sich eine Träne aus dem Gesicht.>\n\nDer Sohn ist der Vater... Mögen die Geister gnädig zu denen sein, die ihm im Weg stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9867] = { id = 9867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Finsterblut...", description = "Wir haben in den letzten Wochen viele Freunde verloren.\n\nSchon seit Jahrzehnten kämpfen wir gegen die Oger aus Nagrand, aber nun ist eine neue Bedrohung aufgetaucht. Der Finsterblutstamm der Zerschlagenen hat unser Fischerdorf im Südwesten, den Sonnenwindposten, angegriffen und alle Orcs, die dort lebten, getötet oder vertrieben.\n\nDie anderen sind der Meinung, dass man sie einfach wahllos töten sollte. Ich bin jedoch davon überzeugt, dass man ihren Anführer töten muss. Ich weiß zwar nicht, wer ihr Anführer ist, aber ich schätze, Ihr werdet es merken, wenn Ihr ihn seht.", sourceObjective = "Bringt Ortor von Finsterbluts Kopf zu Weissager Margadesh in Garadar in Nagrand.", progress = "Bringt mir den Kopf ihres Anführers, {name}.", completion = "Das ist also das Gesicht unseres Feindes? Ich werde den Kopf aufspießen lassen und außerhalb von Garadar aufstellen. Sollten sie je wagen, uns nochmals anzugreifen, werden sie den Folgen ihres Handelns in die Augen sehen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9868] = { id = 9868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem von Kar'dash", description = "Habt Dank, Fremder. Wenn Ihr nicht gewesen wärt, hätten sie mich sicherlich getötet.\n\nIch wurde vor drei Nächten von diesen Finsterblut bei einem Nachtangriff auf Garadar entführt. Was ich seitdem herausgefunden habe, wird wahrscheinlich die ganze Scherbenwelt in ihren Grundfesten erschüttern: diese Finsterlinge versuchen, das Totem von Kar'dash wiederzuerlangen! Wir können nicht zulassen, dass das Totem in die Hände der Finsterblut fällt!\n\nIhr müsst mir helfen zu fliehen. Und Fremder, falls ich es nicht bis Garadar schaffe, müsst Ihr Garrosh erzählen, was hier passiert ist...", sourceObjective = "Begleitet den festgehaltenen Mag'har aus dem Sonnenwindposten hinaus. Sprecht mit Garrosh in Garadar, wenn Ihr erfolgreich wart.", completion = "Was macht das schon? Die Großmutter liegt im Sterben. Das Leben ist nicht lebenswert...", sourceObjectiveStatus = "unverified-source-field" }
quests[9869] = { id = 9869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thron der Elemente", description = "Grüße, {race}. Ich bin Ioki, Elementarist des Irdenen Rings. Ich bin nach Telaar gekommen, um die Kurenai über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Telaar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", sourceObjective = "Elementarist Ioki möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9870] = { id = 9870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thron der Elemente", description = "Grüße, {race}. Ich bin Yal'hah, Elementarist des Irdenen Rings. Ich bin nach Garadar gekommen, um die Mag'har über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Garadar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", sourceObjective = "Elementarist Yal'hah möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9871] = { id = 9871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Finsterblut", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Telaar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Arechron in Telaar.", sourceObjective = "Bringt die Invasionspläne der Finsterblut zu Arechron nach Telaar in Nagrand.", progress = "Was gibt's?", completion = "<Arechron schlägt mit der einen Hand in die andere.>\n\nOrtor... Dieser verräterische Dreckskerl!", sourceObjectiveStatus = "unverified-source-field" }
quests[9872] = { id = 9872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Finsterblut", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Garadar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Garrosh in Garadar.", sourceObjective = "Bringt die Invasionspläne der Finsterblut zu Garrosh.", progress = "Was gibt es?", completion = "<Garrosh zerknüllt die Karte und wirft sie ins Feuer.>\n\nWas soll ich damit? Sie greifen uns schon seit Wochen an. Das ist nichts neues.\n\nVersteht Ihr nicht? Wir sind geliefert... Großmutter Geyah liegt im Sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9873] = { id = 9873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein alter Freund Ortor...", description = "Diese Angriffpläne wurden von jemandem geschrieben, den ich einst kannte. Ortor von Finsterblut, ein adliger Zerschlagener, bewandert in der Beherrschung der Elemente, der nun den dummen, stinkenden Lakai für Sumpffürst Musel'ek spielt.\n\nDie Pläne besagen, dass sie ein Orcdorf nordwestlich von hier, das als Sonnenwindposten bekannt ist, eingenommen haben.\n\nReist zum Sonnenwindposten und erlöst die Welt von Ortor von Finsterblut. Es geschieht zum Wohl aller...", sourceObjective = "Arechron in Telaar in Nagrand möchte, dass Ihr Ortor von Finsterblut tötet.", completion = "Tausend tote Orcs sagt Ihr? Was könnte wohl der Auslöser für solch ein unverfrorenes Vordringen in Orcgebiet sein? Es ist gut, dass er tot ist, aber da steckt mehr dahinter, als ein Tentakel fühlen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9874] = { id = 9874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung eindämmen", description = "Ich habe gerade von einer Katastrophe mit epischen Ausmaßen erfahren, {name}. Die niederträchtigen Finsterblut haben das Orcdorf Sonnenwind nordwestlich von hier eingenommen und seine Einwohner getötet. Was das Ganze noch verschlimmert ist, dass sie begonnen haben, die Leichen in den Sonnenwindsee zu werfen. Wenn die Leichen dort verrotten, wird unsere Hauptwasserquelle in dieser Gegend verseucht werden.\n\nEs ist eine grauenvolle Aufgabe, die ich Euch übertrage, aber sie muss erledigt werden. Nehmt diese verzauberte Fackel und kehrt zum Sonnenwindposten zurück. Verbrennt alle verrottenden Orcleichen...", sourceObjective = "Otonbu der Weise in Telaar in Nagrand möchte, dass Ihr die Fackel des flüssigen Feuers benutzt, um 10 Leichen von Bewohnern von Sonnenwind zu zerstören. Bringt die Fackel des flüssigen Feuers zurück, wenn Ihr fertig seid.", progress = "Die Orcs werden nicht verstehen, warum wir das tun, aber es muss getan werden. Für das Wohl der Orcs sowie der Zerschlagenen.", completion = "<Otonbu seufzt.>\n\nDas macht uns jegliche Hoffnung auf Frieden mit den Orcs für weitere zehn Jahre zunichte. Zumindest werden wir diese zehn Jahre noch erleben, was wir vielleicht nicht hätten, wenn die Leichen im See verrottet wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[9875] = { id = 9875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht katalogisierte Gattung", description = "Lauranna muss diese besondere Pflanze übersehen haben. Ihr seid Euch sicher, dass Ihr eine Gattung gefunden habt, die noch nicht in Laurannas Buch katalogisiert ist. Ihr solltet sie ihr am besten zeigen, um zu sehen, was sie davon hält.", sourceObjective = "Bringt die nicht katalogisierte Gattung zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet?", completion = "Eine neue Gattung! Seid Ihr sicher?\n\n<Lauranna blättert die Notizen und Diagramme durch.>\n\nToll gemacht, {name}. Wir werden sie unserer Liste hinzufügen. Was haltet Ihr von \"Violettblättriges Kollimium\"? Ich finde, das ist ein klangvoller Name.", sourceObjectiveStatus = "unverified-source-field" }
quests[9876] = { id = 9876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlgeschlagene Operation", description = "Ich habe eine kleine Gruppe von Druiden losgeschickt, um den Ablauf, den Ihr im Schlangensee gefunden habt, zu untersuchen. Eigentlich hätten sie kurz darauf zurückkommen müssen. Nun ja, sie sind nicht zurückgekehrt.\n\nIhr zählt zu unseren stärksten Verbündeten. Bitte sucht sie und findet heraus, was ihnen zugestoßen ist.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr am Eingang des Echsenkessels in den Zangarmarschen nach Lebenszeichen der Druiden der Expedition des Cenarius Ausschau haltet.", completion = "Cenarius sein Dank, dass Ihr hier seid. Wegen meiner Verletzungen konnte ich nicht nach draußen zurück, um Hilfe zu holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9877] = { id = 9877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Regenerationsgebräu", description = "Der Kampf gegen die Geißel verläuft nicht ohne Opfer. Viele fallen jeden Tag, doch einige erwartet ein noch schlimmeres Schicksal.\n\nOft nimmt sie Gefangene. Der Tod wäre dem, was sie in der Todesfestung erwartet, vorzuziehen. Sie werden verhört und gefoltert, während sie unter dem Einfluss eines schrecklichen, willensbrechenden Giftes stehen.\n\nApotheker Renzithen in Tristessa hat ein Gegenmittel entwickelt; geht zu ihm und holt das Regenerationsgebräu.", sourceObjective = "Sprecht mit Apotheker Renzithen in Tristessa.", completion = "Janeda schickt Euch, um die Gefangenen der Todesfestung zu retten? Sie muss eine hohe Meinung von Euch haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9878] = { id = 9878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lösung des Problems", description = "Das Auftauchen der Finsterblut in Nagrand hatte einen sehr negativen Einfluss auf unsere Umwelt. Die Elemente sind aufgebracht, was wiederum die Wildtiere stört. Und noch viel schlimmer: die Zerstörung des Sonnenwindpostens hat die Feindschaft der Orcs gegen mein Volk neu entflammt.\n\nDie Kurenai sind zwar ein ganz anderer Stamm als die Finsterblut, aber für einen Orc ist ein Zerschlagener ein Zerschlagener.\n\nWir müssen versuchen, dieses Dilemma zu lösen. Reist nach Nordwesten zum Sonnenwindposten und erledigt das Finsterblutproblem.", sourceObjective = "Poli'lukluk der Weisere in Telaar in Nagrand möchte, dass Ihr 10 Strauchdiebe der Finsterblut und 5 Räuber der Finsterblut tötet.", completion = "Ich glaube kaum, dass die Orcs verstehen oder zu schätzen wissen, was Ihr da getan habt, aber Eure Tat war gut für Nagrand. Vielen Dank, Problemlöser...", sourceObjectiveStatus = "unverified-source-field" }
quests[9879] = { id = 9879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem von Kar'dash", description = "Ich wäre schon tot, wenn Ihr nicht vorbeigekommen wärt, Fremder. Sie haben schon so viele Kurenai auf der Suche nach einem verschollenen Relikt getötet.\n\nSie suchen das Totem von Kar'dash. Ich kann nicht verstehen, warum sie glauben, dass wir etwas über dieses Totem wüssten. Ist ein Totem nicht eine typisch orcische Gerätschaft?\n\nArechron muss davon erfahren. Vielleicht weiß er, warum die Finsterblut Kurenai verschleppen und foltern, um Informationen über ein orcisches Relikt zu erfahren.\n\nLasst uns gehen bevor noch mehr kommen.", sourceObjective = "Begleitet den gefangenen Kurenai aus dem Sonnenwindposten. Sprecht mit Arechron in Telaar, wenn Ihr erfolgreich wart.", completion = "Ja, ich weiß von dem Totem... aber es gehört noch viel mehr zu dieser Geschichte. Ich darf Euch jedoch nichts darüber erzählen. Nur Auserwählte haben Zugang zu solchem Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9880] = { id = 9880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap" }
quests[9881] = { id = 9881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap" }
quests[9882] = { id = 9882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Nexusprinz Haramad hat uns verboten mit der Arbeit im Oshu'gun loszulegen, weil er einen bestimmten mächtigen Naaru nicht verärgern will. Das hält natürlich unsere ganze Operation auf.\n\nIch glaube aber, dass ich ein Hintertürchen gefunden habe.\n\nSeht Ihr, wir sind nicht die einzigen Astralen, die von diesem riesigen Diamanten angelockt werden. Ein Dieb namens Gava'xi hat eine Gruppe von Schurken in den Oshu'gun geführt, und sie haben begonnen, große Teile aus dem Kristall herauszuschlagen.\n\nEure Aufgabe, {race}, ist es, dorthin zu gehen und unsere rechtmäßiges Eigentum zurückzufordern.", sourceObjective = "Besorgt 10 Kristallfragmente von Oshu'gun und bringt sie zu Gezhe am Aerissteg in Nagrand.", progress = "Habt Ihr die Kristallfragmente bekommen, {name}?", completion = "Ich bin beeindruckt. Die meisten sind in ausgezeichnetem Zustand.\n\nIch werde bei unserem Volk ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9883] = { id = 9883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Kristallfragmente", progress = "Ihr habt noch mehr Kristallfragmente? Nehmt aber bitte keine, die noch mit dem Berg verbunden sind. Wir wollen keinen Ärger mit den Naaru.", completion = "Bringt mir ruhig weiter Kristalle, {name}. Wir können nicht zulassen, dass diese Diebe unser Eigentum stehlen.\n\nAuch wenn es eigentlich noch gar nicht unseres ist. Theoretisch natürlich." }
quests[9884] = { id = 9884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedervorteil", sourceObjective = "Das Konsortium ist dafür bekannt, dass es sich gut um seine Freunde kümmert. Zu Beginn jeden Monats werde ich Euch ein paar Edelsteine als Bezahlung für Eure Dienste geben.\n\nDie Qualität der Steine hängt davon ab, wie treu ergeben Ihr uns wart. Lasst uns also hoffen, dass Ihr das Richtige tut und bei uns bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9885] = { id = 9885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedervorteil", sourceObjective = "Schön, Euch wiederzusehen, {name}. Ich habe Eure Edelsteine für diesen Monat fertig.\n\nIch habe Euch ein paar mehr dazugetan, damit Ihr wisst wie froh wir sind, Euch bei uns zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9886] = { id = 9886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedervorteil", sourceObjective = "Das Konsortium ist dafür bekannt, dass es sich gut um seine Freunde kümmert. Zu Beginn jeden Monats werde ich Euch ein paar Edelsteine als Bezahlung für Eure Dienste geben.\n\nDie Qualität der Steine hängt davon ab, wie treu ergeben Ihr uns wart. Lasst uns also hoffen, dass Ihr das Richtige tut und bei uns bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9887] = { id = 9887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedervorteil", sourceObjective = "Ah, {name}! Was macht so ein wichtiger Bursche wie Ihr an so einen dreckigen Ort wie diesem?\n\nNatürlich habe ich Eure Edelsteine. Nur das Beste für unseren Lieblingsuntoter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9888] = { id = 9888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unfähige Anführer", description = "Ich bin dem sicheren Tode entronnen, habe einen feigen Angriff bei Nacht von den Felsfäusten auf mein Dorf überlebt.\n\nAber ich frage Euch, Fremder, wozu?\n\n<Jorin zeigt auf Garrosh.>\n\nEr hat uns jegliche Unterstützung verweigert. Oger toben durch meine Stadt und er sitzt nur da und heult den Mond an. Was ist aus uns geworden? Was wird aus uns werden?\n\nIch habe einen Späher, Kilrath, zum Dorf, den jetzigen Ruinen des Blutenden Auges, geschickt. Könnt Ihr ihn bitte suchen und unterstützen? Er versteckt sich an der Grenze zwischen Nagrand und Terokkar.", sourceObjective = "Jorin Totauge möchte, dass Ihr Kilrath sucht und mit ihm sprecht.", completion = "<Kilrath flüstert.>\n\nDiese Oger sind extrem sonderbar. Und auch extrem dumm. Schaut nur, wie der fette den, äh, weniger fetten zum Tanzen zwingt. Es ist faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[9889] = { id = 9889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht den Fetten töten!", description = "Ich beobachte diese Kreaturen nun schon seit Tagen. Der Fette sagt, dass er auf etwas wartet. Worauf bleibt jedoch ein Geheimnis.\n\nIch habe einen Plan, aber er erfordert ein wenig Brutalität von Eurer Seite. Ihr werdet einige seiner Untertanen töten müssen und ihn dann fast tot schlagen. Wenn Ihr das tut, bin ich sicher, dass er uns alles erzählen wird, was wir wissen wollen.", sourceObjective = "Kilrath in den Wäldern von Terokkar möchte, dass Ihr 10 Eindringlinge der Felsfäuste tötet und Unkor den Rücksichtslosen so lange schlagt, bis er redet.", progress = "Ich gebe auf! Ich gebe auf!", completion = "Lasst mich leben und ich sage Euch alles, was Ihr wissen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9890] = { id = 9890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolg!", description = "Seit vielen Jahren hatten die Felsfäuste die Herrschaft über alle Oger der Scherbenwelt. Die Oger waren unter Krol vereint und zufrieden mit den Ländereien, die sie erhalten hatten. In den letzten Monaten haben wir jedoch viele Oger an einen Klan namens Totschläger verloren. Die Totschläger haben den größten Teil unseres Landes in Nagrand in Beschlag genommen und viele unserer Leute getötet.\n\nWir hatten keine andere Wahl als dieses Dorf einzunehmen. Wir werden ausgerottet...\n\nKrol ist verschollen und die Felsfäuste sind in Aufruhr. Lantresor von der Klinge hat in seiner Abwesenheit die Führung übernommen.", sourceObjective = "Teilt Kilrath in den Wäldern von Terokkar die Informationen, die Ihr aus dem Oger geprügelt habt, mit.", completion = "Ganz ruhig, {name}. Ich bin nur ein kleiner Schurke. Ich habe keine Ahnung, was ich mit solch einer Information anfangen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9891] = { id = 9891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weil Kilrath ein Feigling ist", description = "Erzählt Jorin in Garadar, was Ihr gehört habt. Ich bin mir sicher, dass er nicht erfreut sein wird zu hören, dass unser Dorf zerstört und viele unserer Leute getötet wurden, weil die Oger mehr Platz brauchen.\n\nMögen die Ahnen über Euch wachen... Ich werde mich in den Büschen verstecken, falls Ihr mich noch braucht.", sourceObjective = "Erzählt Jorin Totauge in Garadar in Nagrand, was Ihr aus Unkor herausprügeln konntet.", completion = "Sie denken also, dass sie uns Orcs nach Lust und Laune vertreiben und abschlachten können, was? Ich bin mir sicher, dass das nichts damit zu tun hat, dass unser Anführer ein unfähiger Jammerlappen ist... Wenn er doch nur einen Bruchteil der Leidenschaft seines Vaters geerbt hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[9892] = { id = 9892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Obsidiankriegsperlen", progress = "Habt Ihr noch mehr Kriegsperlen? Ihr findet genügend Oger weit im Norden, an der Grenze zu den Zangarmarschen.", completion = "Wir werden gut an diesen Perlen verdienen, {name}. Ich werde Khoraazi ganz sicher von Eurer Arbeit hier erzählen." }
quests[9893] = { id = 9893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidiankriegsperlen", description = "Während wir hier darauf warten, dass wir endlich am Oshu'gun graben können, verlieren wir so viel Gewinn, {name}.\n\nZum Glück habe ich eine andere Einkommensquelle entdeckt. Die Oger von Nagrand tragen Kriegsperlen aus Obsidian, ein Gestein, das in vielen anderen Welten sehr wertvoll ist.\n\nZerid musste sich aus Sicherheitsgründen bereits mit diesen Rohlingen auseinandersetzen. Betrachtet die Kriegsperlen also als kleinen Bonus. Oder noch besser, betrachtet sie gar nicht und bringt sie mir einfach.", sourceObjective = "Bringt 10 Obsidiankriegsperlen zu Gezhe beim Aerissteg in Nagrand.", progress = "Wie führen die Oger sich auf, {name}? Harte Nuss, was?", completion = "Ausgezeichnet. Das wird uns über Wasser halten bis die Sha'tar fertig sind mit was immer sie auch im Oshu'gun tun mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9894] = { id = 9894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützt die Behüter", description = "Während Eurer Reisen habt Ihr vielleicht ein paar der Behüter der Expedition getroffen. Sie kümmern sich hauptsächlich um die Feldstudien, das heißt die Dokumentation der einzigartigen Bewohner der Marschen, das Sammeln von Proben und die Kontaktaufnahme mit den vernunftbegabten Arten.\n\nDie Sicherheit der Behüter ist von äußerster Wichtigkeit, {class}. Wir mussten die Behüter, die sich aufgemacht haben, um die Funggorhöhle zu erkunden, wegen Angriffen von Sumpfmonstern zurückrufen. Aufseher Hamuht ist der Meinung, dass wir ihren Angriffen ein schnelles Ende machen könnten, wenn wir ihren Anführer, Lord Klaq, töten.", sourceObjective = "Tötet Lord Klaq und kehrt danach zu Windruferin Schwarzhuf in der Zuflucht des Cenarius zurück.", completion = "Ihr habt meinen Dank, {name}, und den der Behüter. Sie werden sich freuen zu hören, dass sie ihre Arbeit im Süden nun ohne Angst vor weiteren Angriffen fortsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9895] = { id = 9895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Gleichgewicht geraten", description = "Habt Ihr die Umgebung genau betrachtet, {name}? Dies ist eine dahinsiechende Landschaft, die verzweifelt versucht ihr Gleichgewicht zu halten und den Kampf verliert.\n\nWenn man weiß, worauf man achten muss, kann man die Symptome deutlich erkennen. Einige Vertreter bestimmter Gattungen überholen ihre Artgenossen, was das Wachstum angeht, bereits und werden aggressiv.\n\nEin gutes Beispiel für so ein unkontrolliertes Wachstum ist der Marschenläufer Sumpfschläger. Wenn ihr ihn selbst sehen wollt, müsst Ihr nur zu den Wasserwegen südlich der Zuflucht gehen.\n\nAber haltet Euch bereit, Euch zu verteidigen. Diese Kreatur kennt kein Erbarmen.", sourceObjective = "Sucht und vernichtet Sumpfschläger und kehrt dann zu Lethyn Mondfeuer in der Zuflucht des Cenarius zurück.", completion = "Jetzt, da Ihr die Anzeichen der Unausgeglichenheit mit eigenen Augen gesehen habt, achtet bei Euren weiteren Reisen darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9896] = { id = 9896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzsichels Fluch", description = "Bei Khaz'goroths brennendem Nabel, ist das heiß hier! Ich kann es der ersten Gruppe nicht verübeln, dass sie abgereist sind, aber wisst Ihr, es war nicht die Hitze, die sie verjagt hat. Nein, es war Schwarzsichel, auch wenn sie das natürlich nicht zugeben möchten.\n\nSie hatten ihr Lager südlich von den leuchtenden Draeneitürmen im Westen aufgeschlagen, gleich nördlich von Wildfenn, als die riesige Wespe aus dem Nichts auftauchte und sie angriff! Ich kann es kaum erwarten, ihre Gesichter zu sehen, wenn ich den Stachel des Biests nach Eisenschmiede bringe!", sourceObjective = "Bringt Schwarzsichels Stachel zu Ausgrabungsleiter Conall in Telredor.", progress = "Habt Ihr den Stachel bekommen können? Denkt daran, wenn er beschädigt ist, ist er wertlos für mich!", completion = "Ich kann Euch gar nicht genug danken, Kumpel. Ich werde es genießen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9897] = { id = 9897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin gerettet!", description = "Es macht mir nichts aus zu teilen. Ich bin nur froh, dass ich vor diesem Widerling Diebus sicher bin! Und ich habe Tonnen von Tierhäuten in den Zangarmarschen gesammelt, es ist also überhaupt kein Problem!", sourceObjective = "Gebt Harold Fährten bei Nesingwarys Safari in Nagrand das Bündel mit Tierhäuten.", progress = "Es ist sehr...<hust>...nett von Kristen, dass sie ihre Tierhäute teilt, meint Ihr nicht?", completion = "Nun, ich konnte nicht wissen, ob Ihr Kristen helfen konntet oder nicht. Aber wenn sie Euch eines ihrer Bündel mit Tierhäuten gegeben hat, müsst Ihr wohl in Ordnung sein.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9898] = { id = 9898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt erlangen", description = "Magasha ist die wildeste Trollfrau im Sumpf, aber sie respektiert nur mächtige Jäger.\n\nIch hab schon versucht, mich ihr zu beweisen, aber die einzige Bestie, mit der mir das gelingen könnte, ist mindestens eine Nummer zu groß für mich. Wärt Ihr vielleicht so nett, mir zu helfen? Es gibt da eine riesige Sumpfwespe namens Schwarzsichel, die sich in der Gegend südlich der leuchtenden Draeneitürme im Westen herumtreibt. Wenn Ihr mir ihren Stachel bringen könnt, gibt Magasha mir vielleicht eine Chance, mich ihren Jägern anzuschließen.\n\nIch weiß, das ist nicht ganz ehrlich, aber ich verspreche Euch, dass ich von ihr lernen und Euch beide stolz machen werde.", sourceObjective = "Bringt Schwarzsichels Stachel zu Reavij im Sumpfrattenposten.", progress = "Ich werde Glück haben - ich fühle es.", completion = "Fantastisch! Ich werde Euch nie vergessen, dass ihr mir geholfen habt, ihr Herz zu gewinnen. Ihr sollt der Ehrengast auf unserer Hochzeit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9899] = { id = 9899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerledigte Arbeit", description = "Jemand muss Reavij zur Vernunft bringen! Er vernachlässigt seine Pflichten und verschwendet stattdessen all seine Energie darauf, meine Aufmerksamkeit zu erlangen. Ich habe versucht, ihn zu ignorieren und ihm gesagt, dass er damit aufhören soll. Aber nichts scheint zu helfen.\n\nBis er es endlich sein lässt, muss ich ständig hinter ihm aufräumen. Er hätte sich eigentlich um Sporenschwinge kümmern sollen, aber das Monster ist immer noch wohlauf. Wenn Ihr Zeit habt, könntet Ihr vielleicht in den westlichen Teil des Todesmoors gehen und den Segler töten? Ich kümmere mich in der Zwischenzeit um Reavij.", sourceObjective = "Magasha im Sumpfrattenposten möchte, dass Ihr Sporenschwinge tötet.", progress = "Ich kann ihn einfach nicht davon abbringen. Ich fürchte, ich muss Schattenjäger Denjai bitten, ihn zurück nach Zabra'jin zu schicken.", completion = "Wenigstens einer hier erfüllt seine Pflicht. Vielen Dank, dass Ihr Euch um diese Angelegenheit gekümmert habt, {name}. Ich muss einmal mit Zurai über Reavij sprechen. Seine Tagträumereien müssen langsam ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9900] = { id = 9900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gava'xi", description = "Die Anwesenheit von astralen Schurken in dieser Gegend mag Gezhe, der in allem eine Möglichkeit sieht, vielleicht erheitern, aber sie sind eine wirkliche Bedrohung für die Sicherheit unserer Unternehmung.\n\nIhr Anführer, Gava'xi, ist ein gefährlicher Krimineller, und ich habe es zu meinem höchsten Anliegen gemacht, ihn zur Strecke zu bringen.\n\nWenn Ihr Euch nützlich machen wollt, dann zieht los und kümmert euch um Gava'xi. Ich werde mich darum kümmern, dass Ihr angemessen entlohnt werdet.", sourceObjective = "Tötet Gava'xi in der Nähe des Oshu'gun und kehrt dann zu Zerid beim Aerissteg in Nagrand zurück.", progress = "Ihr seid zurück, {race}. Ist Gava'xi tot?", completion = "Dank Euch müssen wir uns nun nicht mehr vor Gava'xi fürchten. Wollen wir uns nun um eure Belohnung kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9901] = { id = 9901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Die erste Expedition, die die Liga losgeschickt hatte, berichtete von einem riesigen Sporensegler namens Sporenschwinge. Sie mussten sehr hastig aufbrechen, deshalb hatten sie keine Gelegenheit, das Tier umzubringen. Deshalb dachte ich mir, ich erledige das für sie.\n\nIn ihrem Bericht stand, dass die Kreatur sich im westlichen Teil des Todesmoors aufhält. Ich glaube Verteidiger Idaar erwähnte einmal, dass es sich nordöstlich von Telredor befindet.", sourceObjective = "Ausgrabungsleiter Conall in Telredor möchte, dass Ihr Sporenschwinge tötet.", completion = "Gut gemacht, {name}. Ich glaube, wir beide lassen ein ganzes Team von Ausgrabungsleitern neben uns blass aussehen. Wenn ich zurück in Eisenschmiede bin, werde ich mir meine Einsatzorte sicher selbst aussuchen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9902] = { id = 9902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrecken des Sumpflichtsees", description = "Meine Reisen durch das Gebiet der Naga haben mir einen Eindruck vermittelt, wie schlimm es meinen unglücklichen Brüdern und Schwestern gehen muss. Am Sumpflichtsee im Südwesten habe ich beobachtet, welch tödliches Spiel einer der besonders bösartigen Zuchtmeister treibt. Er jagt seine Sklaven ins Wasser, wenn er weiß, dass Terrorklaue, ein riesiger Sumpfstrok, Hunger hat.\n\nDie Folgen brauche ich nicht weiter erläutern. Wir sind zu wenige, um die Naga direkt anzugreifen, aber wir können ihnen den Spaß verderben, indem wir ihr Haustier umbringen.", sourceObjective = "Tötet Terrorklaue und kehrt dann zu Puluu in der Oreborzuflucht zurück.", completion = "Habt Dank, {name}. Vielleicht werden diese Marschen mit der Hilfe der Draenei eines Tages frei von Naga sein. Ich kann mir gar nicht vorstellen, wie schlimm es sein muss, ihnen dienen zu müssen.\n\nEr spricht nicht oft darüber, aber Maktu war einst ihr Sklave.", sourceObjectiveStatus = "unverified-source-field" }
quests[9903] = { id = 9903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Größte von allen", description = "Ihr seid zwar mit den meisten der kleineren Hydras fertiggeworden, aber ich glaube kaum, dass Mragesh von Eurer Vorstellung beeindruckt war. Er ist eine gerissene, grausame Bestie und hat schon so manchen Angler auf dem Gewissen.\n\nIch habe mir vorgenommen, die Letzte zu sein, die er je belästigt. Er soll sich tief im Schlangensee im Nordosten verstecken. Er ist schon Geschichte, aber das weiß er noch nicht.", sourceObjective = "Tötet Mragesh und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Ich bin mir sicher, der alte Knabe hat das Ende seiner Tage schon vorausgesehen. Bei all diesen Neuankömmlingen musste die alte Rangfolge sich einfach ändern. Es ist nur recht, dass sein Geist nun zu Ruhe kommen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9904] = { id = 9904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Terrorklaue", description = "Ich habe jeden erdenklichen Fisch in den Marschen gefangen, aber einer ist mir bisher entkommen. Sicher habe ich auch Aale und Morastflossenfrenzys gefangen. Aber als ich das letzte Mal am Sumpflichtsee war, hat einer angebissen, meine Schnur zerrissen und ist abgehauen.\n\nTerrorklaue wird er genannt, und ich werde nicht ruhen, bis er tot ist. Er ist zu groß um ihn mit einer Angel zu fangen, also müssen wir ihn wohl auf die altmodische Art umbringen.", sourceObjective = "Tötet Terrorklaue und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Endlich! Wahrscheinlich hat jeder Angler eine Geschichte über \"den, der mir entkommen ist\". Aber ich habe noch keinen Fisch getroffen, den man nicht auf die ein oder andere Art bezwingen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9905] = { id = 9905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maktus Rache", description = "Als Maktu letztes Mal auf Hydrajagd am Schlangensee war, wurde er von größter Hydra, die er jemals gesehen hat, angegriffen. Maktu hat nach seinem Speer gegriffen, aber es war schon zu spät. Er konnte gerade noch entkommen, bevor er zu Hydrafutter wurde.\n\nWer weiß? Vielleicht hat Maktu nächstes Mal nicht mehr so viel Glück. Maktu will, dass es kein nächstes Mal gibt. Werdet Ihr Maktu helfen, sich an Mragesh zu rächen?", sourceObjective = "Sucht und tötet Mragesh und kehrt dann zu Maktu in der Oreborzuflucht zurück.", completion = "<Maktu nickt anerkennend.>\n\nMaktu ist dankbar für Eure Hilfe. Maktus Stolz ist befriedigt. Er wird nicht mehr so unvorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9906] = { id = 9906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sag's mit Fäusten", description = "Oger interessieren sich nur für das Eine: Macht. Wenn wir ihnen gegenüber Schwäche zeigen, werden sie sich das zum Vorteil machen und uns ausrotten.\n\nGarrosh ist vielleicht bereit dazu, die Hände in den Schoß zu legen und diese Hunde unser Land übernehmen zu lassen, aber ich bin es nicht! Ich möchte, dass Ihr den Totschlägern eine Nachricht zukommen lasst, die sie verstehen: Gewalt.\n\nReist zu den Ruinen der Brennenden Klinge südöstlich von hier und zeigt ihnen die Macht der Mag'har.\n\nUnd {name}, schaut bei den anderen vorbei, bevor Ihr geht.", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", completion = "Unser Auftrag ist noch nicht zu Ende. Es gibt noch andere, die einer Lektion bedürfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9907] = { id = 9907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kühner Angriff", description = "Direkt im Westen von hier findet Ihr das Halaanibecken. Im Becken befinden sich die Zwillingsschluchten von Nagrand: Nordwind und Südwind. Die Schocktruppen der Felsfäuste benutzen die Schluchten, um ihre Ogerhorte zu verstecken.\n\nIch möchte, dass Ihr diese Truppen aufspürt und sie alle im Namen der Mag'har tötet.", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", completion = "Wenn dies das Blut in ihren Adern nicht zum Gefrieren bringt, dann wird es nichts schaffen. Ihr habt den Mag'har zu Gerechtigkeit verholfen, {name}. Und für Gerechtigkeit zahlen die Mag'har gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[9910] = { id = 9910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standarten", description = "Wenn Ihr in die Ruinen der Brennenden Klinge reist, habe ich eine Aufgabe für Euch. Stellt diese Schlachtstandarten der Mag'har an drei verschiedenen Orten in der Ogersiedlung auf. Vorzugsweise Orte, an denen man sie gut sehen kann. Haltet nach den großen lodernden Scheiterhaufen in den oberen Bereichen Ausschau. Stellt eine Standarte neben dem ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge auf.\n\nDie Standarten werden einen bleibenden Eindruck bei den Ogern hinterlassen, die die Schlacht verpasst haben.", sourceObjective = "Mystiker Elkay'gan in Garadar in Nagrand möchte, dass Ihr eine Schlachtstandarte der Mag'har am ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge aufstellt. Bringt die übrigen Schlachtstandarten zurück, wenn Ihr fertig seid.", progress = "Ehrfurcht aus Angst! Das ist so gut wie jeder andere Grund.", completion = "Vielleicht wollt Ihr noch eine andere Aufgabe? Eine etwas heiklere?", sourceObjectiveStatus = "unverified-source-field" }
quests[9911] = { id = 9911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Graf der Marschen", description = "Dieses blutige Beißwerkzeug stammt von einem unglaublich großen Insekt. Der Netherrochen, zu dem es gehörte, war der größte, der je in den Zangarmarschen gesichtet wurde. Wenn man den Zustand der Beißwerkzeuge betrachtet, muss der Graf seine Nahrung von Aas auf frisches Fleisch umgestellt haben.\n\nDie Expedition des Cenarius wäre an einem solchen Objekt sicher sehr interessiert. Behüterin Leesa'oh hat ein kleines Lager im Westen des Quaggkamms.", sourceObjective = "Bringt \"Graf\" Ungulas Beißwerkzeug zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", progress = "<Die Behüterin blinzelt ein paar Mal überrascht.>\n\nWoher habt Ihr dieses... Ding?", completion = "Seid Ihr sicher, dass es echt ist? Ich meine, ich wusste schon, dass es riesige Kreaturen in den Marschen gibt, aber es gibt einen Unterschied zwischen riesigen Kreaturen und RIESIGEN Kreaturen.\n\nDa fällt mir ein, dass die Sporlinge einmal etwas von einem furchterregenden Netherrochen erzählt haben, der sie vor den Angriffen der Sumpflords bedroht hatte.\n\nWas ist, wenn diese Geschichten wahr sind? Oh je. Ich hebe das hier mal lieber auf. Die Expedition wird sicher davon erfahren wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9912] = { id = 9912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Expedition des Cenarius", description = "Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.\n\nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.", sourceObjective = "Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Willkommen in der Zuflucht des Cenarius, {name}. Ich hoffe, Ihr könnt uns bei unserer Aufgabe behilflich sein. Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[9913] = { id = 9913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konsortium braucht Euch!", description = "Meine Organisation, das Konsortium, sucht nach talentierten Personen, wie Ihr es seid. Ihr werdet kaum ehrlichere und härter arbeitende Astrale als uns in dieser Gegend hier finden.\n\nAlles, was wir Verlangen ist Loyalität, Einsatz und ein vernünftiges Maß an moralischer Flexibilität. Wenn Ihr Interesse habt, sprecht mit Gezhe, unserem Anführer hier. Ihr findet ihn beim Aerissteg, nördlich des Oshu'guns.", sourceObjective = "Meldet Euch bei Gezhe beim Aerissteg in Nagrand.", completion = "Seid Ihr bereit für ein wenig Arbeit, {race}? Ich habe die perfekte Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9914] = { id = 9914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganzer Kopf voll Elfenbein", description = "Elfenbein ist ein heißbegehrtes Material. Ich habe Kunden von weither, die Schlange stehen, um es zu kaufen. Ich würde mich überreden lassen, meinen Gewinn mit Euch zu teilen.\n\nDie Stoßzähne der wilden Elekk in Nagrand haben genau die Qualität, die ich brauche. Bleibt jedoch von den Bullen fern, ihre Stoßzähne sind zu minderwertig.\n\nOh, und keine Sorge, das ist keine Wilderei, ich habe ein Abkommen mit den Orcs und den Draenei.\n\nAlso, sind wir uns einig?", sourceObjective = "Sammelt 3 Paar Elfenbeinstoßzähne und kehrt dann zu Shadrek beim Aerissteg in Nagrand zurück.", progress = "Ich brauche Elfenbein, keine Entschuldigungen. Wir können natürlich Euren Anteil am Gewinn neu verhandeln. Ich glaube aber kaum, dass Ihr mit dem Ergebnis zufrieden sein werdet.", completion = "Ich habe keine Sekunde an Euch gezweifelt, mein Freund. Die meisten hiervon sehen gut aus. Ein bisschen dreckig und verkratzt vielleicht. Aber ich denke, sie sind den Preis, den wir vereinbart hatten, wert.\n\nIch hoffe, das wir auch in Zukunft ins Geschäft kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9915] = { id = 9915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Elfenbein", progress = "Ich habe immer noch Bedarf an Elfenbeinstoßzähnen von den wilden Elekk in Nagrand. Unglücklicherweise kann ich es mir nicht mehr leisten, Euch dafür zu bezahlen. Wenn Ihr mir aber trotzdem weiter Stoßzähne bringt, werdet Ihr Euch beim Konsortium sehr beliebt machen.", completion = "Ausgezeichnet, noch mehr hochwertige Stoßzähne. Auch wenn ein paar davon etwas schäbig aussehen.\n\nIhr habt den Dank des Konsortiums, {name}." }
quests[9916] = { id = 9916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratskisten des Blutenden Auges", description = "Die Totschläger haben die Vorräte, die sie aus unserem Dorf gestohlen haben, zu den Zwillingsschluchten von Nagrand gebracht, die sich westlich von hier im Halaanibecken befinden.\n\nWenn ihr Euch dort aufhalten solltet, haltet Ausschau nach den Vorratskisten. Wenn wir sie zurückbekommen könnten, würde das die Last, die die Matronen von Garadar zu tragen haben, erheblich mindern.", sourceObjective = "Mystiker Elkay'gan in Garadar in Nagrand möchte, dass Ihr 10 Vorratskisten des Blutenden Auges wiederbesorgt.", progress = "Vielleicht können unserer Kinder eines Tages ohne Hunger leben.", completion = "Die meisten unserer Besitztümer wurden bei Angriffen zerstört oder gestohlen. Ich kann euch nicht viel bieten, aber hier sind ein paar Dinge, die Ihr vielleicht als nützlich empfinden könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9917] = { id = 9917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich meinen Augen trauen?", description = "Kann ich meinen Augen trauen? Ist das da drüben tatsächlich eine Jagdgesellschaft von Ogern? Was treiben Oger denn so weit von Ihrem Hügel entfernt? Mir gefällt das gar nicht, <Fremder/Fremde>. Zuerst die Finsterblut und jetzt die Oger. Wir haben einfach nicht genug Leute, um mit all diesen Gefahren fertigzuwerden.\n\nKönntet Ihr die Ogersiedlung im Osten untersuchen? Ihr Lager ist etwa 200 Schritte östlich von hier. Wenn Ihr die Jäger der Felsfäuste seht, seid Ihr richtig. Tötet sie um an ihre Pläne zu kommen!", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr die Pläne der Felsfäuste besorgt.", progress = "Habt Ihr Neuigkeiten erfahren?", completion = "<Bintook liest die Pläne.>\n\nBEIM LICHT! Diese Handschrift ist grauenvoll! So wie ich das sehe, planen sie \"die blauen Häute zu essen und in ihr Dorf zu bringen\" oder einen Blaubeerkuchen zu backen. Es könnte wirklich beides heißen. Wir müssen der Sache auf den Grund gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9918] = { id = 9918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht solange ich hier wache!", description = "Die Schlachtpläne wurden von einem Leutnant der Oger geschrieben. Sein Name ist entweder Trocken oder Brocken.\n\n<Bintook dreht das Pergament und legt den Kopf schief.>\n\nEs könnte auch Billy sein.\n\nWie auch immer, ich denke, Ihr solltet dorthin zurückgehen und ein paar Takte mit Billy oder Trocken oder Brocken oder was weiß ich reden! Versucht diplomatisch zu sein. Wenn das nichts nützt, dann setzt eben etwas Muskelkraft ein.", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Brocken sprecht. Kehrt zu Jägerin Bintook zurück, wenn Ihr die geforderten Informationen gesammelt habt.", completion = "Oh je, das war nur eine kleine Jagdgesellschaft? Ihr müsst Mo'mor erzählen, was Ihr herausgefunden habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9919] = { id = 9919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporeggar", description = "Ihr seid <ein sehr netter/eine sehr nette:r> {race}, {name}. Nicht wie die anderen, die ich getroffen habe.\n\nIhr solltet den Rest meines Volkes kennenlernen, sie wären Euch für Eure Hilfe sehr dankbar. Bringt diese Sporenbeutel zu meinem Anführer, Msshi'fn. Ihr findet ihn in Sporeggar, nördlich von hier.", sourceObjective = "Geht nach Sporeggar, nördlich vom Pilzgeflecht in den Zangarmarschen, und bringt die geborgenen Sporensäcke zu Msshi'fn.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, {name}?", completion = "Ihr habt uns geholfen, die nächste Generation Sporlinge zu sichern, {race}. Das können wir Euch nur mit einem Willkommen in unserer Stadt vergelten. Bleibt doch ein wenig und lernt die anderen Sporlinge kennen. Sie werden viele Fragen an Euch haben, ich hoffe, das macht Euch nichts aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9920] = { id = 9920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'mor der Brecher", description = "Ihr müsst sofort zu Mo'mor! Ihr könnt ihn in der Mitte von Telaar finden, beim Springbrunnen. Erzählt ihm genau, was der Oger Euch gesagt hat!", sourceObjective = "Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Mo'mor dem Brecher redet.", completion = "<Mo'mor schaut verdutzt drein.>\n\nEin neuer Ogerstamm drängt die Felsfäuste immer weiter nach Süden? Das klingt beunruhigend. Wir müssen mit der Situation in der Nähe unseres Zuhauses fertig werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[9921] = { id = 9921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen der Brennenden Klinge", description = "Die Jagdgesellschaften der Oger sind Vorboten für einen Angriff. Wir müssen sie schlagen, bevor sie eine Chance haben, genug Leute zu sammeln, um unsere Stadt einzunehmen.\n\nIhr werdet Euch wohl Eure Hände schmutzig machen müssen, {race}.\n\nDie größte Ansammlung von Felsfäusten in dieser Gegend befindet sich in den Ruinen der Brennenden Klinge, direkt im Osten von Telaar, an der Grenze zu Terokkar. Geht dort hin und zeigt den Felsfäusten, dass Telaar sich niemals ihrem Willen beugen wird!", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 8 Zermalmer der Felsfäuste und 8 Mystiker der Felsfäuste tötet.", progress = "Wir haben Telaar erst vor kurzem wiedergewonnen. Wir werden es nicht aufgeben!", completion = "Ausgezeichnet. Konntet Ihr diesen Lantresor, der in dem Brief dieses Dummkopfs erwähnt wurde, ausfindig machen?\n\nEgal, wir müssen weitermachen. Ich habe Berichte über weitere Ogeraktivitäten erhalten, um die sich sofort jemand kümmern muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[9922] = { id = 9922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwillingsschluchten von Nagrand", description = "Ihr habt eine gute Arbeit geleistet, {name}. Seid Ihr bereit für noch mehr davon?\n\nIch habe Berichte über eine große Ansammlung von Felsfäusten in den zwei Schluchten von Nagrand, nordwestlich von hier im Halaanibecken.\n\nBegebt Euch zu den Schluchten und werdet mit den übrig gebliebenen Felsfäusten fertig.", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr 10 Krieger der Felsfäuste und 10 Magier der Felsfäuste tötet.", completion = "Ausgezeichnete Arbeit! Ich stelle im Augenblick Nachforschungen über den Totschlägerstamm an, den der Leutnant der Felsfäuste erwähnt hat. Jetzt müssen die Aufgaben, die Ihr erledigt habt, getestet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9923] = { id = 9923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HILFE!", description = "HILFE! Sie werden mich fressen! Ich weiß es!\n\nFindet den Schlüssel, einer dieser Oger muss ihn haben.\n\nWenn Ihr mir hier raushelft, wird mein Vater Euch fürstlich entlohnen! Er ist der Anführer von Telaar, Arechron.", sourceObjective = "Findet den Schlüssel der Felsfäuste und befreit Corki. Sprecht mit Arechron in Telaar, wenn Ihr Erfolg hattet.", completion = "Es tut mir wirklich sehr leid, {race}. Er gerät immer in Schwierigkeiten. Manchmal wünschte ich, ich könnte Ihn anleinen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9924] = { id = 9924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corki wird schon wieder vermisst!", description = "<Arechron seufzt.>\n\nDas ist mir so peinlich. Erinnert Ihr Euch noch an meinen Sohn Corki? Ihr habt ihn vor Kurzem aus den Ruinen der Brennenden Klinge gerettet. Nun ja, seine Neugier hat ihn mal wieder gepackt. Er sagte, er wolle die Felsfaustbedrohung für Onkel Mo'mor untersuchen, und ist zu den Ogerhügeln im Halaanibecken gerannt, nördlich von hier.\n\nKönntet Ihr ihn vielleicht für mich ausfindig machen? Ich wäre Euch ewig dankbar.", sourceObjective = "Arechron in Telaar bittet Euch, Corki zu suchen und zu befreien.", progress = "Habt Ihr ihn gefunden?", completion = "Ich bin Euch so dankbar, {name}. Seine Mutter wird sich in Zukunft um ihn kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9925] = { id = 9925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Sicherheit", description = "Gezhe hat beschlossen, unsere Operation so nahe wie möglich am Oshu'gun zu postieren, ohne dabei einen Gedanken an die Sicherheit der Gruppe zu verschwenden. Warum? Weil er eine Erhöhung unserer Produktivität um zehn Prozent vorausgesehen hat, wenn er uns hier anstatt in den Bergen im Süden ansiedelt.\n\nUngeachtet der durchgedrehten Ausgeburten der Leere, die sich gerade mal 10 Fuß von uns weg aufhalten. Aber das ist das Problem des Sicherheitsoffiziers, nicht Gezhes.\n\nTötet ein paar dieser Ausgeburten für mich, und ich gebe Euch ein Zehntel meines Sicherheitsetats. Freut Euch nicht zu früh, viel Geld steht mir nicht zur Verfügung.", sourceObjective = "Zerid beim Aerissteg in Nagrand möchte, dass Ihr 8 Ausgeburten der Leere in der Nähe des Oshu'gun tötet.", completion = "Ihr zaubert ein Lächeln auf mein Gesicht, {name}. Zumindest würdet Ihr das, wenn ich noch ein Gesicht hätte.\n\nWenn Ihr so weiter macht werden wir noch beste Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9927] = { id = 9927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbarmungslose Gerissenheit", description = "<Lantresor reicht Euch einen Stapel Banner.>\n\nDies sind die Ogerbanner der Totschläger, die ich kürzlich erworben habe.\n\nIch möchte, dass Ihr zur Festung Kil'sorge reist und so viele wie möglich von diesem Abschaum von Kil'sorge tötet, wie Ihr nur könnt. Rammt ein Totschlägerbanner durch das Herz jedes gefallen Soldaten von Kil'sorge. Kehrt zu mir zurück wenn Ihr diese und die beiden anderen Aufgaben, die zu meinem Plan gehören, erledigt habt.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge möchte, dass Ihr 10 Ogerbanner der Totschläger in die Körper von Bewohnern von Kil'sorge in der Festung Kil'sorge rammt.\n\nBringt unbenutzte Ogerbanner der Totschläger zu ihm zurück.", progress = "<Lantresor schaut Euch entgeistert an.>\n\nSchon fertig?", completion = "Könnt Ihr Euch vorstellen, wie verwirrt sie darüber sein werden, {race}? Das wird wundervoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9928] = { id = 9928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen zur Täuschung", description = "Wenn mein Plan gelingen soll, müsst Ihr ein paar Waffen von Kil'sorge in der Festung Kil'sorge stehlen.\n\nDurchsucht die Festung nach Kisten mit Waffen von Kil'sorge. Bringt mir alle, die Ihr finden könnt.\n\nDie Festung Kil'sorge liegt im Süden, etwas westlich von den Ruinen der Brennenden Klinge.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge Nagrand möchte, dass Ihr 10 Waffen von Kil'sorge besorgt.", progress = "Wir werden einen nie dagewesenen Hass zwischen den beiden Klans säen!", completion = "Ausgezeichnet! Unser nächstes Ziel sind die Ruinen des Lachenden Schädels.", sourceObjectiveStatus = "unverified-source-field" }
quests[9931] = { id = 9931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich für den Gefallen revanchieren", description = "Nun müsst Ihr den Wunsch nach Krieg in den fetten, nutzlosen Köpfen der Totschläger wecken. Im Nordwesten, bei den Bergen, findet Ihr die Ruinen des Lachenden Schädels.\n\n<Lantresor zeigt auf die Kiste mit den Waffen, die Ihr ihm gebracht habt.>\n\nErkennt Ihr diese Banner? Es sind Banner von Kil'sorge. Ich möchte, dass Ihr einen Stapel Banner von Kil'sorge nehmt und sie in die Leichen der Totschlägeroger rammt. Denkt daran, Ihr findet sie im Nordwesten.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr 10 Banner von Kil'sorge in die Leichen der Totschlägeroger in den Ruinen des Lachenden Schädels rammt.\n\nBringt unbenutzte Banner von Kil'sorge zu ihm zurück.", progress = "Könnt Ihr vorhersehen, was als nächstes geschieht?", completion = "Der Plan ist perfekt, {name}. Ich sehe jetzt schon die Früchte unserer Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9932] = { id = 9932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweismaterial", description = "Euer Angriff auf die Festung Kil'sorge hat uns eine ganz besondere Möglichkeit eröffnet. Wir haben genügend Leichen, um es so aussehen zu lassen, als hätte eine große Schlacht stattgefunden.\n\nReist zu den Ruinen des Lachenden Schädels und sucht den Hof des Lachenden Schädels. Dort solltet Ihr einen brennenden Scheiterhaufen finden. Vergewissert Euch, dass die Gegend sicher ist, und benutzt diese Decke, um Rauchzeichen zu senden. Wenn meine Oger den Rauch sehen, werden sie sich einschleichen und die Leichen der toten Soldaten von Kil'sorge dort platzieren.\n\nDas sollte unser letzter Streich sein.", sourceObjective = "Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr die feuchte Wolldecke am lodernden Scheiterhaufen der Totschläger im Hof des Lachenden Schädels benutzt, um Signale an seine Oger zu senden.", progress = "Wisst Ihr nun, warum Ihr nie einen Krieg gegen mich gewinnen würdet?", completion = "Ich muss zugeben, dass ich mich seit Jahrzehnten nicht mehr so lebendig gefühlt habe. Ihr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9933] = { id = 9933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Telaar", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", sourceObjective = "Bringt das Friedensangebot der Brennenden Klinge zu Arechron nach Telaar in Nagrand.", progress = "Frieden sagt Ihr?", completion = "Bitte, {name}, nehmt Euch von diesem Friedensangebot was immer Ihr möchtet. Schließlich wäre dies ohne Eure Hilfe niemals möglich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9934] = { id = 9934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Garadar", description = "<Lantresor zeigt auf eine unbeschriftete Kiste.>\n\nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.\n\nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.\n\n<Lantresor verneigt sich.>", sourceObjective = "Bringt das Friedensangebot der Brennenden Klinge zu Garrosh in Garadar.", progress = "<Garrosh scheint von dem Angebot unbeeindruckt zu sein.>", completion = "<Garrosh tritt die Kiste um.>\n\nIhr verschwendet Eure Zeit, {race}. Nehmt Euch aus der Kiste was immer Ihr wollt. Weder ich noch Garadar haben für diesen unnützen Tand Verwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9935] = { id = 9935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Giselda die Alte", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Bullrok in Garadar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", sourceObjective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Bullrok in Garadar zurück.", completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, {name}. Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9936] = { id = 9936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Giselda die Alte", description = "Gesucht: Tot oder lebendig\n\nGiselda die Alte von Kil'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.\n\nAufenthaltsort in der Festung Kil'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.\n\nEine hohe Belohnung in Gold wird von Aufseher Moi'bff Jill in Telaar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.", sourceObjective = "Tötet Giselda die Alte und 10 beliebige Agenten von Kil'sorge. Kehrt danach zu Aufseher Moi'bff Jill in Telaar zurück.", completion = "Die Alte ist tot! Das sind wundervolle Nachrichten, {name}. Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9937] = { id = 9937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Durn der Nimmersatte", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, {name}. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", sourceObjective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Bullrok, wenn Ihr diese Aufgabe erledigt habt.", completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9938] = { id = 9938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Durn der Nimmersatte", description = "Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, {name}. Seid Ihr nun bereit für die Geißel der Geisterfelder?\n\nDurn der Nimmersatte regiert über das Gebiet beim Oshu'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.", sourceObjective = "Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr diese Aufgabe erledigt habt.", completion = "Durns tödlicher Griff wurde gelöst! Nagrand schaut Dank Euch auf eine bessere Zukunft, Held. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9939] = { id = 9939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zorbo der Berater", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Garadar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Orcs getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Bullrok in Garadar ausbezahlt.", sourceObjective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Bullrok, wenn Ihr die Aufgabe erledigt habt.", completion = "Dies ist ein großer Sieg für die Bewohner von Garadar! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9940] = { id = 9940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zorbo der Berater", description = "Gesucht: tot oder lebendig\n\nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Telaar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Zerschlagene getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.\n\nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.\n\nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Moi'bff Jill in Telaar ausbezahlt.", sourceObjective = "Tötet Zorbo den Berater, 5 Schamanen der Totschläger und 5 Häscher der Totschläger. Meldet Euch bei Aufseher Moi'bff Jill, wenn Ihr die Aufgabe erledigt habt.", completion = "Dies ist ein großer Sieg für die Bewohner von Telaar! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9944] = { id = 9944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene mag'harische Prozession", description = "Großmutter sagt, dass wir durchhalten und unserem Volk dienen müssen. Sie sagt, dass wir Garrosh als Beispiel dienen müssen, zeigen, dass das Leben weitergeht.\n\nIch muss mich um so viele Dinge hier kümmern, besonders seit Großmutter krank ist. Würdet Ihr den Mag'har eine Gefallen tun, indem Ihr einer ihrer Matronen helft?\n\nVor ein paar Tagen haben wir einen Begräbniszug zum Ahnengrund geschickt, der noch nicht zurückgekehrt ist. Würdet Ihr nach ihnen suchen? Sie haben die westliche Straße aus Garadar hinaus genommen. Folgt ihr und meidet Halaa.", sourceObjective = "Sucht nach der verschollenen mag'harischen Prozession.", completion = "Dreißig Orcs, {race}! Von diesen dreißig sind nur noch Ungriz und ich übrig. Wir haben den jungen Orc, Saurfang, halb tot in der Nähe von Sonnenwind gefunden. Offensichtlich ist er aus einem anderen Grund hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[9945] = { id = 9945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg den Totschlägern", description = "Wir waren auf dem Weg zum Ahnengrund, als wir in einen Hinterhalt der Totschläger geraten sind. Sie kamen von allen Seiten, haben viele der Wächter der Prozession getötet und auch viele andere. Sie haben sogar die Überreste des Ältesten im Wagen geschändet.\n\nUnd warum? Um uns zu erniedrigen und ihre Macht zu beweisen. Nicht einmal die Felsfäuste hätten sich zu so etwas herabgelassen.\n\nIch habe mich dem spirituellen Weg verschrieben, {name}, aber auch ich kenne Grenzen. Sucht die Angreifer im Totschlägerhügel im Nordwesten und vernichtet sie!", sourceObjective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 8 Schläger der Totschläger und 8 Hexenmeister der Totschläger tötet.", completion = "Das ist ein guter Anfang, aber ihr Anführer muss getötet werden, damit Eure Taten auch langfristige Erfolge erzielen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9946] = { id = 9946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war der Plünderer", description = "Habt Ihr je einen Ogerkönig gesehen, {race}? Nur wenige haben es überlebt und können davon erzählen. Unglücklicherweise haben wir es genau jetzt mit einem zu tun.\n\nDer Anführer dieser Barbaren ist ein Oger namens Cho'war. Gerüchten zufolge soll er die Gronn aus den Höhlen vertrieben haben. Danach hat sich Cho'war selbst zum König ernannt und die Ogerklans, die unter den Gronn gedient haben, aufgelöst. So entstanden die Totschläger.\n\nSucht tief in den Höhlen des Totschlägerhügels nach Cho'war. Tötet ihn und bringt mir seinen Kopf.", sourceObjective = "Ältester Yorley bei der mag'harischen Prozession in Nagrand möchte, dass Ihr Cho'war den Plünderer tötet und Cho'wars Kopf besorgt.", progress = "Er ist sicher sehr schwer bewacht.", completion = "Diesen Kopf stellen wir an dem Toren von Garadar auf, damit alle ihn sehen können. Die Oger werden es sich zweimal überlegen, bevor sie heilige Rituale der Mag'har stören.", sourceObjectiveStatus = "unverified-source-field" }
quests[9948] = { id = 9948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Überlebenden", description = "Wenn ich etwas über Oger weiß, dann dass sie Ihr Essen frisch mögen. Das bedeutet, dass die Mag'har, die sie gefangen haben, wahrscheinlich am Leben gehalten werden, bis sie verspeist werden sollen. Ich weiß, das ist ein grausamer Gedanke, aber wir müssen das zu unserem Vorteil ausnutzen.\n\nGeht zum Totschlägerhügel und sucht nach gefangenen Mag'har. Wenn Ihr Gefangene gefunden habt, holt Euch die Schlüssel von den Totschlägern in der Nähe.\n\nTötet die Oger, um an die Schlüssel zu gelangen, und befreit die Gefangenen.", sourceObjective = "Ältester Ungriz bei der mag'harischen Prozession in Nagrand möchte, dass Ihr 5 gefangene Mag'har befreit.", completion = "Ihr habt geschafft, was keiner für möglich hielt und unsere vermissten Brüder und Schwestern zurückgebracht. Für die Mag'har seid Ihr ein Held, {name}. Alle werden Euren Namen kennen und wissen, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9951] = { id = 9951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es beobachtet Euch!", description = "Schnell, versteckt Euch! Naphthal'ars Auge beobachtet Euch... uns alle!\n\nIch traue mich nicht, auf die Spitze des Turms zu gehen, um mit ihm zu sprechen, aber Ihr... Ihr seht aus, als könntet Ihr die richtigen Worte finden. Aber seid vorsichtig, es mag keine Witze und kann Dummköpfe nicht leiden.\n\nÜberredet es, auf eine Tasse Tee hinunterzukommen. Aber bitte sorgt dafür, dass es mich nicht mehr anstarrt!", sourceObjective = "Tötet Naphthal'ar und kehrt dann zu Aufseher Baumlas im Cenariusdickicht in den Wäldern von Terokkar zurück.", progress = "Wir hätten sie nie zum Abendessen einladen sollen, so viel ist sicher!\n\nOder wir hätten zumindest auf ein paar Gänge vor dem Dessert, dass sie uns mitgebracht haben, bestehen sollen!", completion = "Es ist besser so. Wenn es keine zivilisierte Einladung annehmen kann, dann ist es das auch nicht wert.\n\n<Aufseher Baumlas schaut Euch kurz verwirrt an.>\n\nWer seid Ihr und was wollt Ihr hier? Ihr müsst von hier verschwinden, bevor es zu spät ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[9954] = { id = 9954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corkis Lösegeld", description = "<Arechron zeigt Euch einen rußverschmierten Brief.>\n\nIch habe gerade diesen Brief erhalten. Er ist von einem Ogerstamm, die sich selbst Totschläger nennen. Sie herrschen über die nordwestlichen Gebiete von Nagrand. Hier steht, dass sie Corki in ihrer Gewalt haben, und sie drohen ihn aufzufressen, wenn wir nicht kooperieren. Nunja, Corki ist ein Dummkopf, aber er gehört zur Familie. Würdet Ihr ihn retten, {name}?\n\nIch nehme an, dass er in einem Käfig auf dem Totschlägerhügel eingesperrt ist. Dort solltet Ihr zuerst nachsehen.", sourceObjective = "Arechron möchte, dass Ihr Corki auf dem Totschlägerhügel findet.", completion = "Diesmal haben sie mich gut eingesperrt, {name}. Der König der Totschläger, Cho'war, hat den Schlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9955] = { id = 9955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war der Plünderer", description = "Sie nennen ihn Cho'war den Plünderer, {name}. Er ist der Oger, der die Gronn, die über die Oger geherrscht hatten, vertrieben hat. Ihr könnt mir ruhig glauben, dass er mächtig ist!\n\nDer Chef hat gesagt, dass Cho'war in der großen Höhle wohnt - wo immer das auch sein mag... Besorgt diesen Schlüssel und holt mich hier raus! Wenn wir das hier überleben, wird mein Vater Euch sicher reich belohnen! Geht zu ihm sobald ich frei bin.", sourceObjective = "Corki möchte, dass Ihr Cho'wars Schlüssel besorgt, um ihn aus dem Käfig zu befreien. Kehrt zu Arechron in Telaar zurück, falls Ihr Erfolg haben solltet.", completion = "Danke, {name}. Ich habe Corki zu den Nachtelfen im Schergrat geschickt. Hoffentlich gelingt es ihnen, ihn vom Ärger fern zu halten.\n\nWegen der Belohnung...", sourceObjectiveStatus = "unverified-source-field" }
quests[9956] = { id = 9956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überfallene Karawane", description = "Ich war bei einer Karawane dabei, die Vorräte zur Oreborzuflucht in den Zangarmarschen bringen sollte. An der Grenze zu den Marschen wurden wir jedoch von einer hinterlistigen Truppe von Totschlägerogern überfallen. Sie haben die anderen getötet und mich sowie all unsere Vorräte beschlagnahmt.\n\nZum Glück haben sie vergessen, meinen Käfig zu verriegeln. Als sie eingeschlafen waren, bin ich geflohen.\n\nEs ist zwar zu spät für meine Kameraden, aber wir könnten die gestohlenen Vorräte wirklich gebrauchen. Den Totschlägerhügel findet Ihr in den nordwestlichen Bergen von Nagrand.", sourceObjective = "Jägerin Kima in Telaar in Nagrand möchte, dass Ihr 10 Vorratskisten von Telaar wiederbesorgt.", progress = "Ich komme mir so dumm vor. Archerons Sohn, Corki, hat mich gefragt, was los ist, und ich habe es ihm gesagt. Jetzt ist er schon wieder verschwunden!", completion = "Erstaunlich! Wie habt Ihr es geschafft, all das alleine zurückzutragen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9957] = { id = 9957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts in den Wäldern von Terokkar gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Es gibt viele Wege dorthin, aber der kürzeste führt den Weg nach Süden entlang. Biegt die Straße nach Osten von Shattrath ab, wenn Ihr im Wald seid.", sourceObjective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Zuflucht Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9960] = { id = 9960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "Hey Ihr da, {class}! Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", sourceObjective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Steinbrecherfeste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9961] = { id = 9961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist los mit dem Cenariusdickicht?", description = "{class}, ich habe eine eilige Aufgabe für Euch. Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört. Das ist sehr merkwürdig, da sie sich normalerweise alle paar Tage bei uns melden.\n\nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.", sourceObjective = "Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass Allerias Feste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9962] = { id = 9962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Schmetterzehe", description = "Seid Ihr bereit für den ersten Kampf? Wenn Ihr soweit seid, gebt mir Bescheid und ich bringe die Dinge ins Rollen. Ihr müsst nur im Ring des Blutes auf Euren ersten Gegner warten.\n\nEuer erster Herausforderer wird Schmetterzehe sein, ein grausamer Grollhuf.\n\nViel Glück! Ich hoffe, Ihr habt ein paar Freunde mitgebracht.\n\nUnd denkt daran, der Kampf ist erst zu Ende, wenn Ihr oder Euer Gegner mit dem Gesicht nach unten auf dem Boden liegt.", sourceObjective = "Besiegt Schmetterzehe. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Hm, nicht schlecht. Gar nicht schlecht... Ihr habt Potenzial, Kleiner. Hier habt Ihr etwas Gold für Eure Taschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9967] = { id = 9967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Die Blaumänner", description = "Im nächsten Kampf werdet Ihr auf gleich zwei Gegner treffen, Zwillinge um genau zu sein. Sie nennen sich selbst die \"Blaumänner\".\n\nEs ist noch nicht zu spät, um zu kneifen, {name}. Ich könnte das verstehen.\n\nAber wenn Ihr bereit seid für ein wenig Action, tretet in den Ring des Blutes und wartet auf die Zwillinge der Finsterblut.\n\nDer Letzte, der noch steht, hat gewonnen!", sourceObjective = "Besiegt die Zwillinge der Finsterblut, die sich selbst die Blaumänner nennen. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Ich gebe zu, dass ich nicht geglaubt habe, dass Ihr eine Chance hättet, {name}! Das war beeindruckend! Wie wär's mit einem weiteren Kampf? Gurgthock hat den perfekten Gegner für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9968] = { id = 9968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Energien", description = "Etwas Merkwürdiges hat die Teromotten des Dickichts verändert.\n\nWo einst eine Vielfalt von Arten herrschte, sind jetzt nur noch die Teromotten übrig. Und während sie früher friedlich waren, sind sie jetzt sehr aufgeregt und greifen alles an, was ihnen zu nahe kommt.\n\nIch muss die bösartigen mit den normalen Motten vergleichen. Bringt mir ein paar Exemplare von beiden Sorten. Die gewöhnlichen Teromotten findet Ihr im Süden und im Norden.\n\nIch bin mir sicher, dass dies mit dem Tod der Druiden zusammenhängt.", sourceObjective = "Sammelt 4 Teromottenproben und 4 Proben einer bösartigen Teromotte. Kehrt dann zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar zurück.", progress = "Habt Ihr meine Proben?", completion = "Merkwürdig. Die Proben der bösartigen Teromotten enthalten etwas, das sich wie reines Mana anfühlt.\n\nWie es scheint hinterließ das, was all die Tode verursacht hat, ein starkes Energiefeld. Aber aus irgendeinem Grund hat es die Teromotten nicht umgebracht, sondern nur aufgewühlt.\n\nEs scheint, als wäre diese merkwürdige Energie ein Nebenprodukt dessen, was das Gebüsch angegriffen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9970] = { id = 9970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Rokdar der Zerklüftete", description = "Das wird ein harter Kampf, {name}. Habt Ihr vielleicht ein paar Freunde, die Euch helfen können? Den Ogern ist es gelungen, einen Riesen namens Rokdar aus dem Schergrat hierher zu bringen! Glaubt mir, Ihr werdet ein paar Freunde brauchen, er scheint unbesiegbar zu sein! Er ist hart wie Stein - im wahrsten Sinne des Wortes!\n\nWenn Ihr immer noch gegen ihn antreten möchtet, tretet in den Ring des Blutes und er wird kommen.", sourceObjective = "Besiegt Rokdar den Zerklüfteten. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Ihr habt die Oger zum Schwitzen gebracht, Kleiner. Diesmal bekommt Ihr noch etwas dazu. Benutzt nicht alles auf einmal!\n\nSeid Ihr bereit für einen weiteren Kampf? Gurgthock setzt die ganze Bank auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[9971] = { id = 9971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise im Dickicht", description = "Ich habe keine Ahnung, was all die Druiden hier getötet hat. Ich war ein paar Tage unterwegs, um die Knochenwüste im Süden zu untersuchen.\n\nBitte, Ihr müsst mir helfen herauszufinden, was hinter dieser furchtbaren Tragödie steckt. Geht zum Dickicht und haltet nach einem Hinweis Ausschau, der uns weiterhelfen könnte. Als ich kurz dort war, hätte ich schwören können, dass ich einen toten Zerschlagenen und ein merkwürdiges Ding neben ihm gesehen habe.\n\nUnd habt keine Angst vor Baumlas - er ist vielleicht durch die Geschehnisse verrückt geworden, aber ich glaube, er ist harmlos.", sourceObjective = "Untersucht das merkwürdige Objekt neben der Leiche eines Zerschlagenen um herauszufinden, was hinter der Tragödie beim Cenariusdickicht steckt. Kehrt dann zu Erdbinder Tavgren außerhalb des Dickichts in den Wäldern von Terokkar zurück.", completion = "Ich hatte also Recht. Die Leiche eines Zerschlagenen? Und Ihr sagt, dass da tatsächlich ein komisches Objekt auf dem Boden neben ihm war?\n\nDas macht keinen Sinn. Was würde einer von ihnen denn hier wollen? Und was war das für ein Ding, das er dabei hatte?\n\nHat es vielleicht all die Tode verursacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[9972] = { id = 9972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Skra'gath", description = "Ihr bringt sie ja reihenweise um, <Kleiner/Kleine>! Dieses Mal haben sie einen Profi für den Kampf. Sie sagen er sei ein Leerenfürst oder so was... Sie wollen Euch auf keinen Fall gegen ihren Champion kämpfen lassen. Habt Ihr gehört wie Mogor, das Fallobst, Euch angekläfft hat? Die Wetten stehen astronomisch hoch!\n\nSteigt in den Ring und haut ihn um!", sourceObjective = "Besiegt Skra'gath. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", completion = "KLEINER! KLEINER IHR HABT ES GESCHAFFT! Als nächstes kommt der große Kampf! Die Meisterschaft!\n\nOk, locker bleiben. Wir wollen ja nicht, dass die Oger erfahren, dass hier was im Busch ist. Schließlich bekomme ich ja auch meinen Anteil daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[9973] = { id = 9973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Champion der Totschläger", description = "Sie mussten den Champion aus den Gladiatorengruben im Schergrat einschiffen. Dort hat er mit den Bergriesen trainiert - mit gleich dreien auf einmal!\n\nWenn Ihr gegen ihn gewinnt, seid Ihr der neue Champion. Glaubt Ihr, Ihr habt eine Chance? Könnt Ihr das schaffen? Sagt mir nur Bescheid, dann setze ich mein Haus auf Euch.\n\nJetzt steigt in den Ring und gewinnt!", sourceObjective = "Besiegt den Champion der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener, um Eure Belohnung zu erhalten.", completion = "Oh je, Mogor hat sein Kampfrecht als Held der Totschläger eingefordert. Ihr müsst gegen ihn kämpfen!\n\nNiemand hat je behauptet, dass die Totschläger gute Verlierer... äh... Oger wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[9977] = { id = 9977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Die letzte Herausforderung", description = "<Gurgthock zählt seinen riesigen Berg Gold.>\n\nIhr habt viel Geld eingebracht, <Kleiner/Kleine>. Wenn Ihr Mogor besiegt, verspreche ich, dass es sich für euch lohnen wird. Die ganzen Schmerzen, die Ihr im Ring des Blutes aushalten musstet, werden sich bezahlt machen.\n\nJetzt geht da rein und zeigt diesen Ogern, was in Euch steckt!", sourceObjective = "Besiegt Mogor, Held der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Gurgthock hat doch gesagt, dass es sich bezahlt machen wird, Kleiner. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[9978] = { id = 9978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln", description = "Ich bin mir nicht sicher, was das zu bedeuten hat, aber ich weiß, wie wir an weitere Hinweise kommen können.\n\nEmpoor ist ein Händler der Zerschlagenen, der mit allen Arten von Waren und Informationen handelt. Wenn wir ihn zum Reden bringen könnten, bin ich mir sicher, dass er etwas Interessantes zu sagen hätte.\n\nEr reist auf der Straße zwischen Tuurem und Shattrath hin und her. Seid aber vorsichtig, er hat einen Leibwächter.", sourceObjective = "Findet Empoor. Er hält sich auf der Straße zwischen Tuurem und Shattrath in den Wäldern von Terokkar auf. Bringt ihn dazu, Euch zu erzählen, was Ihr wissen wollt.", completion = "Gut, gut... Ich sage Euch, was ich weiß, aber viel ist das nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9979] = { id = 9979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windhändler Lathrai", description = "Ich wurde gebeten, ein paar Kästen mit Waren bei einem Astralen in Shattrath abzuholen und auszuliefern.\n\nAls ich ihn das letzte Mal gesehen habe, stand er außerhalb der Taverne Weltenend im Unteren Viertel. Sein Name ist Windhändler Lathrai, mehr weiß ich nicht!\n\nWenn Ihr mehr wissen wollt, dann fragt ihn selbst!", sourceObjective = "Sprecht mit Windhändler Lathrai in der Nähe der Taverne Weltenend im unteren Viertel in Shattrath.", completion = "Ja? Wie kann ich Euch diesmal helfen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9982] = { id = 9982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9983] = { id = 9983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9984] = { id = 9984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Deirom gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Thander erwähnt hat, dass Andarl die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Andarl in Allerias Feste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9985] = { id = 9985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Dugar gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Rokag erwähnt hat, dass Kurgatok die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Kurgatok in der Steinbrecherfeste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9986] = { id = 9986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Thander in Allerias Feste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9987] = { id = 9987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Rokag in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9988] = { id = 9988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund eines Gecken", description = "Lasst Euch von Thander und seinem Gefolge nicht täuschen. Sie sehen vielleicht aus wie eine Gruppe von Furcht einflößenden Kriegern, aber sie sind nichts als eine Bande von Gecken!\n\nUnd sie lassen sich in der Öffentlichkeit nicht ohne ihre Hüte sehen. Das sind ganz schicke Teile aus Filz und Fell, mit den ausgefallensten Federn, die Ihr je gesehen habt.\n\nDie begehrtesten Federn stammen natürlich von den Arakkoa, und mein Vorrat geht langsam zur Neige. Ich würde Euch bezahlen, wenn Ihr sie für mich sammelt.", sourceObjective = "Bringt 30 Arakkoafedern zu Ros'eleth in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9989] = { id = 9989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Geister", description = "Als ich in die Scherbenwelt kam und meine Ohren den Stimmen seiner Geister geöffnet habe, war ich erstaunt, was ich zu hören bekam. Nach einiger Zeit fand ich auch heraus, welche Geister ich nicht hören konnte.\n\nTrotz all meiner Versuche habe ich niemals mit den Geistern der Arakkoaahnen Kontakt aufnehmen können. Ihre Magie unterscheidet sich grundlegend von unserer, aber ich bin mir nicht sicher, ob ihre Geister außerhalb meiner Reichweite liegen.\n\nBringt mir die Federn vieler Arakkoa. Vielleicht kann ein Zeichen ihres Volks die nötige Verbindung herstellen.", sourceObjective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9990] = { id = 9990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung von Tuurem", description = "Wisst Ihr, jetzt, da Ihr es sagt, erinnere ich mich daran, dass ich Empoor vor etwa einem Monat mehrere Kästen mit merkwürdigen und fremdartigen Bauteilen verkauft habe. Ich weiß nicht, wozu sie gut sind, aber ich weiß, dass sie nach Tuurem geliefert werden sollten.\n\nVielleicht sind dort ja noch ein paar Kästen davon?", sourceObjective = "Findet den versiegelten Kasten und bringt ihn zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar.", progress = "Welche Neuigkeiten bringt Ihr, {name}?", completion = "Astrale? Waren nach Tuurem? Fremdartige Bauteile? Und ein Blutelf, der den letzten Kasten zum Posten der Feuerschwingen bringen wollte?\n\nWas soll das alles bedeuten?! Was hat das mit dem Schicksal der Druiden im Cenariusdickicht zu tun?\n\nIch glaube, wir sollten einmal einen Blick in den Kasten werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9991] = { id = 9991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspektion des Lagers", description = "Wenn Ihr meine Augen sein wollt, müsst Ihr sehr sorgfältig sein. Nethrandamus wird Euch durch die Lager der Legion führen, aber Ihr müsst alles, was Ihr seht, katalogisieren. Selbst das kleinste Detail, und wenn Euch noch so unwichtig erscheint, kann für unsere Zwecke hilfreich sein.\n\nZuerst möchte ich, dass Ihr notiert, welchen Aufbau das Lager hat und wie seine Verteidigungsmaßnahmen aussehen.\n\nNethrandamus ist bereit, wenn Ihr es seid, {name}. Habt keine Angst, er wird Euch beschützen.", sourceObjective = "Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist.", progress = "Noch nie auf einem Netherdrachen geflogen, was?", completion = "Ausgezeichnete Arbeit, {name}! Jetzt haben wir einen Ausgangspunkt um unseren Gegenangriff zu planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9992] = { id = 9992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembasamen", description = "Sind die Bäume des Waldes nicht wunderschön? Ich habe mich schon oft gefragt, ob sie wohl auch in Azeroth wachsen würden.\n\nIch scheue mich jedoch davor, Keimlinge zurückzuschicken. Es ist ein anstrengender Weg und sie sind viel schwieriger zu transportieren als ein Sack mit Samen. Die Samenkörner wachsen in harten Zapfen, die von den Ästen der Bäume fallen, wenn sie reif sind.\n\nWenn Ihr auf Euren Reisen ein paar dieser Zapfen findet, könntet Ihr mir dann ein paar Samenkörner bringen?", sourceObjective = "Sammelt 30 Olembasamenkörner und kehrt dann zu Ros'eleth in Allerias Feste zurück.", progress = "Ich habe eine Samenkornsammlung angefangen, aber ich werde Hilfe brauchen, bis ich genügend zusammen habe, um sie nach Sturmwind zu schicken.", completion = "Vielen Dank für diese Samenkörner. Ich habe schon fast genügend zusammen, um eine erste Ladung zurückzuschicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[9993] = { id = 9993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembaöl", description = "Die öligen Samen der Olembabäume könnten sich als sehr wertvoll erweisen. Ich würde gern eine größere Menge davon sammeln und schauen, was ich daraus machen kann.\n\nStellt Euch nur vor, da steht ein ganzer Wald mit Bäumen, die so viele Samen produzieren, die alle ungenutzt bleiben. Mir ist egal, ob ich nur Salatöl, Waffenöl oder Lampenöl daraus herstellen kann, ich werde ihre Verschwendung nicht dulden!\n\nBringt mir alle Samen, die Ihr von den Olembazapfen sammeln könnt. Sie liegen hier überall.", sourceObjective = "Bringt 30 Olembasamenkörner zu Rakoria in der Steinbrecherfeste.", progress = "Habt Ihr ein paar Samenkörner für mich?", completion = "Das ist ein guter Anfang, aber wir werden noch mehr davon brauchen, wenn wir eine angemessene Menge Öl herstellen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9994] = { id = 9994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste im Südosten bringen. Vielleicht hat sie ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.\n\nJa, wie ich befürchtet habe. Ich glaube, das sind Bombenteile. Unsere Augen und Ohren in Shattrath haben uns informiert, dass einige Astrale verbotene Waren aus anderen Dimensionen, mit denen sie in Kontakt stehen, einführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9995] = { id = 9995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Tooki in die Steinbrecherfeste im Südosten bringen. Vielleicht hat er ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Tooki in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.", sourceObjectiveStatus = "unverified-source-field" }
quests[9996] = { id = 9996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Norden und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Leutnant Meridian bei Allerias Posten in den Wäldern von Terokkar zurück.", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9997] = { id = 9997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Nordosten und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar zurück.", progress = "Berichtet. Was bringt Ihr Neues vom Posten der Feuerschwingen?", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9998] = { id = 9998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerspenstige Nachbarn", description = "Thander ist über die Ankunft der Höllenorcs bei den Ruinen vor Kurzem sowohl überrascht als auch besorgt. Sie haben keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren.\n\nDie Bauarbeiten laufen Tag und Nacht, {name}. Ich habe ein paar meiner zuverlässigsten Agenten losgeschickt, um die Situation zu überwachen, aber wir können uns keine Verzögerungen leisten. Geht gegen ihre Arbeiter vor und sucht dann nach Theloria Dämmermantel bei Allerias Posten nördlich der Ruinen der Knochenmalmer. Sie wird Euch weitere Anweisungen geben.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Theloria Dämmermantel bei Allerias Posten.", completion = "<Die Hochelfe nickt.>\n\nEs ist ein guter Anfang, aber Bertelm hatte Recht, Euch zu mir zu schicken. Ich habe eine Entdeckung gemacht, die die Anwesenheit der Höllenorcs hier erklären könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9999] = { id = 9999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel auf Zeit", description = "Solange die Transporter noch stehen, ist nichts, was wir gegen die Konstruktionslager unternehmen, von Dauer. Wir müssen einen Weg finden, die Gebäude der Legion zu zerstören.\n\nIch brauche Zeit, um einen Angriffsplan auszuarbeiten. Wenn Ihr die Ingenieure und Tüftler eine Weile beschäftigen könntet, würde das ihre Fortschritte verlangsamen, und ich hätte die Zeit, die ich benötige.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo'arg und 8 Tüftler der Gan'arg tötet.", completion = "Wie ich es mir dachte. Es gibt keinen normalen Weg, Teufelsstahl zu zerstören. Es ist aber noch nicht alles verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[10000] = { id = 10000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unangenehme Gesellschaft", description = "Unsere Streitkräfte in Thrallmar dachten, sie hätten die Höllenorcs der Höllenfeuerzitadelle unter Kontrolle, aber die Neuankömmlinge in den Ruinen im Osten sagen etwas anderes.\n\nWir können ihnen nicht erlauben, hier Fuß zu fassen. Rokag hat Schattenpirscher Kaide zu den Ruinen geschickt, um sie zu beobachten, aber wir müssen sie aufhalten, bevor sie es sich zu bequem machen.\n\nGeht zu den Ruinen, dezimiert ihre Peons und haltet bei den Bäumen im Norden nach Kaide Ausschau. Er wird Euch sagen, wo Ihr danach hingehen sollt.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Schattenpirscher Kaide.", progress = "Ich wollte gerade einen Bericht zu Rokag schicken und einen Angriff vorschlagen, aber wie ich sehe ist das nicht mehr nötig.", completion = "Um die Höllenorcs aufzuhalten müssen wir schon mehr tun, als ihre Arbeiter zu töten. Ich habe eine Entdeckung gemacht, die vielleicht erklären kann, warum sie hier sind, und die mich in meiner Überzeugung bestätigt, dass wir schnell handeln müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10001] = { id = 10001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterplaner", description = "Alle Konstruktionslager haben einen Meisterplaner. Der Meisterplaner bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt.\n\nWir brauchen die Blaupausen des Meisterplaners. Mit solch detaillierten Informationen könnten wir einen meiner Bekannten dazu bewegen, uns etwas Unterstützung zu schicken.\n\nSucht den Meisterplaner der Mo'arg und stehlt seine Blaupausen. Er wird sich hinter den Konstruktionen aufhalten.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt.", progress = "Bleibt auf jeden Fall von den Vorarbeitern fern. Sie dürfen nichts von Eurer Anwesenheit mitbekommen. Die Folgen könnten verheerend sein!", completion = "Mein Bekannter kennt hoffentlich einen Weg, die Lager zu zerstören. Er war schließlich mal ein Ingenieur der Legion...", sourceObjectiveStatus = "unverified-source-field" }
quests[10002] = { id = 10002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Theloria Dämmermantel zurück.", completion = "<Theloria nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[10003] = { id = 10003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Schattenpirscher Kaide zurück.", completion = "<Kaide nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.\n\nWenn die Zeit gekommen ist, werde ich Rokag von unseren Fortschritten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10004] = { id = 10004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld und Verständnis", description = "Nehmt die Blaupausen und reist nach Shattrath in den Wäldern von Terokkar. Wenn Ihr in Shattrath seid, geht ins Untere Viertel sucht nach einem Mo'arg namens Sal'salabim. Er ist wahrscheinlich an der Bar und ertränkt seine Sorgen.\n\nDa fällt mir ein, dass Ihr ihn wahrscheinlich überreden müsst, uns zu helfen. Versucht ihm viel Geduld und Verständnis entgegenzubringen. Wenn das nichts hilft, dann versucht es mit Gewalt.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal'salabim in Shattrath bringt und ihn überredet, euch zu helfen.", progress = "<Sal'salabim kratzt sich am Kopf.>\n\n[Dämonisch] Ik il romath sardon.", completion = "Beruhigt Euch, Schätzchen, Sal'salabim wird helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10005] = { id = 10005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10006] = { id = 10006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10007] = { id = 10007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "So wie ich Thander und Bertelm kenne, werden sie nicht dulden, dass eine feindliche Macht so ein großes Lager direkt vor unserer Haustüre errichtet. Aber sie zu bitten, ein paar Leute ihrer Garnison zu schicken, um das Lager anzugreifen, steht auch nicht zur Debatte. Wir wären dann viel zu leicht angreifbar.\n\nWir müssen uns also selbst darum kümmern, die Bedrohung durch die Bauarbeiten der Höllenorcs zu verringern. Tötet alle von ihnen, die Ihr könnt, und ich sehe mich solange nach Verstärkung um.", sourceObjective = "Tötet 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer und kehrt dann zu Theloria Dämmermantel zurück.", completion = "Langsam sehen die Dinge besser aus. Wenn wir die Höllenorcs daran hindern können, ihre Kumpel hier zu unterstützen, können wir den Posten unter Kontrolle halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10008] = { id = 10008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was in Terokkar geschieht, bleibt in Terokkar", description = "Wenn Thrallmar erfährt, dass sie es nicht geschafft haben, die Höllenorcs unter Kontrolle zu halten, werden wir hier bald viel Gesellschaft haben. Ehrlich gesagt bin ich mir nicht sicher, ob ich so viel Aufmerksamkeit möchte, deswegen behalten wir dieses kleine Problem für uns, verstanden?\n\nWenn wir den Höllenorcs genug Verluste beibringen können, besteht die Möglichkeit, dass niemand außerhalb der Steinbrecherfeste von ihrer Anwesenheit erfährt.\n\nMarschiert da rein, schwingt Eure Waffe, wedelt mit der Hand - oder was auch immer Ihr tut - und tötet die Höllenorcs!", sourceObjective = "Schattenpirscher Kaide möchte, dass Ihr 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer tötet.", progress = "Bitte sagt mir, dass ich nicht den Falschen auf diese Mission geschickt habe...", completion = "Ich weiß, dass Ihr schon weit gereist seid, {name}, aber manche Geschichten sollten das Land niemals verlassen, haben wir uns verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10009] = { id = 10009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schädel spalten", description = "<Sal'salabim lacht.>\n\nDas Sal'salabims Entwurf.\n\n<Sal'salabim zeigt auf die Architektur und die Anordnungen auf den Blaupausen.>\n\nSchaut Türme an. Dämonenjäger kann nicht sehen, oder? Armer, armer Altruis. Er weinen wenn er Augen hätte, oder?\n\nJa, Sal'salabim helfen, aber erst Ihr helfen Sal'salabim.\n\n<Sal'salabim gibt Euch einen Ordner.>\n\nDiese Wesen schulden Sal'salabim Gold. Viel Gold. Gehen für Sal'salabim eintreiben. Sie werden nicht einfach rausrücken Sal'salabims Gold. Müssen kämpfen, aber Ihr stark. Ihr besiegen Sal'salabim!", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch'kuschs Schulden und Floons Schulden eintreibt.", progress = "Ihr ja nicht kommen zurück ohne Sal'salabims Gold!", completion = "Nun, Geschäft sein Geschäft, aber wenn Sal'salabim Euch sagen, Ihr nicht böse werden, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[10010] = { id = 10010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So einfach ist das?", description = "<Sal'salabim zeigt auf die Blaupause.>\n\nSeht Ihr, wo Teufelskanonen sind?\n\n<Sal'salabim zeichnet einen Pfeil, der einen Richtungswechsel anzeigt.>\n\nIhr dreht Teufelskanone um und richtet sie auf Gebäude.\n\nWartet! Nicht durchdrehen! Ihr wisst etwas nicht. Vorarbeiter haben Schlüssel, um Kanonen zu drehen. Ihr braucht erst Schlüssel! Einer von jedem Vorarbeiter!\n\nNicht so leicht, was?\n\nBringt Information zurück zu Altruis.", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt.", completion = "Natürlich! Wir werden sie mit ihren eigenen Waffen schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10011] = { id = 10011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: zerstört", description = "Sammelt Euren Mut, {name}. Ihr werdet ihn brauchen, wenn Ihr einem Vorarbeiter gegenübersteht.\n\nSobald Ihr bereit seid, sucht und tötet die Vorarbeiter in jedem Lager. Nehmt ihre Schlüssel und benutzt sie, um die Kanonen umzudrehen. Schießt damit auf die Lager. Kehrt zu mir zurück, wenn die Lager zerstört sind.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört.", progress = "Schon fertig?", completion = "Wir haben gesiegt! Das Vorrücken der Legion wurde gebremst!\n\nIch biete Euch eine Auswahl an Belohnungen für Eure heldenhaften Taten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10012] = { id = 10012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenorcpläne", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Bertelm mehr über dieses merkwürdige Bündnis. Ihr beschließt, zu Allerias Feste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Bertelm in Allerias Feste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Bertelm nimmt die Pläne und schaut sie an.>\n\nWenn Ihr mir diese Pläne nicht gebracht hättet, hätte ich behauptet, dass Ihr irre seid, aber hier steht es ganz deutlich. Die Höllenorcs sind nicht nur hier, um den Blutelfen zu dienen, sie haben sogar den Auftrag, uns abzulenken.\n\nDiese Pläne werfen mehr Fragen auf, als sie beantworten, aber nun können wir uns besser vorstellen, womit wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10013] = { id = 10013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungesehene Hand", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Rokag mehr über dieses merkwürdige Bündnis. Ihr beschließt, zur Steinbrecherfeste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Rokag in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Rokag nimmt die Pläne und schaut sie an.>\n\nKaide hatte also Recht! Diese Höllenorcs führen etwas im Schilde. Ich hätte jedoch nie gedacht, dass sie mit den Blutelfen zusammenarbeiten.\n\nLaut diesen Plänen sollen die Höllenorcs uns beschäftigen... aber warum? Das sind beunruhigende Nachrichten, {name}. Gut, dass Ihr mir die Pläne gleich gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10014] = { id = 10014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen Allerias Feste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Meridian in Allerias Posten in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10015] = { id = 10015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen die Steinbrecherfeste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10016] = { id = 10016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldworgschwänze", description = "Seid Ihr auf Euren Reisen den Waldworgs begegnet? Ich hatte die Gelegenheit, sie zu beobachten, als ich einige der nördlichen Regionen des Waldes kartografiert habe. Ich würde Euch nicht empfehlen, zu nahe an sie heranzugehen, es sei denn, Ihr seid bereit für einen Kampf.\n\nSie haben keine Angst und scheuen vor nichts zurück, um ihr Territorium zu verteidigen.\n\nEs ist nicht verwunderlich, dass diese Kreaturen solch wundervolle Schwänze haben. Ich habe versucht, ein paar von ihnen zu sammeln, um einen neuen Mantel zu schneidern, aber die Worgs entkommen meinen Fallen dauernd. Wollt Ihr mir helfen?", sourceObjective = "Bertelm in Allerias Feste möchte, dass Ihr ihm 12 Waldworgschwänze bringt. Die Schwänze können von Waldworgs oder Waldworgalphas stammen.", progress = "Wie ich sehe habt Ihr die Gefahren des Waldes überlebt. Habt Ihr ein paar Schwänze für meinen Umhang?", completion = "Ah, gut gemacht, Freund. Sie sind noch feiner, als ich gedacht habe. Sie werden sicher einen schönen Umhang abgeben.\n\n<Bertelm schaut zum Gasthaus hinüber.>\n\nJa, das wird ein schöner Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10017] = { id = 10017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Vorräte", description = "Immer mehr Flüchtlinge kommen Tag für Tag durch die Tore von Shattrath. Viele sind so schwer verwundet, dass es an ein Wunder grenzt, dass sie es überhaupt hierher geschafft haben.\n\nAls Heiler der Aldor kann ich die meisten gewöhnlichen Wunden verarzten. Vergiftete Wunden sind jedoch problematischer, da mir langsam die Vorräte an Gegengift ausgehen.\n\nBringt mir ein paar Schreckensgiftbeutel von den Schreckensspinnen hier in der Gegend, damit ich mehr davon herstellen kann. Ihr findet eine Gruppe von diesen Spinnen im Südosten von Terokkar.", sourceObjective = "Bringt 8 Schreckensgiftbeutel zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Giftbeutel, {name}? Diese Flüchtlinge können nicht mehr lange warten.", completion = "Ihr habt meinen Dank, {name}. Die Aldor werden von Euren Taten erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10018] = { id = 10018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Wolfgeistes", description = "Vor Generationen, als die Orcs die Wälder von Terokkar noch ihr Zuhause nannten, spielte der Wolfgeist eine große Rolle in ihrem Leben. Als die Orcs fortgingen, brauchten sie den Wolfgeist nicht mehr und haben ihn zurückgelassen.\n\nMit der Zeit wurde der Geist einsam und verließ die Wälder ebenfalls.\n\nIch glaube, dass ich den Wolfgeist zu seinem ursprünglichen Heim zurückbringen kann, wie auch wir Orcs zurückgekehrt sind. Das Ritual erfordert, dass ich ein Gewand aus den Pelzen der Wölfe der Wälder schneidere, um den Wolfgeist zu seinem Zuhause zurück zu geleiten.", sourceObjective = "Bringt 12 Waldworgpelze zu Malukaz in der Steinbrecherfeste.", progress = "Konntet Ihr alle Pelze, die ich benötige, finden?", completion = "Die Pelze sind perfekt, {name}! Ich hätte keine besseren bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10019] = { id = 10019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Giftbeutel", progress = "Viele Flüchtlinge brauchen immer noch Heilung für ihre vergifteten Wunden. Habt Ihr mir noch mehr Giftbeutel gebracht, {name}?", completion = "Ihr habt meinen Dank, {name}. Die Naaru haben diese unglücklichen Seelen unter ihren Schutz gestellt. Es wäre sehr schade, wenn sie es bis Shattrath geschafft hätten, um dort an ihren Wunden zu verenden." }
quests[10020] = { id = 10020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heilmittel für Zahlia", description = "Die Frau rechts von mir hat eine schwere Kopfverletzung erlitten. Sie hat zwar überlebt, aber ihr Augenlicht verloren.\n\nEin traditionelles Heilmittel meines Volkes verlangt das Blut eines sehr alten Basilisken.\n\nUnglücklicherweise leben die Basilisken von Terokkar wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange.\n\nEs gibt jedoch einen Basilisken, dessen Name ich schon als Kind kannte. Er ist als Steinstarrer bekannt und soll östlich von hier leben, in der Nähe der Landesgrenze.\n\nBringt mir sein Blut, damit Zahlia wieder sehen kann.", sourceObjective = "Bringt Steinstarrers Blut zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr das Blut bekommen, {name}? Ohne das Blut wird Zahlia ihrem Sohn nie wieder in die Augen schauen können.", completion = "Vielen Dank, {name}. Sich um die Notleidenden zu kümmern ist eine schwierige Aufgabe, aber sie wird auf ihre ganz eigene Weise belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10021] = { id = 10021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht wiederherstellen", description = "Vor langer Zeit war ein Großteil dieses Gebiets von den Draenei bewohnt. Wir, die Aldor, hatten den Auftrag, unsere heiligen Stätten und Altäre zu beschützen. Doch seitdem wurden viele davon zerstört oder von unseren Feinden eingenommen.\n\nÖstlich von hier gibt es einen Außenposten der Arakkoa. Sie haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei unserer heiligen Altäre stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht unserer Schreine zu verändern und zu schänden.\n\nBringt dies zum Arakkoaaußenposten und reinigt die drei Altäre.", sourceObjective = "Ishanah möchte, dass Ihr zum Arakkoaaußenposten östlich von Shattrath geht. Benutzt die gesegnete Phiole, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr habt meinen Dank, {name}. Wir sind die Hüter des Lichts und können unsere Pflichten nicht vernachlässigen. Nicht einmal in den schwersten Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10022] = { id = 10022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwer zu fassende Eisenkiefer", description = "Jetzt, da ich das Fell habe, das ich für mein Gewand benötige, dachte ich, dass der Pelz eines ganz bestimmten Wolfs eine schöne Kapuze für meinen Umhang abgeben würde. Stellt Euch nur vor, wie es wäre, Euren Feind im Pelz des gerissensten Raubtiers der Wälder zu sehen!\n\nIch habe bisher vergeblich versucht, Eisenkiefer zu fangen. Ich habe versucht ihn in die Enge zu treiben, ihn zu überlisten und ihn zu locken. Nichts hat geklappt.\n\nEr streunt in den nordöstlichen Gebieten des Waldes herum, und ich würde Euch angemessen belohnen, wenn Ihr schafft, was mir nie gelang.", sourceObjective = "Bringt Eisenkiefers Pelz zu Bertelm in Allerias Feste.", progress = "Hat der alte Eisenkiefer Euch übers Ohr gehauen? Oder konntet Ihr den alten Gesellen überlisten?", completion = "Ich verneige mich vor Eurem Geschick, {name}. Ihr habt Euch als herausragender Jäger bewiesen.\n\nIch werde Eure Hilfe bei der Herstellung dieses Umhangs nie vergessen. Er ist ein einzigartiges Gewand, das ich voller Stolz tragen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10023] = { id = 10023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch Eisenkiefer", description = "Ihr habt gute Arbeit beim Sammeln der ersten Pelze geleistet.\n\nDas letzte Stück der Gewandung erfordert einen ganz besonderen Pelz. Es gibt einen bestimmten Wolf, der alt und gerissen ist, und sich dadurch den Rang des Patriarchen unter den Wölfen des Waldes verdient hat. Er ist unter ihnen als Eisenkiefer, der mächtige Jäger, bekannt.\n\nIn meinen Visionen habe ich ihn im Nordosten der Wälder umherstreifen sehen. Sein Pelz in meiner Gewandung wird sicher den Pfad des Wolfgeistes erhellen.\n\nBeklagt Eisenkiefer nicht. Er wird die ihm gebührende Ehre erhalten.", sourceObjective = "Bringt Eisenkiefers Pelz zu Malukaz in der Steinbrecherfeste.", progress = "Der Geist wartet, {name}. Habt Ihr den Pelz des Patriarchen?", completion = "Der Pelz ist noch vortrefflicher, als ich erhofft hatte! Das ist ein gutes Zeichen, {name}, und die Geister werden Euch wegen Eurem Beitrag zu dieser Zeremonie wohl gesonnen sein.\n\nIch habe Euch aus dem übrigen Pelz einen Helm gemacht, {name}. Er zeichnet Euch als mächtigen Jäger und Verbündeter des großen Wolfgeists der Wälder von Terokkar aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10024] = { id = 10024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thals Visionen", description = "Unser Anführer, Voren'thal der Seher, war einst ein enger Vertrauter von Kael'thas. Seine prophetischen Visionen habe ihn gewarnt, dass Kaels Weg in der Zerstörung unseres Volkes enden würde.\n\nNormalerweise sind diese Visionen nur sehr vage und ungenau, aber unsere Alchemisten haben ein Elixier entwickelt, mit dessen Hilfe seine Visionen deutlicher werden. Unglücklicherweise erfordert das Elixier eine sehr seltene Zutat: Basiliskenaugen. Normalerweise bekomme ich sie von diesem aufgeblasenen Astralen, aber er hat mich enttäuscht.\n\nMacht Euch auf die Suche nach den Dunstschuppenbasilisken im gebirgigen Terokkar und bringt mir ihre Augen.", sourceObjective = "Bringt 8 Augen eines Dunstschuppenbasilisken zu Arkanistin Adyria in Shattrath.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Basiliskenaugen für Voren'thals Elixier?", completion = "Sie sind in tadellosem Zustand, {name}. Macht weiter so, und die Seher werden bald zu Euren Freunden zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10025] = { id = 10025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Basiliskenaugen", progress = "Um auch nur eine kleine Dosis von Voren'thals Elixier herzustellen, braucht man sehr viele Basiliskenaugen. Wenn Ihr mir mehr davon bringt, gewinnt Ihr sicher das Wohlwollen der Seher.", completion = "Ich danke Euch, {name}. Voren'thals Visionen können vielleicht eines Tages das Schicksal unseres Volks entscheiden. Wir tun gut daran, dafür zu sorgen, dass seine Visionen so klar wie möglich sind." }
